      "path": "cmd/deja/main.go",
      "content": "// Command deja indexes the session transcripts of the coding agents on this\n// machine and answers recall, blame and fix questions from them.\npackage main\n\nimport (\n\t\"bytes\"\n\t\"errors\"\n\t\"fmt\"\n\t\"io\"\n\t\"io/fs\"\n\t\"math\"\n\t\"os\"\n\t\"path/filepath\"\n\t\"regexp/syntax\"\n\t\"slices\"\n\t\"sort\"\n\t\"strconv\"\n\t\"strings\"\n\t\"sync\"\n\t\"sync/atomic\"\n\t\"syscall\"\n\t\"time\"\n\t\"unicode\"\n\n\t\"github.com/vshulcz/deja-vu/internal/digest\"\n\t\"github.com/vshulcz/deja-vu/internal/index\"\n\t\"github.com/vshulcz/deja-vu/internal/model\"\n\t\"github.com/vshulcz/deja-vu/internal/nfcfold\"\n\t\"github.com/vshulcz/deja-vu/internal/policy\"\n\t\"github.com/vshulcz/deja-vu/internal/query\"\n\t\"github.com/vshulcz/deja-vu/internal/redact\"\n\t\"github.com/vshulcz/deja-vu/internal/search\"\n\t\"github.com/vshulcz/deja-vu/internal/sources\"\n\t\"github.com/vshulcz/deja-vu/internal/termwidth\"\n\t\"github.com/vshulcz/deja-vu/internal/usage\"\n)\n\nvar version = \"dev\"\n\n// errAlreadySaid exits non-zero for a command that has already told the reader\n// what went wrong. Without it the choice was between a silent success and the\n// same sentence twice: `deja unforget x` printed \"that is not a command, here\n// is the one that is\" and exited 0, so a script that checked the code was told\n// the work had been done.\nvar errAlreadySaid = errors.New(\"already said\")\n\nfunc main() {\n\t// The detached look an interactive run started once a day (#4622).\n\tif stamp, ok := releaseLookRequested(os.Args[1:], index.DefaultDir()); ok {\n\t\trunReleaseLook(stamp, defaultDoctorVersionLookup())\n\t\treturn\n\t}\n\t// A command that lands mid-rebuild waits for the whole of it, and silence\n\t// there reads as a hang rather than as a queue (#994).\n\tinstallLockWait()\n\t// A detached warmup is index work nobody asked for at a moment somebody is\n\t// working, so it takes less than a foreground run would (#3500).\n\ttakeWarmupBudget()\n\tstopProfiling := startProfiling()\n\t// Only `deja doctor` said a newer release exists. Look at most once a day,\n\t// in the background, and only when a person is at the terminal (#4622).\n\tnotice := startReleaseNotice(os.Args[1:], briefWanted(os.Stdout) && briefWanted(os.Stderr),\n\t\tindex.DefaultDir(), time.Now(), spawnReleaseLook)\n\terr := run(os.Args[1:])\n\tif exe, exeErr := os.Executable(); exeErr == nil {\n\t\tnotice.finish(os.Stderr, exe)\n\t}\n\tvar status exitStatus\n\tif errors.As(err, &status) {\n\t\tstopProfiling()\n\t\tos.Exit(int(status))\n\t}\n\tif err != nil {\n\t\tstopProfiling()\n\t\t// Already said, on stderr, in the words that fit what happened: a\n\t\t// second sentence here would repeat it. The exit code is the point —\n\t\t// a command nobody typed correctly must not look like one that worked.\n\t\tif !errors.Is(err, errAlreadySaid) {\n\t\t\tfmt.Fprintln(os.Stderr, \"deja:\", rebuildWindowError(err))\n\t\t}\n\t\tos.Exit(1)\n\t}\n\tstopProfiling()\n}\n\n// rebuildInProgress is a seam: a test can put the process in the window\n// without racing a real rebuild.\nvar rebuildInProgress = index.RebuildInProgress\n\n// rebuildWindowError names the one state that looks like a broken store and is\n// not: a rebuild recreates the index directory, and a reader that lands in that\n// window gets `open …/manifest.gob: no such file or directory` (#822).\nfunc rebuildWindowError(err error) error {\n\tif !errors.Is(err, fs.ErrNotExist) {\n\t\treturn err\n\t}\n\tif !rebuildInProgress(index.DefaultDir()) {\n\t\t// Not a rebuild, so the manifest is missing for some other reason —\n\t\t// and on a machine where the cache cannot be created that reached the\n\t\t// reader as `open …/manifest.gob: no such file or directory`, which is\n\t\t// the shape #798 replaced everywhere else (#2267).\n\t\tif d := index.DefaultDir(); !dirExists(d) {\n\t\t\tif a := nearestExistingDir(filepath.Dir(d)); a != \"\" && !dirWritable(a) {\n\t\t\t\treturn fmt.Errorf(\"cannot create the index directory (%s) — %s is not writable; check its permissions, or point DEJA_INDEX_DIR somewhere writable\", filepath.Dir(d), a)\n\t\t\t}\n\t\t}\n\t\treturn err\n\t}\n\treturn errors.New(\"the index is being rebuilt right now — run this again in a moment\")\n}\n\nfunc loadAll(h string) []model.Session {\n\tvar ss []model.Session\n\tif h == \"\" || h == \"claude\" {\n\t\tss = append(ss, sources.LoadClaude()...)\n\t}\n\tif h == \"\" || h == \"codex\" {\n\t\tss = append(ss, sources.LoadCodex()...)\n\t}\n\tif h == \"\" || h == \"opencode\" {\n\t\tss = append(ss, sources.LoadOpencode()...)\n\t}\n\tif h == \"\" || h == \"aider\" {\n\t\tss = append(ss, sources.LoadAider()...)\n\t}\n\tif h == \"\" || h == \"gemini\" {\n\t\tss = append(ss, sources.LoadGemini()...)\n\t}\n\tif h == \"\" || h == \"cursor\" {\n\t\tss = append(ss, sources.LoadCursor()...)\n\t}\n\tif h == \"\" || h == \"antigravity\" {\n\t\tss = append(ss, sources.LoadAntigravity()...)\n\t}\n\tif h == \"\" || h == \"grok\" {\n\t\tss = append(ss, sources.LoadGrok()...)\n\t}\n\tif h == \"\" || h == \"qwen\" {\n\t\tss = append(ss, sources.LoadQwen()...)\n\t}\n\tif h == \"\" || h == \"kimi\" {\n\t\tss = append(ss, sources.LoadKimi()...)\n\t}\n\tif h == \"\" || h == \"goose\" {\n\t\tss = append(ss, sources.LoadGoose()...)\n\t}\n\tif h == \"\" || h == \"hermes\" {\n\t\tss = append(ss, sources.LoadHermes()...)\n\t}\n\treturn ss\n}\n\nfunc loadFileSources() []model.Session {\n\tvar ss []model.Session //nolint:prealloc // the count is whatever each store holds\n\tfor _, harness := range []string{\"claude\", \"codex\", \"aider\", \"gemini\", \"cursor\", \"antigravity\", \"grok\", \"qwen\", \"kimi\", \"goose\", \"hermes\"} {\n\t\tss = append(ss, loadAll(harness)...)\n\t}\n\treturn ss\n}\n\n// worksWithNoHome names the commands that never write under a home directory\n// they cannot find: they print, or they diagnose the very state the guard is\n// about, or they carry their own refusal.\n//\n// `version` and `help` write nothing at all and are what a packager runs;\n// `completion` is sourced from a shell rc file; `update` replaces the binary\n// and is how somebody gets out of a broken state; `doctor` and `sources` are\n// where every other message sends the reader to find out what deja can see;\n// and install carries #1690's own guard, whose advice is the right one for it.\nvar worksWithNoHome = map[string]bool{\n\t\"version\": true, \"--version\": true, \"-version\": true,\n\t\"help\": true, \"--help\": true, \"-h\": true,\n\t\"completion\": true, \"update\": true,\n\t\"doctor\": true, \"sources\": true,\n\t\"install\": true, \"uninstall\": true,\n}\n\n// dispatchKnows reports whether a word is a command deja runs, from either\n// half of the dispatcher: the map, and the switch above it that holds the five\n// commands taking their own argument parsing.\nfunc dispatchKnows(name string) bool {\n\tif _, ok := commands[name]; ok {\n\t\treturn true\n\t}\n\tswitch name {\n\tcase \"show\", \"last\", \"search\", \"aider\", \"goose\":\n\t\treturn true\n\t}\n\treturn false\n}\n\n// homelessRefusal answers what to do when deja cannot find a home directory\n// and nothing else says where its index goes.\n//\n// A command somebody typed says why it cannot run. A hook does not: it runs\n// unattended on every prompt, a refusal would cost the turn, and the whole\n// design of the hooks is to fail open and stay quiet (#1692). Either way\n// nothing is written, which is the part that matters — the index is a database,\n// and it was landing in whatever repository the agent was working in.\nfunc homelessRefusal(name string) (bool, error) {\n\t// Both roots: the index answers to DEJA_INDEX_DIR, and the config\n\t// directory to XDG_CONFIG_HOME, so one of them being absolute says\n\t// nothing about the other.\n\tif filepath.IsAbs(index.DefaultDir()) && filepath.IsAbs(xdgConfigHome()) {\n\t\treturn false, nil\n\t}\n\tif worksWithNoHome[name] {\n\t\t// Only a name the dispatcher will actually take: `-v` is not a\n\t\t// command, so allowlisting it let it through the guard, miss the map\n\t\t// and land in the bare-query path — which builds an index (#1692).\n\t\tif _, known := commands[name]; known {\n\t\t\treturn false, nil\n\t\t}\n\t}\n\tif strings.HasPrefix(name, \"hook-\") || name == \"statusline\" || name == \"warmup-status\" {\n\t\treturn true, nil\n\t}\n\t// The command's own name, or deja's: for a bare query the first word is\n\t// the reader's, and \"retry cannot find your home directory\" reads as if\n\t// `retry` were a command.\n\tif !dispatchKnows(name) {\n\t\tname = \"deja\"\n\t}\n\treturn true, fmt.Errorf(\"%s cannot find your home directory — set HOME, or DEJA_INDEX_DIR and XDG_CONFIG_HOME to absolute paths\", name)\n}\n\ntype command func(dir string, rest []string) error\n\nvar commands = map[string]command{\n\t\"version\":   cmdVersion,\n\t\"help\":      cmdHelp,\n\t\"--help\":    cmdHelp,\n\t\"-h\":        cmdHelp,\n\t\"--version\": cmdVersion,\n\t\"-version\":  cmdVersion,\n\t\"sources\": func(dir string, rest []string) error {\n\t\t// The command takes nothing, and --json exists on seven of its\n\t\t// neighbours — a script that reaches for it here got the\n\t\t// tab-separated table back and parsed it as JSON (#747).\n\t\tfor _, a := range rest {\n\t\t\treturn fmt.Errorf(\"sources takes no arguments — got %q\", a)\n\t\t}\n\t\tprintSources(dir)\n\t\treturn nil\n\t},\n\t\"completion\":    func(_ string, rest []string) error { return runCompletion(rest) },\n\t\"doctor\":        func(dir string, rest []string) error { return runDoctor(os.Stdout, rest, doctorLookup, dir) },\n\t\"warmup\":        cmdWarmup,\n\t\"warmup-status\": cmdWarmupStatus,\n\t\"index\":         cmdIndex,\n\t\"embed\":         runEmbed,\n\t\"bench\":         func(_ string, rest []string) error { return runBench(rest) },\n\t\"statusline\": func(dir string, _ []string) error {\n\t\treturn endLineOnTerminal(os.Stdout, func(w io.Writer) error { return runStatusline(dir, os.Stdin, w) })\n\t},\n\t\"stats\":    runStats,\n\t\"remember\": runRemember,\n\t\"promote\":  func(dir string, rest []string) error { return runPromote(dir, rest, os.Stdout) },\n\t\"rules\":    runRules,\n\t\"forget\":   runForget,\n\t\"delete\":   func(dir string, rest []string) error { return runDelete(dir, rest, os.Stdout) },\n\t\"mcp\": func(dir string, rest []string) error {\n\t\treturn serveMCPProcess(dir, os.Stdin, os.Stdout, mcpContextFlag(rest))\n\t},\n\t\"hook-prompt\": func(dir string, rest []string) error {\n\t\tif sayIfTypedByHand(\"hook-prompt\") {\n\t\t\treturn nil\n\t\t}\n\t\tplain := false\n\t\t// --mcode answers in MiniMax Code's shape (hook_mcode.go).\n\t\tmcodeHookOutput = mcodeHookFlag(rest)\n\t\tfor _, a := range rest {\n\t\t\tswitch a {\n\t\t\tcase \"--plain\", \"-plain\":\n\t\t\t\tplain = true\n\t\t\t// --copilot: the flat answer Copilot CLI reads (see hook_strict.go).\n\t\t\tcase \"--copilot\", \"-copilot\":\n\t\t\t\tcopilotHookOutput = true\n\t\t\t// --strict: ZCode discards a reply with a key it does not know,\n\t\t\t// recall and all, so the receipt line stays out (hook_strict.go).\n\t\t\tcase \"--strict\", \"-strict\":\n\t\t\t\tstrictHookOutput = true\n\t\t\t}\n\t\t}\n\t\treturn endLineOnTerminal(os.Stdout, func(w io.Writer) error { return runHookPromptMode(dir, os.Stdin, w, plain) })\n\t},\n\t\"hook-antigravity\": func(dir string, _ []string) error {\n\t\treturn runHookAntigravity(dir, os.Stdin, os.Stdout)\n\t},\n\t\"hook-session-end\": func(dir string, rest []string) error {\n\t\trunHookSessionEnd(dir, os.Stdin)\n\t\t// --json: a host that reads every hook's answer as JSON gets the\n\t\t// empty object that means \"nothing to add\" (Antigravity's Stop).\n\t\tif len(rest) > 0 && (rest[0] == \"--json\" || rest[0] == \"-json\") {\n\t\t\tfmt.Fprintln(os.Stdout, \"{}\")\n\t\t}\n\t\treturn nil\n\t},\n\t\"hook-codewhale\": func(dir string, rest []string) error {\n\t\treturn runHookCodeWhale(dir, rest, os.Stdin, os.Stdout)\n\t},\n\t\"hook-stop\": func(dir string, _ []string) error {\n\t\treturn runHookStop(dir, os.Stdin, os.Stdout)\n\t},\n\t\"hook-mcp-call\": func(dir string, _ []string) error {\n\t\trunHookMCPCall(dir, os.Stdin, os.Stdout)\n\t\treturn nil\n\t},\n\t\"hook-plan\": func(dir string, _ []string) error {\n\t\tif sayIfTypedByHand(\"hook-plan\") {\n\t\t\treturn nil\n\t\t}\n\t\treturn runHookPlan(dir, os.Stdin, os.Stdout)\n\t},\n\t\"hook-tool\": func(dir string, rest []string) error {\n\t\tif sayIfTypedByHand(\"hook-tool\") {\n\t\t\treturn nil\n\t\t}\n\t\treturn endLineOnTerminal(os.Stdout, func(w io.Writer) error {\n\t\t\treturn runHookToolMode(dir, os.Stdin, w, hookToolShapeOf(rest))\n\t\t})\n\t},\n\t\"hook-tool-after\": func(dir string, rest []string) error {\n\t\tif sayIfTypedByHand(\"hook-tool-after\") {\n\t\t\treturn nil\n\t\t}\n\t\tplain := len(rest) > 0 && (rest[0] == \"--plain\" || rest[0] == \"-plain\")\n\t\t// --copilot: the flat answer Copilot CLI reads (see hook_strict.go).\n\t\tif len(rest) > 0 && (rest[0] == \"--copilot\" || rest[0] == \"-copilot\") {\n\t\t\tcopilotHookOutput = true\n\t\t}\n\t\t// --mcode answers in MiniMax Code's shape (hook_mcode.go).\n\t\tmcodeHookOutput = mcodeHookFlag(rest)\n\t\treturn endLineOnTerminal(os.Stdout, func(w io.Writer) error { return runHookToolAfterMode(dir, os.Stdin, w, plain) })\n\t},\n\t\"check\": func(dir string, rest []string) error {\n\t\treturn runCheck(dir, rest, os.Stdin, os.Stdout)\n\t},\n\t// The screen `deja` prints on a terminal, under a name, so it can be paged,\n\t// captured into a bug report or read over a pipe — and so the obvious guess\n\t// stops being a search for the word (#2108).\n\t// The arguments were thrown away here, so `deja brief --json` printed the\n\t// human screen and exited 0 — the shape #2253 fixed for friction and\n\t// restore (#2265). statusline stays as it is on purpose: a harness runs it\n\t// on every redraw, and a refusal would land in someone's prompt.\n\t\"brief\": func(dir string, rest []string) error {\n\t\tfor _, a := range rest {\n\t\t\treturn fmt.Errorf(\"brief takes no arguments — got %q\", a)\n\t\t}\n\t\treturn runBrief(dir, os.Stdout)\n\t},\n\t\"hook-context\":    cmdHookContext,\n\t\"hook-precompact\": cmdHookPrecompact,\n\t\"wip\":             func(dir string, args []string) error { return runWIP(dir, args, os.Stdout) },\n\t\"hook-refresh\":    func(dir string, _ []string) error { runHookRefresh(dir); return nil },\n\t\"view\":            runView,\n\t\"install\":         func(dir string, rest []string) error { return runInstall(dir, rest, false) },\n\t\"uninstall\":       func(dir string, rest []string) error { return runInstall(dir, rest, true) },\n\t\"update\":          func(_ string, rest []string) error { return runUpdate(rest, os.Stdout) },\n\t\"share\":           func(dir string, rest []string) error { return runShare(dir, rest, os.Stdout) },\n\t\"resume\":          func(dir string, rest []string) error { return runResume(dir, rest, os.Stdout) },\n\t\"handoff\":         func(dir string, rest []string) error { return runHandoff(dir, rest, os.Stdout) },\n\t\"files\":           func(dir string, rest []string) error { return runFiles(dir, rest, os.Stdout) },\n\t\"restore\":         func(dir string, rest []string) error { return runRestore(dir, rest, os.Stdout) },\n\t\"friction\":        func(dir string, rest []string) error { return runFriction(dir, rest, os.Stdout) },\n\t\"secrets\":         func(dir string, rest []string) error { return runSecrets(dir, rest, os.Stdout) },\n\t\"tests\":           func(dir string, rest []string) error { return runTests(dir, rest, os.Stdout) },\n\t\"recap\":           func(dir string, rest []string) error { return runRecap(dir, rest, os.Stdout) },\n\t\"fix\":             func(dir string, rest []string) error { return runFix(dir, rest, os.Stdout) },\n\t\"how\":             func(dir string, rest []string) error { return runHow(dir, rest, os.Stdout) },\n\t\"recall\":          func(dir string, rest []string) error { return runRecall(dir, rest, os.Stdout) },\n\t\"log\":             runLog,\n\t\"sync\":            runSync,\n\t\"ctx\":             cmdCtx,\n\t// Wrappers, but only with arguments: bare `deja aider` is far more\n\t// likely someone searching for the word than someone asking to launch\n\t// an editor, and launching one from a search is not a mistake worth\n\t// making. See cmdAider/cmdGoose.\n\t\"hook-goose\": cmdGooseHook,\n\t\"hook-goose-prompt\": func(dir string, _ []string) error {\n\t\treturn refreshGooseForPrompt(dir, readHookStdin())\n\t},\n\t// The code extension `deja install reasonix-auto` registers. Reasonix\n\t// starts it and speaks JSON-RPC on its stdin; at a terminal it says so\n\t// rather than sitting on a read nobody will answer.\n\t\"reasonix-ext\": func(dir string, _ []string) error {\n\t\tif sayIfTypedByHand(\"reasonix-ext\") {\n\t\t\treturn nil\n\t\t}\n\t\treturn runReasonixExt(dir, os.Stdin, os.Stdout)\n\t},\n\t\"blame\": runBlame,\n}\n\nfunc run(args []string) error {\n\tif len(args) > 0 && args[0] == framedFlag {\n\t\treturn runFramed(args[1:])\n\t}\n\tdir := index.DefaultDir()\n\t// Before anything reads or writes: every path deja writes hangs off the\n\t// home directory, and it answers \"\" when there is none, so\n\t// `filepath.Join(\"\", \".cache\", \"deja\")` is `.cache/deja` — deja built its\n\t// index in whatever directory it happened to be run from, on the commands\n\t// an agent runs unattended as much as on the ones a person types. #1690\n\t// fixed install; this is the rest (#1692).\n\tname := \"\"\n\tif len(args) > 0 {\n\t\tname = args[0]\n\t}\n\tif stop, err := homelessRefusal(name); stop {\n\t\treturn err\n\t}\n\t// A typo in DEJA_STORES silences every store rather than narrowing to one,\n\t// and what follows reads like a machine with no history instead of like a\n\t// mistake. Checked once, before any command runs.\n\tif err := sources.StoresSelectionError(); err != nil {\n\t\treturn err\n\t}\n\tif len(args) == 0 {\n\t\t// briefWanted, not logoWanted: a reader who turned colour off still\n\t\t// has an index and a terminal, and the brief is what that reader came\n\t\t// for (#1596).\n\t\tif tuiWanted() {\n\t\t\treturn runTUI(dir)\n\t\t}\n\t\tif briefWanted(os.Stdout) {\n\t\t\treturn runBrief(dir, os.Stdout)\n\t\t}\n\t\t// Piped, the full page was 106 lines nobody asked for. Nothing deja\n\t\t// installs runs a bare deja, and the brief would build an index into a\n\t\t// pipe, so the reader gets what is indexed and where to go next (#4621).\n\t\tfmt.Print(bareDejaPointer(dir))\n\t\treturn nil\n\t}\n\tsourceInstance := os.Getenv(\"DEJA_SOURCE_INSTANCE\")\n\twarnBrokenPolicy(args[0], os.Stderr)\n\tif wantsHelp(args[1:]) {\n\t\t// `deja aider --help` is aider's: the help page promises the rest of\n\t\t// the line goes to the tool, and answering with deja's page left no\n\t\t// way to reach the tool's own short of calling it directly.\n\t\tif toolOwnsHelp(args[0]) {\n\t\t\treturn runToolHelp(args[0], args[1:])\n\t\t}\n\t\tif h := helpForCommand(args[0]); h != \"\" {\n\t\t\t// The same width the page itself respects: `deja last --help`\n\t\t\t// quotes the widest line in it, so a single command's help was\n\t\t\t// the one most likely to wrap (#1661).\n\t\t\tfmt.Print(wrapUsage(h, printableWidth(os.Stdout)))\n\t\t\treturn nil\n\t\t}\n\t\t// Not a command, so the words are a bare search, and --help after\n\t\t// them was searched for along with them.\n\t\tif !dispatchKnows(args[0]) && !strings.HasPrefix(args[0], \"hook-\") {\n\t\t\tfmt.Print(wrapUsage(helpForCommand(\"search\"), printableWidth(os.Stdout)))\n\t\t\treturn nil\n\t\t}\n\t}\n\tswitch args[0] {\n\tcase \"show\":\n\t\treturn cmdShow(dir, args[1:], sourceInstance)\n\tcase \"last\":\n\t\treturn cmdLast(dir, args[1:], sourceInstance)\n\tcase \"search\":\n\t\treturn cmdSearch(dir, args[1:], sourceInstance)\n\tcase \"aider\":\n\t\treturn cmdAider(dir, args[1:], sourceInstance)\n\tcase \"goose\":\n\t\treturn cmdGoose(dir, args[1:], sourceInstance)\n\t}\n\tif cmd, ok := commands[args[0]]; ok {\n\t\tif deferrableHooks[args[0]] {\n\t\t\treturn runHookDeferred(dir, args[0], args[1:], cmd)\n\t\t}\n\t\treturn cmd(dir, args[1:])\n\t}\n\t// A `hook-…` this build does not have is a line in a config an older deja\n\t// wrote, not a query: reading it as one ran a search on every session\n\t// start — and built the whole index to answer it — while stdout, where a\n\t// hook's output is read from, stayed empty (#2718). commandHint already\n\t// treats these names as plumbing nobody types.\n\t//\n\t// Only when a harness is calling: at a terminal this is somebody who\n\t// mistyped `hook-context`, and telling them a config calls it is a claim\n\t// about their machine that is not true — they keep the search and the near\n\t// miss every other mistyped word gets (#674). And only when it is the whole\n\t// command line: `deja hook-session timeout` is a query somebody typed, and\n\t// no harness passes a retired hook extra arguments.\n\tif len(args) == 1 && strings.HasPrefix(args[0], \"hook-\") && !stdinIsTerminal() {\n\t\t// On stderr: a harness reads stdout as the hook's answer, and on some\n\t\t// of them a bare line there lands in the model's context. This is a\n\t\t// note for whoever reads the logs, not something to inject.\n\t\t// What to do, and only what is true: install writes the hooks this\n\t\t// build has and leaves a line under a name it does not recognise where\n\t\t// it is (#2719), so pointing at it would be advice that does nothing.\n\t\tfmt.Fprintf(os.Stderr, \"deja: %q is not a hook this build has — a config still calls it on every session; that line is safe to delete\\n\", args[0])\n\t\treturn nil\n\t}\n\treturn runBareSearch(dir, args, sourceInstance)\n}\n\nfunc cmdVersion(_ string, rest []string) error {\n\tif len(rest) > 0 {\n\t\treturn fmt.Errorf(\"version takes no arguments — got %q\", rest[0])\n\t}\n\tfmt.Fprintf(os.Stdout, \"deja %s\\n\", version)\n\treturn nil\n}\n\nfunc cmdWarmup(dir string, rest []string) error {\n\t// The arguments were thrown away here, so `deja warmup --rebuild` ran the\n\t// ordinary incremental build, said nothing and exited 0 (#4109). The\n\t// rebuild lives on index; a near miss of it is pointed there too.\n\tif len(rest) > 0 {\n\t\ta := rest[0]\n\t\tif a == \"--rebuild\" || a == \"-rebuild\" || nearestKnownFlag(a, []string{\"--rebuild\"}) != \"\" {\n\t\t\treturn fmt.Errorf(\"warmup: unknown flag %q — the rebuild is deja index --rebuild\", a)\n\t\t}\n\t\treturn fmt.Errorf(\"warmup takes no arguments — got %q\", a)\n\t}\n\t// warmup is what hooks and installs start; with automatic indexing off\n\t// it reports the index instead of building it (#5385).\n\tif index.Manual() {\n\t\tif err := index.ManualStatus(dir); err != nil {\n\t\t\treturn err\n\t\t}\n\t\tif line := manualIndexLine(dir); line != \"\" {\n\t\t\tfmt.Fprintln(os.Stderr, line)\n\t\t}\n\t\t_, _ = writeCLISkill()\n\t\treturn nil\n\t}\n\tstop := publishBuildProgress(dir)\n\tdefer stop()\n\tprepareFirstIndexGreeting(dir)\n\tif err := withBuildProgress(func() error { return index.Ensure(dir, \"\", false, os.Stderr) }); err != nil {\n\t\t// Every other build path runs through ensureError; this one returned\n\t\t// the raw error, so a read-only index directory read as\n\t\t// `open /…/index.lock: permission denied` — an internal lock file and\n\t\t// a syscall, the shape #798 replaced everywhere else.\n\t\treturn ensureError(dir, err)\n\t}\n\tmaybeFirstIndexGreeting(dir)\n\t// The CLI-only path ends here: binary, warmup, search. Without this the\n\t// agent on such a machine has a working index and no instruction to reach\n\t// for it, because the skill deja shipped described MCP tools that were\n\t// never installed (#1320). A failure is not the warmup's failure — the\n\t// index is built and search works either way.\n\t_, _ = writeCLISkill()\n\treturn nil\n}\n\n// countingWriter passes writes through and remembers whether there were any.\ntype countingWriter struct {\n\tw io.Writer\n\tn int\n}\n\n// Unwrap is the writer underneath, so a printer deciding whether it is\n// talking to a terminal sees the terminal rather than the counter (#4620).\nfunc (c *countingWriter) Unwrap() io.Writer { return c.w }\n\nfunc (c *countingWriter) Write(p []byte) (int, error) {\n\tn, err := c.w.Write(p)\n\tc.n += n\n\treturn n, err\n}\n\n// indexQuietOutcome is the line an index run ends with when the build itself\n// said nothing — another deja had already done the work. It reports what is\n// actually on disk: a store can change again in the moment between the build\n// finishing and this line, and claiming \"up to date\" there would be a guess.\nfunc indexQuietOutcome(fresh bool, sessions int) string {\n\tif !fresh {\n\t\treturn fmt.Sprintf(\"deja: another deja finished the build (%d session%s indexed); newer sessions are not in it yet\", sessions, pluralS(sessions))\n\t}\n\treturn fmt.Sprintf(\"deja: index is up to date (%d session%s)\", sessions, pluralS(sessions))\n}\n\nfunc cmdIndex(dir string, rest []string) error {\n\tforce := false\n\tquiet := false\n\tfor _, a := range rest {\n\t\tswitch a {\n\t\tcase \"--rebuild\", \"-rebuild\":\n\t\t\tforce = true\n\t\tcase \"--quiet\", \"-quiet\":\n\t\t\tquiet = true\n\t\tdefault:\n\t\t\treturn unknownFlag(\"index\", a, indexFlags)\n\t\t}\n\t}\n\t// The detached warmup runs this command too. With automatic indexing off\n\t// it is not the user asking, so it writes nothing; anything else here is\n\t// the explicit build the switch leaves on (#5385).\n\tif os.Getenv(\"DEJA_WARMUP_SENTINEL\") != \"\" && index.Manual() {\n\t\tclearWarmupSentinel()\n\t\treturn nil\n\t}\n\t// Before the freshness walk and the index lock, either of which can take\n\t// minutes on a contended disk: from here on the claim names a live owner.\n\tadoptWarmupClaim()\n\tdefer index.AllowBuild()()\n\t// Run by hand, it is also what turns search-only on or off (#5395).\n\tif os.Getenv(\"DEJA_WARMUP_SENTINEL\") == \"\" {\n\t\tdefer index.ApplySearchOnly()()\n\t}\n\t// Where the command reports that it worked. Nobody is watching a run out\n\t// of a shell profile or a hook, and a line printed over the prompt on\n\t// every new shell is the kind of thing that gets a tool uninstalled\n\t// rather than reported; `deja index >/dev/null` also swallows the errors\n\t// you would want to see (#1827).\n\t//\n\t// Only the success reporting goes here. A run that cannot read a store or\n\t// cannot write the index still says so on stderr, or a scheduled job\n\t// stops working and nothing tells anyone. The counts and the outcome line\n\t// are what quiet is about; a warning that the exclude list is not applied,\n\t// a path that could not be read, and an index that came out empty for a\n\t// reason are not.\n\tsaid := io.Writer(os.Stderr)\n\tif quiet {\n\t\tsaid = io.Discard\n\t}\n\t// Silence reads as \"it did not run\". `update` on the newest release and\n\t// `doctor` on a fresh index both say so; this one returned to the prompt\n\t// with nothing (#824). Only here: on a search the same line would be noise.\n\t// The freshness check walks every store, which on a slow volume is the\n\t// longest part of the whole command, and it ran before the progress sink\n\t// existed (#1021).\n\tstopProgress := publishBuildProgress(dir)\n\tindex.SweepStaleTmp(dir)\n\tfresh, n, check := index.CheckUpToDate(dir, \"\")\n\t// A note bucket's id names the local day of whichever process indexed the\n\t// line, so a `remember` under TZ=UTC and one under the machine's own zone\n\t// split the same moment into two buckets. `show` tells the reader this\n\t// command regroups them, and it answered that the index was up to date\n\t// (#1058).\n\tif fresh && !force && index.NotesZoneDrift(dir) {\n\t\tfmt.Fprintln(os.Stderr, \"deja: some notes were grouped in another time zone — regrouping them\")\n\t\tfresh, force = false, true\n\t}\n\t// aider headers carry no zone and are read in this one; after a zone\n\t// change the warmup this command runs must reread them (#5053).\n\tif fresh && !force && index.AiderZoneDrift(dir) {\n\t\tfmt.Fprintln(os.Stderr, \"deja: aider sessions were read in another time zone — reading them again\")\n\t\tfresh, force = false, true\n\t}\n\tif fresh && !force {\n\t\tstopProgress()\n\t\t// The warmup child runs this command, so returning before the sentinel\n\t\t// is cleared leaves a build that is not running: the next request is\n\t\t// suppressed until the retry window, and readWarmupStatus tells the\n\t\t// agent memory is on its way (#839).\n\t\tclearWarmupSentinel()\n\t\tfmt.Fprintf(said, \"deja: index is up to date (%d session%s)\\n\", n, pluralS(n))\n\t\tprintRetentionDue(said, time.Now())\n\t\t// Up to date with what it could read: a path it may not read is\n\t\t// still missing from recall on every run, not only the one that\n\t\t// found it (#5393).\n\t\tunread := sayUnreadable(dir)\n\t\t// \"Up to date\" is the most misleading place to stay quiet about it:\n\t\t// nothing changed on disk, so this is exactly where an exclusion set\n\t\t// after the build looks applied and is not.\n\t\tif index.ExclusionsChanged(dir) {\n\t\t\tfmt.Fprintln(os.Stderr, \"deja: the exclude list changed since this index was built — `deja index --rebuild` applies it to sessions already indexed\")\n\t\t}\n\t\tsayAliasesChanged(dir)\n\t\treturn partialIndex(unread, 0)\n\t}\n\tstopProgress()\n\tif !quiet {\n\t\tprepareFirstIndexGreeting(dir)\n\t}\n\t// The detached warmup publishes its progress so hooks can tell the user\n\t// memory is on its way; an interactive run draws the live display.\n\t// Counted, because a run that waited for another build prints nothing of\n\t// its own: Ensure finds the index current under the lock and returns. The\n\t// command then owed a closing line and had none, leaving \"waiting for it\n\t// to finish\" as the last thing on screen (#1751).\n\tprogress := &countingWriter{w: said}\n\t// Piped or under cron there is no live display, and a long run printed\n\t// \"indexing ...\" and then nothing until the per-store counts: one line\n\t// per phase says where it is (#5396). Not for the warmup, which\n\t// publishes its phases to the status file.\n\tphases := !quiet && !logoWanted(os.Stdout) && os.Getenv(\"DEJA_WARMUP_SENTINEL\") == \"\"\n\tskippedBefore := index.SkippedThisRun()\n\tbuild := func() error {\n\t\tif phases {\n\t\t\tindex.SetPhaseLines(said)\n\t\t\tdefer index.SetPhaseLines(nil)\n\t\t}\n\t\tif check != nil {\n\t\t\treturn index.EnsureChecked(check, force, progress)\n\t\t}\n\t\treturn index.Ensure(dir, \"\", force, progress)\n\t}\n\tdraw := func() error { return withBuildProgress(build) }\n\tif quiet {\n\t\t// The live display paints the same progress the sink above is\n\t\t// discarding, and it paints it to stdout.\n\t\tdraw = func() error { return timeBuild(build) }\n\t}\n\tif err := withWarmupStatus(dir, draw); err != nil {\n\t\t// The command whose whole job is building the index used to pass the\n\t\t// syscall through — `mkdir /…/index.db.tmp: permission denied` names\n\t\t// an internal temp path and no fix, while every reading command has\n\t\t// said what to change since ensureError was written (#798).\n\t\treturn ensureError(dir, err)\n\t}\n\tclearWarmupSentinel()\n\t// Inside the branch, not in its initializer: Go runs an `if` initializer\n\t// before it tests the condition, so the freshness walk — every registered\n\t// store, every candidate statted, the longest part of this command on a slow\n\t// volume — ran on every `deja index` and its answer was thrown away whenever\n\t// progress had already said what happened (#3500).\n\tif progress.n == 0 {\n\t\tfresh, n := index.UpToDate(dir, \"\")\n\t\tfmt.Fprintln(said, indexQuietOutcome(fresh, n))\n\t}\n\t// After the counts, beside the \"no longer on disk\" line the build printed:\n\t// the sessions a harness is about to delete, which the index keeps.\n\tprintRetentionDue(said, time.Now())\n\t// Two transcripts can carry the same harness:id — two files with the same\n\t// name in different projects. Both stay searchable, but one manifest row\n\t// holds them, so one project name covers both. Silence was the worst part\n\t// of it: the indexer counted every session on disk while the manifest held\n\t// fewer, and nothing connected the two numbers (#698).\n\t// A store deja could not read loses its sessions from recall, and the index\n\t// run is where someone is looking at the counts — doctor knowing about it\n\t// is not the same as saying it here (#818).\n\tunread := sayUnreadable(dir)\n\t// An exclusion applies at ingest, so it covers nothing already indexed —\n\t// and the sequence someone actually performs is to set the pattern, run\n\t// this command, and sync. That used to return silently having applied\n\t// nothing, and the export that followed still carried the project (#1307).\n\tif index.ExclusionsChanged(dir) {\n\t\tfmt.Fprintln(os.Stderr, \"deja: the exclude list changed since this index was built — `deja index --rebuild` applies it to sessions already indexed\")\n\t}\n\tsayAliasesChanged(dir)\n\t// The parse count and the indexed count differ by exactly these, and this\n\t// is where both are on screen (#868).\n\tif n := index.ReportEmptySessions(); n > 0 {\n\t\tfmt.Fprintf(said, \"deja: %d transcript%s held no message deja could index — not counted as %s\\n\",\n\t\t\tn, pluralS(n), pluralSessionWord(n))\n\t}\n\t// Said on every pass that reads a shared id's copies again, so it is a\n\t// count like the ones above and --quiet keeps it out.\n\tif n := index.ReportCollisions(); n > 0 {\n\t\tfmt.Fprintf(said, \"deja: %d session%s %s an id with another transcript — each pair is filed under one project, the one whose file sorts first\\n\", n, pluralS(n), verbShare(n))\n\t}\n\t// The per-harness lines above count transcripts, so once any of them\n\t// merged, those lines add up to more than the index holds — and the\n\t// reconciling line below is TTY-only, which is not where anyone is\n\t// counting. Say the real totals whenever the sums have parted (#1091).\n\t//\n\t// Every merge, not only the ones deja warns about: a goose session that\n\t// came back from both of that harness's stores is one conversation and\n\t// gets no warning, but it is still two transcripts against one row (#2066).\n\tif b := index.LastBuild; index.ReportMerged() > 0 && b.Messages > 0 {\n\t\tfmt.Fprintf(said, \"deja: indexed %d session%s, %d message%s%s — the per-harness lines above count transcripts, not rows\\n\",\n\t\t\tb.Sessions, pluralS(b.Sessions), b.Messages, pluralS(b.Messages), tookSuffix(b.Took))\n\t}\n\t// A machine with no agent history built an empty index and said nothing:\n\t// the step whose whole job is filling memory returned to the prompt after\n\t// a bare \"indexing ...\" line, and the state (no history anywhere, or a\n\t// store behind a permission wall) only surfaced on the next command.\n\t// Only when the index is empty too: a pass that found no transcript left\n\t// on disk still holds the sessions it keeps searchable, and the line\n\t// above has just said so (#4221).\n\t//\n\t// A store behind a permission wall is still named when the index holds\n\t// other sessions, without the \"nothing to index\" half: that line is the\n\t// only pointer to the store this pass could not read.\n\tif b := index.LastBuild; b.Sessions == 0 && b.Messages == 0 {\n\t\tdenied := deniedStoreCount()\n\t\tswitch {\n\t\tcase indexIsEmpty(dir) && (denied > 0 || noAgentHistoryFound()):\n\t\t\tfmt.Fprintln(os.Stderr, emptyIndexReason(b, index.ReportEvictedFiles()))\n\t\tcase denied > 0:\n\t\t\tfmt.Fprintln(os.Stderr, deniedStoresLine(denied, index.ReportEvictedFiles()))\n\t\t}\n\t}\n\tif !quiet {\n\t\tmaybeFirstIndexGreeting(dir)\n\t}\n\t// The live display erases itself on the way out, so a rebuild on a\n\t// terminal ended with an empty screen — three seconds of animation and no\n\t// record of what was built. Piped output has said it all along; this is\n\t// the same two numbers for the reader who watched it happen (#867).\n\tif b := index.LastBuild; !b.Initial && b.Messages > 0 && logoWanted(os.Stdout) && os.Getenv(\"DEJA_WARMUP_SENTINEL\") == \"\" {\n\t\tfmt.Fprintf(said, \"deja: indexed %d session%s, %d message%s%s\\n\", b.Sessions, pluralS(b.Sessions), b.Messages, pluralS(b.Messages), tookSuffix(b.Took))\n\t}\n\treturn partialIndex(unread, index.SkippedThisRun()-skippedBefore)\n}\n\n// exitPartial is the status of a `deja index` that wrote the index but left\n// part of the input unread: a path it could not read, or lines it skipped in\n// what it read this run. A cron job or a timer could not tell that from a\n// clean run, because both exited 0 (#5396). 1 stays \"the index was not\n// written\"; 2 is left alone, since a hook host reads it as \"block\".\nconst exitPartial = 3\n\n// exitStatus is an error that has already been said and carries the status\n// the process exits with.\ntype exitStatus int //nolint:errname // index_partial_exit_test.go names it\n\nfunc (e exitStatus) Error() string { return fmt.Sprintf(\"exit status %d\", int(e)) }\n\n// partialIndex is the outcome of an index run that wrote the index: nil, or\n// exitPartial when something it was given was not read.\nfunc partialIndex(unreadable, skipped int) error {\n\tif unreadable > 0 || skipped > 0 {\n\t\treturn exitStatus(exitPartial)\n\t}\n\treturn nil\n}\n\n// sayAliasesChanged says the project alias file changed since the build. The\n// aliases name sessions at ingest, so the edit renames nothing already indexed;\n// the rebuild is the reader's to start, it rereads every store (#5373).\nfunc sayAliasesChanged(dir string) {\n\tif index.ProjectAliasesChanged(dir) {\n\t\tfmt.Fprintf(os.Stderr, \"deja: %s changed since this index was built — `deja index --rebuild` renames the sessions already indexed\\n\", reportPath(sources.ProjectAliasPath()))\n\t}\n}\n\n// sayUnreadable names, per store, the paths the index could not read. A store\n// deja could not read loses its sessions from recall, and the index run is\n// where someone is looking at the counts — doctor knowing about it is not the\n// same as saying it here (#818). Returns how many there were.\nfunc sayUnreadable(dir string) int {\n\thealth := index.IngestHealth(dir)\n\ttotal := 0\n\tfor _, h := range sortedHarnesses(health) {\n\t\te := health[h]\n\t\tif e.FailedFiles == 0 {\n\t\t\tcontinue\n\t\t}\n\t\ttotal += e.FailedFiles\n\t\t// \"deja: deja: 1 path could not be read\" is the notes file, and reads\n\t\t// like a stutter. It is the user's own writing, so it says so (#901).\n\t\tname := h\n\t\tif h == \"deja\" {\n\t\t\tname = \"your notes\"\n\t\t}\n\t\tfmt.Fprintf(os.Stderr, \"deja: %s: %d path%s could not be read — `deja doctor` names %s\\n\",\n\t\t\tname, e.FailedFiles, pluralS(e.FailedFiles), pluralWhich(e.FailedFiles))\n\t}\n\treturn total\n}\n\nfunc cmdHookContext(dir string, rest []string) error {\n\tplain := false\n\tonce := false\n\t// --mcode answers in MiniMax Code's shape (hook_mcode.go).\n\tmcodeHookOutput = mcodeHookFlag(rest)\n\tfor _, a := range rest {\n\t\tswitch a {\n\t\tcase \"--plain\", \"-plain\":\n\t\t\tplain = true\n\t\t// --once is for a host with no usable session-start event, where the\n\t\t// digest has to ride the per-prompt hook instead: it turns the payload\n\t\t// flag on from the command line, so the same session gets it once.\n\t\tcase \"--once\", \"-once\":\n\t\t\tonce = true\n\t\t// --strict is for a host that validates the hook's JSON and discards\n\t\t// the whole output over a key it does not know. It drops the receipt\n\t\t// line and keeps the context (see hook_strict.go).\n\t\tcase \"--strict\", \"-strict\":\n\t\t\tstrictHookOutput = true\n\t\t// --copilot answers in Copilot CLI's flat shape, the only one it reads\n\t\t// (see hook_strict.go).\n\t\tcase \"--copilot\", \"-copilot\":\n\t\t\tcopilotHookOutput = true\n\t\t// --notes is for a host that shows a person nothing from its hooks —\n\t\t// dsh and OpenClaw put the plain digest in front of the model only. It\n\t\t// prints the notes meant for the person, and nothing else, for the\n\t\t// plugin to add to a reply the person does read.\n\t\t// A plugin reply can land in a group chat (OpenClaw's /deja), so the\n\t\t// notes here never quote the person's own questions.\n\t\tcase \"--notes\", \"-notes\":\n\t\t\tif notes := safeNote(humanNotesFor(dir, false)); notes != \"\" {\n\t\t\t\tfmt.Fprintln(os.Stdout, notes)\n\t\t\t}\n\t\t\treturn nil\n\t\t}\n\t}\n\t_ = runHookContextMode(dir, plain, once)\n\treturn nil\n}\n\nfunc cmdShow(dir string, rest []string, sourceInstance string) error {\n\to, err := parseShow(rest)\n\tif err != nil {\n\t\t// The missing id is the one refusal that depends on the store: on a\n\t\t// machine with nothing indexed the honest answer is that there is\n\t\t// nothing to show, not that an argument is missing. parseShow has no\n\t\t// dir to ask, so the store-aware phrasing is applied here (#1063).\n\t\tif err.Error() == showNeedsID {\n\t\t\treturn idPrefixNeeded(dir, \"show needs an id prefix\", showNeedsID)\n\t\t}\n\t\treturn err\n\t}\n\t// An id arrives from a chat wrapped in quotes or backticks and with the\n\t// harness deja itself printed in front of it (#921).\n\to.id = index.PastedSelector(o.id)\n\tif o.id == \"\" {\n\t\treturn idPrefixNeeded(dir, \"show needs an id prefix\", showNeedsID)\n\t}\n\t// A harness that does not exist matches nothing, and the refusal then\n\t// blamed the id the reader typed correctly (#2251). search, last, blame\n\t// and the MCP tools have always named the value they did not recognise.\n\tif herr := checkHarness(&o.harness); herr != nil {\n\t\treturn herr\n\t}\n\tvar s model.Session\n\tvar ok, prefixed bool\n\tif o.harness != \"\" {\n\t\t// The same pass the prefix form runs. Without it the exact-identity\n\t\t// path read whatever was on disk, and a store below the redaction\n\t\t// floor is fresh — so `show --harness` printed text this build would\n\t\t// not write while `show <prefix>` re-read the sources first (#3617).\n\t\t// A store that cannot be rebuilt — read-only, no space — falls through\n\t\t// to the loader, which refuses and says why.\n\t\t_ = ensureForCLIRead(dir)\n\t\t// Exact identity first — that is what --harness is for. But the usage line documents an id *prefix*, and\n\t\t// routing --harness straight to the exact lookup made every\n\t\t// prefix+harness call fail: \"deja show 019fa282 --harness codex\" said\n\t\t// no session matches while the same prefix without --harness worked.\n\t\ts, ok, err = index.FindByIdentity(dir, o.harness, o.id)\n\t\tif err == nil && !ok {\n\t\t\ts, ok = findByPrefixHarness(dir, o.id, o.harness)\n\t\t\tprefixed = true\n\t\t\tif ok && o.json {\n\t\t\t\terr = ambiguousJSONPrefixIn(dir, o.id, o.harness)\n\t\t\t}\n\t\t}\n\t} else {\n\t\ts, ok, err = findByPrefix(dir, o.id)\n\t\t// A machine reader cannot notice it was handed the newest of several\n\t\t// matches, so --json answers only a prefix that names one session.\n\t\tif err == nil && ok && o.json {\n\t\t\terr = ambiguousJSONPrefix(dir, o.id)\n\t\t}\n\t}\n\tif err != nil {\n\t\treturn err\n\t}\n\tif !ok {\n\t\tif n, cerr := index.SessionCount(dir); cerr == nil && n == 0 {\n\t\t\treturn errors.New(strings.TrimPrefix(emptyIndexHint(fmt.Sprintf(\"no session matches %q\", o.id)), \"deja: \"))\n\t\t}\n\t\treturn noSessionMatches(dir, o.id)\n\t}\n\tif err := denyPolicyHidden(o.id, s, os.Stderr); err != nil {\n\t\treturn err\n\t}\n\tif o.json {\n\t\treturn printSessionJSON(os.Stdout, s, o.offset, o.limit, sourceInstance)\n\t}\n\tif o.sliced {\n\t\t// Both flags are documented for `show` and only the JSON path honoured\n\t\t// them; the text output printed the whole session (#709).\n\t\ttotal := len(s.Messages)\n\t\ts.Messages = sliceMessages(s.Messages, o.offset, o.limit)\n\t\t// The JSON has reported the window all along; the terminal printed the\n\t\t// slice and said nothing, so five turns of two hundred read the same as\n\t\t// a session that is five turns long (#2296). search says it in this\n\t\t// shape two commands away.\n\t\tif line := showWindowNote(o.offset, len(s.Messages), total); line != \"\" {\n\t\t\tfmt.Fprintln(os.Stderr, line)\n\t\t}\n\t} else if n := len(s.Messages); n > showLargeSession {\n\t\tfmt.Fprintf(os.Stderr, \"deja: %d messages — `--offset n --limit n` reads a slice\\n\", n)\n\t}\n\tif o.harness == \"\" {\n\t\tnoteAmbiguousPrefix(dir, o.id, \"showing\")\n\t} else if prefixed {\n\t\tnoteAmbiguousPrefixIn(dir, o.id, o.harness, \"showing\")\n\t}\n\t// A day bucket's date is the day the index was built in, not the moment a\n\t// line was written: read in another zone, `show` lists a record dated the\n\t// day before the id says, and nothing connected the two (#1006).\n\tif note := bucketDayNote(s); note != \"\" {\n\t\tfmt.Fprintln(os.Stderr, note)\n\t}\n\tprintSpawnEdges(os.Stderr, dir, s)\n\tif s.Harness == \"claude\" && sources.IsPromptLog(s.Path) {\n\t\tfmt.Fprintln(os.Stderr, \"deja: only the prompts are left — Claude Code deleted the transcript, and history.jsonl kept what was typed\")\n\t}\n\t// A pasted log is one message, and the index keeps the head of it. The\n\t// window note above says when messages were left out; nothing said when a\n\t// message was, so a reader searching a log for the line that explains a\n\t// failure searched one they believed was whole (#2467).\n\tif line := clippedMessageNote(dir, s); line != \"\" {\n\t\tfmt.Fprintln(os.Stderr, line)\n\t}\n\tsearch.PrintSessionStyled(os.Stdout, s, search.ColorOK(os.Stdout), printableWidth(os.Stdout))\n\treturn nil\n}\n\n// clippedMessageNote says that a message in this session was stored short of\n// what the transcript holds. deja records the count per file at ingest, and a\n// store like Zed's threads.db keeps every session in one file, so the file's\n// count put the note on every session in it (#4340). The file says a clip\n// happened; the per-session split says which of its sessions holds it.\nfunc clippedMessageNote(dir string, s model.Session) string {\n\tif s.Path == \"\" {\n\t\treturn \"\"\n\t}\n\tfiles := index.IngestFilesReport(dir)\n\te, ok := files[s.Path]\n\tif !ok || e.Clipped == 0 {\n\t\treturn \"\"\n\t}\n\tn := e.ClippedSessions[s.ID]\n\tif e.ClippedSessions == nil {\n\t\t// A store built before the split: the file's count is all there is.\n\t\tn = e.Clipped\n\t}\n\tif n == 0 {\n\t\treturn \"\"\n\t}\n\treturn fmt.Sprintf(\"deja: %s stored short of what the transcript holds — the rest of %s is in the file itself\",\n\t\tpluralMessages(n), pluralThem(n))\n}\n\nfunc pluralMessages(n int) string {\n\tif n == 1 {\n\t\treturn \"one message was\"\n\t}\n\treturn fmt.Sprintf(\"%d messages were\", n)\n}\n\nfunc pluralThem(n int) string {\n\tif n == 1 {\n\t\treturn \"it\"\n\t}\n\treturn \"them\"\n}\n\n// showWindowNote is what the terminal says about a slice: which messages it\n// printed and how many there are. Empty when the slice is the whole session,\n// because a reader who asked for everything needs no arithmetic.\nfunc showWindowNote(offset, returned, total int) string {\n\tif total == 0 {\n\t\t// Not the offset's fault, and asked before the full-window case below:\n\t\t// a session deja holds with nothing readable in it answers every\n\t\t// window the same way, and printing a bare header for it is the silent\n\t\t// empty this note exists to end.\n\t\treturn \"deja: this session has no messages to show\"\n\t}\n\tif offset <= 0 && returned == total {\n\t\treturn \"\"\n\t}\n\tif returned == 0 {\n\t\treturn fmt.Sprintf(\"deja: --offset %d is past the end — the session has %d message%s\", offset, total, pluralS(total))\n\t}\n\tfirst := offset + 1\n\tlast := offset + returned\n\tif last >= total {\n\t\t// The last slice has no next one, and pointing at the offset after it\n\t\t// sent the reader to \"--offset 16 is past the end — the session has 16\n\t\t// messages\", which is deja answering its own advice (#3578).\n\t\treturn fmt.Sprintf(\"deja: showing message%s %d-%d of %d — the end of the session\",\n\t\t\tpluralS(returned), first, last, total)\n\t}\n\treturn fmt.Sprintf(\"deja: showing message%s %d-%d of %d — `--offset %d` reads the next slice\",\n\t\tpluralS(returned), first, last, total, last)\n}\n\n// printSpawnEdges names the sessions around this one when an agent spawned it\n// or spawned others from it. A subagent's work lives in its own session, so a\n// reader who found the parent could not get to it and a reader who found the\n// child could not say what asked for it (#1385).\nfunc printSpawnEdges(w io.Writer, dir string, s model.Session) {\n\tswitch {\n\tcase s.Parent != \"\" && s.Kind == \"fork\":\n\t\t// A Codex fork names the thread it branched from; nothing spawned it.\n\t\tfmt.Fprintf(w, \"deja: forked from %s — `deja show %s`\\n\", digest.Short(s.Parent), pasteSafe(digest.Short(s.Parent)))\n\tcase s.Parent != \"\":\n\t\tby := \"\"\n\t\tif s.Agent != \"\" {\n\t\t\tby = \" as \" + s.Agent\n\t\t}\n\t\tfmt.Fprintf(w, \"deja: spawned from %s%s — `deja show %s`\\n\", digest.Short(s.Parent), by, pasteSafe(digest.Short(s.Parent)))\n\tcase s.Kind != \"\" && strings.HasPrefix(s.Project, \"imported:\"):\n\t\t// The parent is on the machine that sent it.\n\t\tfmt.Fprintf(w, \"deja: %s session from another machine\\n\", s.Kind)\n\tcase s.Kind != \"\":\n\t\t// A kind with no parent is all the harness recorded; saying which\n\t\t// session asked for it would be a guess.\n\t\tfmt.Fprintf(w, \"deja: %s session — the harness records no parent for it\\n\", s.Kind)\n\t}\n\tchildren, err := ChildrenOfSession(dir, s.ID)\n\tif err != nil || len(children) == 0 {\n\t\treturn\n\t}\n\t// A long session spawns a hundred agents; naming them all buries the line\n\t// that says how many there were.\n\tconst named = 3\n\tids := make([]string, 0, named)\n\tfor _, c := range children[:min(named, len(children))] {\n\t\tids = append(ids, digest.Short(c.ID))\n\t}\n\trest := \"\"\n\tif len(children) > len(ids) {\n\t\trest = fmt.Sprintf(\" and %d more\", len(children)-len(ids))\n\t}\n\tfmt.Fprintf(w, \"deja: spawned %d session%s: %s%s\\n\", len(children), pluralS(len(children)), strings.Join(ids, \", \"), rest)\n}\n\n// ChildrenOfSession is a thin seam so the surface can be tested without an\n// index on disk.\nvar ChildrenOfSession = index.ChildrenOf\n\n// bucketDayNote explains a note bucket's date when the records inside it fall\n// on a different local day than the id claims — and stays silent otherwise, so\n// the ordinary case gains no line.\nfunc bucketDayNote(s model.Session) string {\n\tif s.Harness != \"deja\" || !strings.HasPrefix(s.ID, \"deja-20\") {\n\t\treturn \"\"\n\t}\n\tparts := strings.Split(strings.TrimPrefix(s.ID, \"deja-\"), \"-\")\n\tif len(parts) < 3 {\n\t\treturn \"\"\n\t}\n\tday := strings.Join(parts[:3], \"-\")\n\tfor _, m := range s.Messages {\n\t\tif m.Time.IsZero() {\n\t\t\tcontinue\n\t\t}\n\t\tif m.Time.Local().Format(\"2006-01-02\") != day {\n\t\t\treturn fmt.Sprintf(\"deja: %s in this id is the day the index was built in; the times below are this machine's — `deja index` regroups them\", day)\n\t\t}\n\t}\n\treturn \"\"\n}\n\ntype showOptions struct {\n\tid, harness   string\n\tjson          bool\n\toffset, limit int\n\t// sliced records that the reader asked for a slice, as opposed to the\n\t// JSON default: applying 50 to the text output would silently truncate\n\t// `deja show` for everyone who reads a session whole (#709).\n\tsliced bool\n}\n\n// showLargeSession is where `deja show` mentions the flags that read a slice.\n// A 200k-message transcript prints 600 001 lines.\nconst showLargeSession = 1000\n\nfunc parseShow(args []string) (showOptions, error) {\n\to := showOptions{limit: 50}\n\tfor i := 0; i < len(args); i++ {\n\t\tswitch a := args[i]; a {\n\t\tcase \"--json\":\n\t\t\to.json = true\n\t\tcase \"--harness\", \"--offset\", \"--limit\":\n\t\t\tif i+1 >= len(args) {\n\t\t\t\treturn o, fmt.Errorf(\"%s needs value\", a)\n\t\t\t}\n\t\t\ti++\n\t\t\tif strings.TrimSpace(args[i]) == \"\" { //nolint:gosec // bounds checked before i++\n\t\t\t\t// Empty is how \"no filter\" is spelled inside deja (#1612).\n\t\t\t\treturn o, fmt.Errorf(\"%s needs value\", a)\n\t\t\t}\n\t\t\tif a == \"--harness\" {\n\t\t\t\to.harness = args[i] //nolint:gosec // bounds checked before i++\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tv := args[i] //nolint:gosec // bounds checked before i++\n\t\t\tn, e := strconv.Atoi(v)\n\t\t\t// 0 is where a session starts, so the two flags have different\n\t\t\t// floors; the words recall uses for the same flags (#5650).\n\t\t\tif a == \"--offset\" {\n\t\t\t\tif e != nil || n < 0 {\n\t\t\t\t\treturn o, fmt.Errorf(\"show: --offset wants a number from 0 up, got %q\", v)\n\t\t\t\t}\n\t\t\t\to.offset = n\n\t\t\t} else {\n\t\t\t\tif e != nil || n <= 0 {\n\t\t\t\t\treturn o, fmt.Errorf(\"show: --limit wants a positive number, got %q\", v)\n\t\t\t\t}\n\t\t\t\to.limit = n\n\t\t\t}\n\t\t\to.sliced = true\n\t\tdefault:\n\t\t\tif strings.HasPrefix(a, \"-\") {\n\t\t\t\treturn o, unknownFlag(\"show\", a, showFlags)\n\t\t\t}\n\t\t\tif o.id != \"\" {\n\t\t\t\treturn o, errors.New(\"show accepts one session id\")\n\t\t\t}\n\t\t\to.id = a\n\t\t}\n\t}\n\t// The id first: it is what the command is for, and checking the flag ahead\n\t// of it cost two runs to learn two missing things (#820).\n\tif o.id == \"\" {\n\t\treturn o, errors.New(showNeedsID)\n\t}\n\tif o.limit > 200 {\n\t\treturn o, errors.New(\"show --limit must not exceed 200\")\n\t}\n\treturn o, nil\n}\n\n// ctxFromIDPrefix answers from the session an id-prefix names, and reports\n// whether it did. Six characters is where cmdCtx starts reading an argument as\n// an id at all — below that a token is far likelier to be a word — so this also\n// runs after the text search comes up empty, where there is no answer left to\n// shadow (#1614).\nfunc ctxFromIDPrefix(dir, q string) (bool, error) {\n\ts, ok, err := findByPrefix(dir, q)\n\tif err != nil || !ok {\n\t\treturn false, err\n\t}\n\t// Every other reading surface stops here when a rule denies the session's\n\t// origin; ctx handed the whole session over, and it is the command the hook\n\t// tells an agent to call (#1026).\n\tif kept, hidden := policyFilterSessionsCounted(policy.ActivationSearch, []model.Session{s}); len(kept) == 0 {\n\t\tfmt.Fprint(os.Stderr, policyHiddenNote(policy.ActivationSearch, hidden))\n\t\treturn false, fmt.Errorf(\"no session matches %q\", q)\n\t}\n\t// The one command an agent is told to call — the hook's lead line names\n\t// recall_context — answered from one of several sessions behind an elided\n\t// id without saying it was a choice, while show, share, resume, promote,\n\t// forget and handoff all said so (#923).\n\tnoteAmbiguousPrefix(dir, q, \"answering from\")\n\t// A decision that was taken back must say so here too. The search screen and\n\t// ctx's own query path both mark it; the id path handed an agent the whole\n\t// transcript of a withdrawn decision, reading like current truth (#1643).\n\thits := []search.Hit{{Session: s}}\n\tattachLifecycles(dir, hits)\n\tif line := lifecycleLine(hits[0]); line != \"\" {\n\t\tfmt.Fprintln(os.Stdout, line)\n\t}\n\tcw := &countingWriter{w: os.Stdout}\n\t// The digest marks its own cuts; a message the index stored short is a\n\t// cut made before it, and `deja show` says so the same way (#5392).\n\tif line := clippedMessageNote(dir, s); line != \"\" {\n\t\tfmt.Fprintln(os.Stderr, line)\n\t}\n\tsearch.PrintContextStyled(cw, s, \"\", search.ColorOK(os.Stdout), printableWidth(os.Stdout))\n\tif blk := changesBlock(s, search.ContextBudget-cw.n); blk != \"\" {\n\t\tfmt.Fprint(os.Stdout, \"\\n\"+blk)\n\t}\n\treturn true, nil\n}\n\nfunc cmdCtx(dir string, rest []string) error {\n\tif len(rest) < 1 {\n\t\treturn idPrefixNeeded(dir, \"ctx needs a query or an id-prefix\",\n\t\t\t\"ctx needs query or id-prefix (see `deja last`)\")\n\t}\n\t// ctx takes no flags, and --json/--harness/--project/--since all exist on\n\t// neighbouring commands — so reaching for one here is the obvious mistake.\n\t// Folding it into the query answered \"no session matches\", which is a\n\t// false statement about the store (#721).\n\t// Except behind a leading `--`, which is how search, fix and how already\n\t// spell \"the rest is the query\". Without it no caller can ask about a\n\t// query that starts with a dash, and the refusal reads to a plugin exactly\n\t// like an empty store.\n\tif len(rest) > 0 && rest[0] == \"--\" {\n\t\trest = rest[1:]\n\t} else {\n\t\tfor _, a := range rest {\n\t\t\tif strings.HasPrefix(a, \"--\") {\n\t\t\t\treturn fmt.Errorf(\"ctx takes no flags, only a query or id-prefix — got %q; a question that starts with a dash goes after `--`\", a)\n\t\t\t}\n\t\t}\n\t}\n\tq := strings.Join(rest, \" \")\n\t// Blank is not a query: it matched nothing and the search handed back the\n\t// first session in the store, so `deja ctx \"$TOPIC\"` with the variable\n\t// unset printed a transcript nobody asked for (#2259).\n\tif strings.TrimSpace(q) == \"\" {\n\t\treturn idPrefixNeeded(dir, \"ctx needs a query or an id-prefix\",\n\t\t\t\"ctx needs query or id-prefix (see `deja last`)\")\n\t}\n\tif !strings.Contains(q, \" \") && len(q) >= 6 {\n\t\tdone, err := ctxFromIDPrefix(dir, q)\n\t\tif err != nil || done {\n\t\t\treturn err\n\t\t}\n\t}\n\to := search.Options{Query: nfcfold.Compose(q), All: true}\n\tif err := ensureForCLISearch(dir, o, false, os.Stderr); err != nil {\n\t\tif !staleUnwritableIndex(dir, err) {\n\t\t\treturn err\n\t\t}\n\t\tfmt.Fprintf(os.Stderr, \"deja: answering from the index as it was — %v\\n\", ensureError(dir, err))\n\t}\n\t// Detailed, not the plain form: retrieval answers a sentence by dropping\n\t// the terms nothing carries and returning the session under the close or\n\t// relevance tier. Handing those sessions to Run without the tier and its\n\t// variant map made scoring hunt for the whole literal query, score zero,\n\t// and report \"no session matches\" — about a store `deja search` answered\n\t// on the same words. ctx is the command the hook names to an agent, and\n\t// agents ask in sentences (#R8).\n\tresult, err := index.SearchWithRecoveryDetailed(dir, o, os.Stderr)\n\tif err != nil {\n\t\treturn err\n\t}\n\tss := result.Sessions\n\to.Tier = result.Tier\n\t// Which rung answered, said out loud on stderr as the search screen says\n\t// it — stdout stays the context block an agent parses. ctx served an\n\t// answer to a word the caller never typed and said nothing about it.\n\tswitch {\n\tcase result.Neighbour:\n\t\tprintNeighbour(os.Stderr, result.Variants)\n\t\to.Stemmed = true\n\t\to.FuzzyVariants = result.Variants\n\tcase result.Stemmed:\n\t\tprintStemmed(os.Stderr, result.Variants)\n\t\to.Stemmed = true\n\t\to.FuzzyVariants = result.Variants\n\tcase result.Fuzzy:\n\t\tprintSpellings(os.Stderr, result.Variants)\n\t\to.Fuzzy = true\n\t\to.FuzzyVariants = result.Variants\n\t}\n\tif result.Tier == search.TierClose && o.FuzzyVariants == nil {\n\t\to.FuzzyVariants = result.Variants\n\t}\n\tvar hits []search.Hit\n\tif result.Tier == search.TierError {\n\t\tfmt.Fprintln(os.Stderr, \"deja: matched by error signature; showing the sessions that hit it\")\n\t\t// Both tiers below build their own hits and never went through the cap\n\t\t// in RunDetailed, so `--limit 3` printed the whole window — fifty\n\t\t// sessions — and so did a query with no flag (#3345).\n\t\thits, _ = capTierHits(search.ErrorHits(ss, o.Query), o)\n\t} else if result.Tier == search.TierRelevance {\n\t\to.Strict = result.Strict\n\t\tfmt.Fprintln(os.Stderr, relevanceLead(result.Strict))\n\t\thits, _ = capTierHits(markStrictHits(search.RelevanceHitsWeighted(ss, index.RelevanceMatchTerms(o.Query), result.TermIDF), result), o)\n\t} else if hits, err = search.Run(ss, o); err != nil {\n\t\treturn err\n\t}\n\thits, policyHidden := policyFilterHitsCounted(policy.ActivationSearch, hits)\n\tif len(hits) == 0 && policyHidden > 0 {\n\t\tfmt.Fprint(os.Stderr, policyHiddenNote(policy.ActivationSearch, policyHidden))\n\t\treturn fmt.Errorf(\"no session matches %q\", q)\n\t}\n\t// The same order the search screen shows: ctx took the top hit off its own\n\t// ranking, so a session the reader had rejected was handed to the agent as\n\t// the answer while search demoted it and said why (#1099, #974).\n\tattachLifecycles(dir, hits)\n\tdemoteRejected(hits)\n\tif len(hits) == 0 {\n\t\t// A prefix shorter than six characters never reached the id branch\n\t\t// above, so a session `deja show` opens on the same argument was\n\t\t// reported as no session at all (#1614). The query has already failed\n\t\t// here, so there is no answer for the id to shadow.\n\t\tif !strings.Contains(q, \" \") && len(q) < 6 {\n\t\t\tdone, ferr := ctxFromIDPrefix(dir, q)\n\t\t\tif ferr != nil {\n\t\t\t\treturn ferr\n\t\t\t}\n\t\t\tif done {\n\t\t\t\treturn nil\n\t\t\t}\n\t\t}\n\t\t// Same as #834 in files and restore: an empty store is not a miss on\n\t\t// the query.\n\t\tif n, cerr := index.SessionCount(dir); cerr == nil && n == 0 {\n\t\t\treturn errors.New(strings.TrimPrefix(emptyIndexHint(fmt.Sprintf(\"no session matches %q\", q)), \"deja: \"))\n\t\t}\n\t\t// The agent asking by a bucket id that moved got the dead end while\n\t\t// the human on `show` got the way forward (#1043).\n\t\treturn fmt.Errorf(\"no session matches %q%s\", q, movedBucketHint(dir, q))\n\t}\n\t// A short selector never reaches the id branch above, so a forgotten\n\t// session's note arrives as an ordinary hit — and the answer still has to\n\t// say the session is gone (#971).\n\tnoteForgottenSource(hits[0].Session, q, false)\n\t// The hit carries the matching snippets, not the session: for a promoted\n\t// note that meant the correction — which rarely repeats the words of the\n\t// decision — was missing, and the command whose whole job is packaging\n\t// context handed an agent a decision that had been withdrawn (#1011).\n\twhole := hits[0].Session\n\tif full, ok, ferr := findByPrefix(dir, whole.ID); ferr == nil && ok {\n\t\twhole = full\n\t}\n\tcw := &countingWriter{w: os.Stdout}\n\tif line := clippedMessageNote(dir, whole); line != \"\" {\n\t\tfmt.Fprintln(os.Stderr, line)\n\t}\n\tsearch.PrintContextStyled(cw, whole, q, search.ColorOK(os.Stdout), printableWidth(os.Stdout))\n\tif blk := changesBlock(whole, search.ContextBudget-cw.n); blk != \"\" {\n\t\tfmt.Fprint(os.Stdout, \"\\n\"+blk)\n\t}\n\treturn nil\n}\n\n// clearedNoteIDs names the notes whose borrowed title was just cleared. The\n// line used to offer `--session deja-note-…`, an id that matches nothing —\n// deja knows them here, and the ellipsis sent the reader to `deja last` to\n// look up what this command was already holding (#1030).\nfunc clearedNoteIDs(keys []string) string {\n\t// Only keys a note was actually promoted from: the dropped set also holds\n\t// the notes' own rows, and turning one of those into an id produced\n\t// `deja-note-deja-deja-note-claude-s1`, which matches nothing.\n\tknown := promotedNoteSources()\n\tids := make([]string, 0, len(keys))\n\tfor _, k := range keys {\n\t\tid := \"deja-note-\" + strings.ReplaceAll(k, \":\", \"-\")\n\t\tif _, ok := known[id]; !ok {\n\t\t\tcontinue\n\t\t}\n\t\t// Quoted one by one: the join renders them as separate code spans, so\n\t\t// quoting the finished list made every id one shell word (#2768).\n\t\tids = append(ids, pasteSafe(id))\n\t}\n\tsort.Strings(ids)\n\tconst shown = 3\n\tif len(ids) > shown {\n\t\treturn strings.Join(ids[:shown], \"`, `\") + fmt.Sprintf(\"` and %d more\", len(ids)-shown)\n\t}\n\treturn strings.Join(ids, \"`, `\")\n}\n\nfunc cmdLast(dir string, rest []string, sourceInstance string) error {\n\tn, o, sinceRaw, err := parseLast(rest)\n\tif err != nil {\n\t\treturn err\n\t}\n\tharnessRaw := o.Harness\n\tif herr := checkHarness(&o.Harness); herr != nil {\n\t\treturn herr\n\t}\n\tif rerr := checkRole(o.Role); rerr != nil {\n\t\treturn rerr\n\t}\n\t// Uncut, because the count the reader is told about has to be the count\n\t// they would get by asking again — and the trust policy filters below,\n\t// after the cut, so a total taken before it promised rows the policy would\n\t// not hand over (#2638). RecentMatching builds the whole matching set\n\t// before cutting anyway, so nothing is read twice.\n\tss, err := recentMatching(dir, 0, o)\n\tif err != nil {\n\t\treturn err\n\t}\n\t// The listing is titles and project names, which is exactly what the trust\n\t// policy exists to keep off the screen — and it was the one path that never\n\t// consulted it, while `search` under the same rule refused and said so\n\t// (#937). Listing counts as browsing: the search activation governs it.\n\tss, policyHidden := policyFilterSessionsCounted(policy.ActivationSearch, ss)\n\ttotal := len(ss)\n\tif n > 0 && len(ss) > n {\n\t\tss = ss[:n]\n\t}\n\t// Printing nothing at all and exiting 0 leaves no way to tell whether the\n\t// command worked, found nothing, or failed silently — which is what a\n\t// fresh install sees. blame already answers this shape of question.\n\tif note := policyHiddenNote(policy.ActivationSearch, policyHidden); note != \"\" {\n\t\tfmt.Fprintln(os.Stderr, note)\n\t}\n\t// And the other rule that withholds rows here. It filters inside the index\n\t// (#2541), so the count comes from the manifest rather than from what came\n\t// back — the same walk the listing has just done, over metas already read.\n\tif note := ignoredHiddenNote(index.IgnoredMatching(dir, o)); note != \"\" {\n\t\tfmt.Fprint(os.Stderr, note)\n\t}\n\tif len(ss) == 0 {\n\t\tif o.JSON {\n\t\t\treturn printRecentJSONWithheld(os.Stdout, nil, sourceInstance, policyHidden)\n\t\t}\n\t\t// The rule that emptied the list was named a line above; \"no sessions\n\t\t// indexed yet — run `deja index`\" is advice for a state deja is not in,\n\t\t// and the backside of teaching the listing to filter at all (#937,\n\t\t// #949).\n\t\tif policyHidden > 0 {\n\t\t\treturn nil\n\t\t}\n\t\t// \"Run deja index\" is advice for an empty store. With a filter set it\n\t\t// is advice for a state the tool is not in: indexing changes nothing\n\t\t// and doctor reports the stores as found. Name what emptied the result\n\t\t// instead (#637).\n\t\tif where := activeFilters(o, sinceRaw, harnessRaw); where != \"\" {\n\t\t\tfmt.Fprintf(os.Stderr, \"deja: no sessions match %s\\n\", where)\n\t\t\tfmt.Fprint(os.Stderr, olderThanWindow(dir, o.Since))\n\t\t\treturn nil\n\t\t}\n\t\t// \"run `deja index`\" cannot bring back what the reader forgot, and on a\n\t\t// store emptied by their own settings it is the wrong instruction —\n\t\t// search has said so since #844; the listing did not (#1007).\n\t\tif note := hiddenByOwnSettings(); note != \"\" {\n\t\t\tfmt.Fprint(os.Stderr, \"deja: no sessions indexed yet\\n\"+note)\n\t\t\treturn nil\n\t\t}\n\t\tfmt.Fprintln(os.Stderr, emptyIndexHint(\"no sessions indexed yet\"))\n\t\treturn nil\n\t}\n\tif o.JSON {\n\t\treturn printRecentJSONWithheld(os.Stdout, ss, sourceInstance, policyHidden)\n\t}\n\t// The cut is silent everywhere else on this screen: ten rows read as the\n\t// whole answer, and the two rules that withhold rows here already have a\n\t// line above the list. `last` takes its count as a bare argument, so that\n\t// is the form the way out takes (#2638).\n\tif total > len(ss) {\n\t\tfmt.Fprintf(os.Stderr, \"deja: showing %d of %d — `deja last %d` shows the rest\\n\", len(ss), total, total)\n\t}\n\tmarkForkTitles(dir, ss)\n\tprintLastRows(os.Stdout, ss)\n\t// The listing is ordered by a date, so one that has not happened leads it\n\t// and nothing else on the screen says why. The first screen carries the\n\t// same sentence beside the same list, because leaving it unexplained makes\n\t// the counters and the list disagree for no visible reason (#696, #2104).\n\tif n := stampedAheadCount(ss, time.Now()); n > 0 {\n\t\tfmt.Fprintf(os.Stderr, \"deja: %d session%s stamped later than this machine's clock — %s at the top of this list\\n\",\n\t\t\tn, pluralS(n), pluralThatThose(n))\n\t}\n\treturn nil\n}\n\n// printLastRows lists sessions one per line in the form the search result\n// header uses — harness, project, day, short id — with the columns padded so\n// a screenful scans down, and the title after them. On a terminal the harness\n// is coloured, the day dimmed and the title cut to the width; a pipe gets every\n// title whole.\nfunc printLastRows(w io.Writer, ss []model.Session) {\n\ttype row struct{ tag, project, when, id, title string }\n\trows := make([]row, 0, len(ss))\n\twTag, wProject, wWhen, wID := 0, 0, 0, 0\n\tfor _, s := range ss {\n\t\t// A session whose timestamp was missing or unparseable carries the Go\n\t\t// zero time, and \"0001-01-01\" reads as corrupted data rather than as a\n\t\t// missing field (#765). The reader's zone, like the brief and stats\n\t\t// (#849).\n\t\twhen := \"-\"\n\t\tif !s.Updated.IsZero() {\n\t\t\twhen = search.DisplayDate(s.Updated)\n\t\t}\n\t\t// Project, id and title are text a harness wrote, and this is one\n\t\t// line: an escape byte in any of them recolours the rest of the\n\t\t// listing and a carriage return rewinds it (#1090).\n\t\tr := row{\n\t\t\ttag:     \"[\" + s.Harness + \"]\",\n\t\t\tproject: redact.SafeForDisplay(displayProject(s)),\n\t\t\twhen:    when,\n\t\t\tid:      redact.SafeForDisplay(search.ShortID(s.ID)),\n\t\t}\n\t\ttitle := s.Title\n\t\tif title == \"\" {\n\t\t\ttitle = firstUserTitle(s)\n\t\t}\n\t\t// SafeForDisplay keeps a newline on purpose — the reading surfaces are\n\t\t// the session's own layout — but this is one row of a listing, and a\n\t\t// note title carries whatever a person wrote by hand (#2058).\n\t\tif title = search.SafeNoteTitle(redact.SafeForDisplay(title)); title != \"\" {\n\t\t\t// A session with no user turn borrows the assistant's opening line\n\t\t\t// (#692), and unmarked it read like the reader's own question\n\t\t\t// (#1100).\n\t\t\tif s.AgentTitle {\n\t\t\t\ttitle = \"agent: \" + title\n\t\t\t}\n\t\t}\n\t\tr.title = title\n\t\twTag = max(wTag, termwidth.Columns(r.tag))\n\t\twProject = max(wProject, termwidth.Columns(r.project))\n\t\twWhen = max(wWhen, termwidth.Columns(r.when))\n\t\twID = max(wID, termwidth.Columns(r.id))\n\t\trows = append(rows, r)\n\t}\n\t// A long project name would push every title off a narrow screen; past\n\t// this it stops setting the column for the rest.\n\twProject = min(wProject, 24)\n\tcolor, width := search.ColorOK(w), printableWidth(w)\n\tpad := func(s string, n int) string {\n\t\tif gap := n - termwidth.Columns(s); gap > 0 {\n\t\t\treturn s + strings.Repeat(\" \", gap)\n\t\t}\n\t\treturn s\n\t}\n\tfor i, r := range rows {\n\t\ttag := pad(r.tag, wTag)\n\t\tif color {\n\t\t\ttag = search.HarnessTag(ss[i].Harness, true) + strings.Repeat(\" \", len(tag)-len(r.tag))\n\t\t}\n\t\twhen := pad(r.when, wWhen)\n\t\tif color {\n\t\t\twhen = statDim + when + statReset\n\t\t}\n\t\thead := tag + \" \" + pad(r.project, wProject) + \"  \" + when + \"  \" + pad(r.id, wID)\n\t\tline := head\n\t\tif r.title != \"\" {\n\t\t\ttitle := r.title\n\t\t\tif width > 0 {\n\t\t\t\tused := wTag + 1 + max(wProject, termwidth.Columns(r.project)) + 2 + wWhen + 2 + wID + 2\n\t\t\t\t// Too little room beside the columns and the title goes under\n\t\t\t\t// them, the way a search hit's quote does, rather than being\n\t\t\t\t// cut to a few words.\n\t\t\t\tif width-used < 32 {\n\t\t\t\t\tfmt.Fprintln(w, strings.TrimRight(line, \" \"))\n\t\t\t\t\tfmt.Fprintln(w, \"  \"+cutToWidth(title, width-2))\n\t\t\t\t\tcontinue\n\t\t\t\t}\n\t\t\t\ttitle = cutToWidth(title, width-used)\n\t\t\t}\n\t\t\tline += \"  \" + title\n\t\t}\n\t\tfmt.Fprintln(w, strings.TrimRight(line, \" \"))\n\t}\n}\n\n// cutToWidth shortens s to width columns with an ellipsis, ending on a whole\n// word where one is near. Width zero or less leaves it alone.\nfunc cutToWidth(s string, width int) string {\n\tif width <= 0 || termwidth.Columns(s) <= width {\n\t\treturn s\n\t}\n\tif width < 8 {\n\t\twidth = 8\n\t}\n\tcut := strings.TrimRight(termwidth.Cut(s, width-1), \" \")\n\tif at := strings.LastIndex(cut, \" \"); at > 0 && termwidth.Columns(cut[at:]) <= 14 {\n\t\tcut = strings.TrimRight(cut[:at], \" \")\n\t}\n\treturn cut + \"…\"\n}\n\n// fitNotice wraps a one-line notice to the terminal w writes to, at spaces,\n// with the continuation indented under \"deja: \". A pipe gets it unchanged.\nfunc fitNotice(w io.Writer, note string) string {\n\tbody, nl := strings.CutSuffix(note, \"\\n\")\n\tif strings.Contains(body, \"\\n\") {\n\t\treturn note\n\t}\n\tout := termwidth.Indent(body, printableWidth(w), \"\", \"      \")\n\tif nl {\n\t\tout += \"\\n\"\n\t}\n\treturn out\n}\n\n// stampedAheadCount counts the listed sessions whose stamp is after now, by the\n// same rule the first screen counts them with.\nfunc stampedAheadCount(ss []model.Session, now time.Time) int {\n\tn := 0\n\tfor _, s := range ss {\n\t\tif index.StampedAhead(s.Updated, now) {\n\t\t\tn++\n\t\t}\n\t}\n\treturn n\n}\n\n// stampedAheadHits counts the same thing over a result set rather than a\n// listing. Search ranks on recency among other things, so the sessions whose\n// stamp cannot place them are the ones it places first.\nfunc stampedAheadHits(hits []search.Hit, now time.Time) int {\n\tn := 0\n\tfor _, h := range hits {\n\t\tif index.StampedAhead(h.Session.Updated, now) {\n\t\t\tn++\n\t\t}\n\t}\n\treturn n\n}\n\n// pluralThatThose keeps the sentence above readable for one session and for\n// several, the way pluralThem does for the ingest lines.\nfunc pluralThatThose(n int) string {\n\tif n == 1 {\n\t\treturn \"that one is\"\n\t}\n\treturn \"those are\"\n}\n\n// cmdSearch is the explicit form. Bare `deja <words>` also searches, but a\n// single word that happens to name a subcommand runs that instead, which is\n// how `/deja uninstall` inside a plugin came back with \"nothing matches\".\n// Anything shelling out to deja with user text should use this.\nfunc cmdSearch(dir string, rest []string, sourceInstance string) error {\n\tif len(rest) == 0 {\n\t\treturn errors.New(\"search needs a query\")\n\t}\n\treturn runSearch(dir, rest, sourceInstance)\n}\n\n// ensureForCLISearch keeps a search off the rewrite path. Appending the new\n// bytes of a grown transcript is cheap and stays inline; work that rewrites the\n// index — a store that rewrote itself, a removed file, a harness with no append\n// path — is handed to the detached warmup, and the search answers from the\n// index it already has. MCP made that trade at #1305 because a rebuild blows\n// the client's timeout; the CLI kept waiting, and on a 1.7 GB store a query\n// that matched nothing took 194 s while a live Grok session grew (#1521).\n//\n// `--rebuild` still waits: someone who asked for the rebuild wants its result.\nfunc ensureForCLISearch(dir string, o search.Options, force bool, progress io.Writer) error {\n\tif force {\n\t\t// Asked for by hand, so it builds with automatic indexing off too.\n\t\tdefer index.AllowBuild()()\n\t\treturn index.EnsureForSearch(dir, o, true, progress)\n\t}\n\tcov, err := index.EnsureForSearchCoverage(dir, o, progress)\n\tif err != nil {\n\t\treturn err\n\t}\n\tif line := manualIndexLine(dir); line != \"\" && progress != io.Discard {\n\t\tsaidManualIndex.Do(func() { fmt.Fprintln(progress, line) })\n\t}\n\tif cov.Stale {\n\t\trequestWarmup(dir)\n\t\t// Only when there is an index to answer from. On a first build there is\n\t\t// not, and the two lines contradicted each other on the worst run to\n\t\t// contradict anything — a new machine's first search said \"answering\n\t\t// from the index as it was\" and then \"the index is being rebuilt right\n\t\t// now, run this again in a moment\" (#3574).\n\t\tif index.ReadableSnapshot(dir) {\n\t\t\tfmt.Fprintln(progress, \"deja: \"+coverageLine(cov))\n\t\t}\n\t}\n\treturn nil\n}\n\n// runBareSearch is `deja <words>` — the form where the first word stood where a\n// command name goes. That is the only form the mistyped-command hint is about:\n// `deja search doctro` is someone searching for the word (#2197).\nfunc runBareSearch(dir string, args []string, sourceInstance string) error {\n\treturn searchWithOptions(dir, args, sourceInstance, true)\n}\n\n// oneEditCommand names the command a bare search's first word is one edit\n// from, so the hint comes before the index build and the results (#4628). It\n// is a hint, not a refusal: lost, list, logs and fixes are one edit from a\n// command and are also words people search for. The broader prefix and\n// two-edit hints stay for after the search; a quoted multi-word query is\n// still a query.\nfunc oneEditCommand(first string) string {\n\tlow := strings.ToLower(first)\n\tif len([]rune(low)) < 4 || strings.HasPrefix(low, \"-\") || strings.ContainsAny(low, \" \\t\\r\\n\") || dispatchKnows(low) {\n\t\treturn \"\"\n\t}\n\tfor _, name := range commandHintNames() {\n\t\tif editDistance(low, name) == 1 {\n\t\t\treturn name\n\t\t}\n\t}\n\treturn \"\"\n}\n\nfunc runSearch(dir string, args []string, sourceInstance string) error {\n\treturn searchWithOptions(dir, args, sourceInstance, false)\n}\n\nfunc searchWithOptions(dir string, args []string, sourceInstance string, bare bool) error {\n\tforce := false\n\tvar filtered []string\n\tfor _, a := range args {\n\t\tif a == \"--rebuild\" || a == \"-rebuild\" {\n\t\t\tforce = true\n\t\t\tcontinue\n\t\t}\n\t\tfiltered = append(filtered, a)\n\t}\n\to, err := parseSearch(filtered)\n\tif err != nil {\n\t\treturn err\n\t}\n\tharnessRaw := o.Harness\n\tif herr := checkHarness(&o.Harness); herr != nil {\n\t\treturn herr\n\t}\n\tif rerr := checkRole(o.Role); rerr != nil {\n\t\treturn rerr\n\t}\n\tsinceRaw := sinceRawArg(filtered)\n\t// Before the index build, so the reader who meant a command sees it first,\n\t// and then the search runs as typed. On stderr like every other command\n\t// hint, and never for --json, where a script reads the results (#4628).\n\thinted := false\n\tif bare && !o.JSON && len(args) > 0 {\n\t\tif near := oneEditCommand(args[0]); near != \"\" {\n\t\t\tfmt.Fprintf(os.Stderr, \"deja: %q is not a command — did you mean `deja %s`?\\n\", args[0], near)\n\t\t\thinted = true\n\t\t}\n\t}\n\to.SourceInstance = sourceInstance\n\to.RecallWorn = usage.WornSessions(dir)\n\tprepareFirstIndexGreeting(dir)\n\tif err = withBuildProgress(func() error { return ensureForCLISearch(dir, o, force, os.Stderr) }); err != nil {\n\t\t// A store that cannot be written still has an index that can be read:\n\t\t// answering from it beats answering nothing (#904).\n\t\tif !staleUnwritableIndex(dir, err) {\n\t\t\treturn ensureError(dir, err)\n\t\t}\n\t\tfmt.Fprintf(os.Stderr, \"deja: answering from the index as it was — %v\\n\", ensureError(dir, err))\n\t}\n\tmaybeFirstIndexGreeting(dir)\n\t// The page is all a capped search shows, so retrieval may rank a large\n\t// match from the postings first and read only what can reach it (#5467).\n\tif !o.All {\n\t\to.Window = o.Limit\n\t\tif o.Window <= 0 {\n\t\t\to.Window = search.DefaultLimit\n\t\t}\n\t\tif pool := rerankCandidateLimit(dir, o); pool > o.Window {\n\t\t\to.Window = pool\n\t\t}\n\t\to.Activation = policy.ActivationSearch\n\t}\n\tresult, err := index.SearchWithRecoveryDetailed(dir, o, os.Stderr)\n\tif err != nil {\n\t\treturn fmt.Errorf(\"search: %w\", err)\n\t}\n\to.Unread = result.Unread\n\t// Before ranking, not after: the cap is applied while ranking, so a rule\n\t// that runs later still lets denied sessions occupy the result slots and\n\t// the allowed ones never reach the page (#1060).\n\tss, policyHidden := policyFilterSessionsCounted(policy.ActivationSearch, search.WithoutIgnored(result.Sessions))\n\tpolicyHidden += unreadWithheld(result)\n\to.PolicyWithheld = policyHidden\n\to.Tier = result.Tier\n\tapplySearchLadder(&o, result)\n\t// The relevance and error tiers hand back a ranked window, not the\n\t// whole match: date order over them is the newest of that window, and\n\t// tierWindow says the match ran past it.\n\t// --all reads newest first unless --sort relevance says otherwise; --json\n\t// keeps the ranked order a script may rely on unless --sort date asks.\n\tdated := o.Sort == search.SortDate || o.All && !o.JSON && o.Sort == \"\"\n\thits, tierWindow, windowRead, err := searchTierHits(dir, &o, result, ss, dated)\n\tif err != nil {\n\t\treturn err\n\t}\n\thits, demoted := searchAfterRank(dir, hits, &o)\n\tif note := demotedNote(hits, demoted); note != \"\" {\n\t\tfmt.Fprintf(os.Stderr, \"deja: %s\\n\", note)\n\t}\n\tif note := otherWordFormsNote(dir, o, hits); note != \"\" {\n\t\tfmt.Fprint(os.Stderr, fitNotice(os.Stderr, note))\n\t}\n\tmistyped := false\n\tif len(hits) == 0 {\n\t\tmistyped = printSearchMiss(dir, o, policyHidden, sinceRaw, harnessRaw, hinted)\n\t}\n\tif o.Capped && len(hits) > 0 {\n\t\tprintSearchCapped(o, len(hits))\n\t}\n\t// The answer can also be short for a reason no flag lifts. Counted over the\n\t// sessions holding every term, so an ordinary search in a store with a big\n\t// ignored tree stays quiet (#2562).\n\t//\n\t// Only where there is an answer to be short: printNoMatches says the same\n\t// thing on the way to \"try fewer words\", and a miss printed it twice\n\t// (#2632).\n\tif len(hits) > 0 {\n\t\tif note := ignoredHiddenNoteFor(\"answer\", index.IgnoredWithAllTerms(dir, query.Tokens(o.Query))); note != \"\" {\n\t\t\tfmt.Fprint(os.Stderr, note)\n\t\t}\n\t}\n\t// The window this is being printed into, so the lines can be budgeted\n\t// rather than assumed 80 wide. Only for a terminal: a pipe gets the whole\n\t// line, since a script reading deja wants the text and not the layout\n\t// (#604).\n\to.Width = printableWidth(os.Stdout)\n\t// --all is the whole list, and past the first screen the scores are near\n\t// ties a reader cannot see, so the order read as random: Jun 2, May 13,\n\t// Mar 4, then Jun 22 (#45). The whole list reads newest first unless\n\t// --sort relevance says otherwise; --json keeps the ranked order a script\n\t// may rely on unless --sort date asks for this one (#5577).\n\tif dated {\n\t\t// The semantic tier and the demotion of rejected sessions reorder\n\t\t// after retrieval; the date is the last word.\n\t\tsearch.ByDate(hits)\n\t\tif !o.JSON && len(hits) > 1 {\n\t\t\tfmt.Fprintln(os.Stderr, \"deja: \"+newestFirstNote(o, len(hits), tierWindow, windowRead))\n\t\t}\n\t}\n\t// Through a counter, so the log records what actually went out rather than\n\t// a guess at it. `deja log` is the audit of what deja did, and the search\n\t// kind has been named in the docs, in the comment over the kind constants\n\t// and in the empty-log line since #47 while nothing ever wrote one (#2471).\n\t// It stays out of every count: servedKind and injectedKind both exclude it,\n\t// so the statusline and the impact screen still speak only for memory that\n\t// reached an agent.\n\tcounted := &countingWriter{w: os.Stdout}\n\t// The first recall that finds something is a moment for the mark, once per\n\t// index, only at a terminal and never into a pipe or as JSON (#4624).\n\tif len(hits) > 0 && !o.JSON && logoWanted(os.Stdout) && firstRecall(dir) {\n\t\tmood, line := searchCatMoment(false)\n\t\tprintLogoMood(os.Stdout, []string{line}, mood)\n\t}\n\tsearch.Print(counted, hits, o)\n\tusage.RecordResult(dir, usage.KindSearch, counted.n, len(hits), len(hits) == 0)\n\t// A stamp that has not happened is a date the reader cannot use, and recency\n\t// is half of what puts a hit where it is. The listing has said so since\n\t// #2104, the brief and doctor count them, recall marks the one it quotes —\n\t// search was the surface that printed \"Jan 1 2099\" beside an answer and left\n\t// the reader to work out what it meant (#3595).\n\tif n := stampedAheadHits(hits, time.Now()); n > 0 {\n\t\tfmt.Fprintf(os.Stderr, \"deja: %d session%s here stamped later than this machine's clock — a stamp that has not happened cannot be placed against the others\\n\",\n\t\t\tn, pluralS(n))\n\t}\n\treturn searchAfterPrint(dir, o, len(hits), bare, hinted, mistyped)\n}\n\n// searchAfterPrint is what search says once the results are out: the hint\n// for a mistyped command, its exit code, and the daily tip.\nfunc searchAfterPrint(dir string, o search.Options, found int, bare, hinted, mistyped bool) error {\n\t// A wrong guess at a command name falls through to search, and the hint\n\t// that names it ran only on an empty result — so a typo whose word happens\n\t// to be in the history got a conversation back and nothing about the\n\t// command it meant (#2197). After the results, on stderr, and only for the\n\t// bare form: `deja search doctro` is someone searching for the word.\n\t//\n\t// One word only, which is narrower than the empty-result hint on purpose.\n\t// There, a hint costs nothing over a failed search; here it lands on an\n\t// answer the reader may well have wanted, and \"doctors pool\" is a search\n\t// however close its first word sits to a command name.\n\tif bare && !hinted && !o.JSON && found > 0 && len(strings.Fields(o.Query)) == 1 {\n\t\tfmt.Fprint(os.Stderr, commandHint(o.Query))\n\t}\n\t// A search that found nothing is not a failure — that is the ordinary\n\t// answer to a question the history cannot settle. A command name that does\n\t// not exist is: `deja unforget x` did nothing, said so, and exited 0, so a\n\t// script that ran it and checked the code was told otherwise. The hint is\n\t// narrow enough to carry the distinction — it stays quiet unless a real\n\t// command is within one edit of what was typed.\n\tif mistyped {\n\t\treturn errAlreadySaid\n\t}\n\t// One line, at most once a day, naming a command the reader may not have\n\t// met (#4629). Only after an answer, only in a terminal and never for\n\t// --json: a pipe, a script or a hook reads the results, not advice. On\n\t// stderr, so the results themselves stay what they were, and only when\n\t// stderr is a terminal too: `2>file` is a log, not a reader.\n\tif found > 0 && !o.JSON && briefWanted(os.Stdout) && briefWanted(os.Stderr) {\n\t\tmaybeTip(os.Stderr, dir+\".tip\", time.Now())\n\t}\n\treturn nil\n}\n\n// searchAfterRank runs what comes after the tier ranked: the rerank, the\n// semantic tier and the lifecycle marks. It returns the hits and how many\n// rejected ones were moved down.\nfunc searchAfterRank(dir string, hits []search.Hit, o *search.Options) ([]search.Hit, int) {\n\t// A rerank reorders by meaning, which date order throws away again.\n\tif !o.Regex && !o.NoEmbed && os.Getenv(\"DEJA_EMBED\") != \"off\" && o.Sort != search.SortDate {\n\t\thits = maybeRerank(dir, hits, *o, os.Stderr)\n\t}\n\tvar semantic bool\n\thits, semantic = maybeSemantic(dir, hits, *o, os.Stderr)\n\tif semantic {\n\t\t// The lexical hits were scoped by the trust policy above, but the\n\t\t// semantic tier reaches the whole sidecar and brings back sessions of\n\t\t// its own — an imported peer's content the policy withholds from every\n\t\t// other read path leaked straight through the embedding fallback. Scope\n\t\t// the semantic hits the same way before they are shown.\n\t\thits, _ = policyFilterHitsCounted(policy.ActivationSearch, hits)\n\t}\n\to.Semantic = semantic\n\t// What the semantic tier and reranking brought in, uncapped: a fork's hit\n\t// quoting its source again goes here too (#5320).\n\thits = dropCopiedHits(dir, hits)\n\t// Policy scoping, reranking and the semantic tier all run after the cap, so\n\t// the pre-cap count can no longer describe what is being returned. When\n\t// nothing was capped the honest total is simply what survived; when it was,\n\t// there is no way to know how the filters would have treated the hidden\n\t// ones, so the pre-cap figure stands and `capped` says to distrust it.\n\tattachLifecycles(dir, hits)\n\tdemoted := demoteRejected(hits)\n\tattachMoved(hits)\n\tif !o.Capped {\n\t\to.Total, o.TotalEstimated = len(hits), false\n\t}\n\tif !o.All {\n\t\tvar pageCapped bool\n\t\thits, pageCapped = capTierHits(hits, *o)\n\t\to.Capped = o.Capped || pageCapped\n\t}\n\treturn hits, demoted\n}\n\n// applySearchLadder records which rung of the word ladder answered, and says\n// so on stderr.\nfunc applySearchLadder(o *search.Options, result index.SearchResult) {\n\tswitch {\n\tcase result.Neighbour:\n\t\tprintNeighbour(os.Stderr, result.Variants)\n\t\to.Stemmed = true\n\t\to.FuzzyVariants = result.Variants\n\tcase result.Stemmed:\n\t\tprintStemmed(os.Stderr, result.Variants)\n\t\to.Stemmed = true\n\t\to.FuzzyVariants = result.Variants\n\tcase result.Fuzzy:\n\t\tprintFuzzy(os.Stderr, result.Variants)\n\t\to.Fuzzy = true\n\t\to.FuzzyVariants = result.Variants\n\t}\n\tif result.Tier == search.TierClose && o.FuzzyVariants == nil {\n\t\to.FuzzyVariants = result.Variants\n\t}\n}\n\n// searchTierHits turns what retrieval handed back into hits, the way the tier\n// that answered ranks them. tierWindow says the tier's window cut the match\n// short and windowRead how much of it was read in date order.\nfunc searchTierHits(dir string, o *search.Options, result index.SearchResult, ss []model.Session, dated bool) (hits []search.Hit, tierWindow bool, windowRead int, err error) {\n\trankOpt := *o\n\tif pool := rerankCandidateLimit(dir, *o); pool > rankOpt.Limit {\n\t\trankOpt.Limit = pool\n\t}\n\tswitch result.Tier {\n\tcase search.TierError:\n\t\t// A pasted error IS a match; ErrorHits keeps the ranking and the error\n\t\t// neighbourhood the tier found. Re-scoring it as an ordinary run would\n\t\t// zero it out — the word ladder already failed, which is why this tier\n\t\t// fired at all.\n\t\tfmt.Fprintln(os.Stderr, \"deja: matched by error signature; showing the sessions that hit it\")\n\t\thits = search.ErrorHits(ss, o.Query)\n\t\to.Total, o.Capped = result.Total, result.Capped\n\t\ttierWindow = result.Capped\n\t\terrAt := len(hits)\n\t\thits = dropCopiedHits(dir, hits)\n\t\tif d := errAt - len(hits); o.Total >= d {\n\t\t\to.Total -= d\n\t\t}\n\t\tif o.Total < len(hits) {\n\t\t\to.Total = len(hits)\n\t\t}\n\t\tif o.Sort == search.SortDate {\n\t\t\tsearch.ByDate(hits)\n\t\t\twindowRead = len(hits)\n\t\t}\n\t\tvar capped bool\n\t\thits, capped = capTierHits(hits, rankOpt)\n\t\to.Capped = o.Capped || capped\n\tcase search.TierRelevance:\n\t\to.Strict = result.Strict\n\t\tlead := relevanceLead(result.Strict)\n\t\tif dated && result.Strict > 0 {\n\t\t\tlead = strings.Replace(lead, \"the rest below are ranked by relevance\", \"they come first and the rest after, each newest first\", 1)\n\t\t}\n\t\tfmt.Fprintln(os.Stderr, lead)\n\t\thits = markStrictHits(search.RelevanceHitsWeighted(ss, index.RelevanceMatchTerms(o.Query), result.TermIDF), result)\n\t\trelAt := len(hits)\n\t\thits = dropCopiedHits(dir, hits)\n\t\trelAt -= len(hits)\n\t\t// This tier ranks and truncates inside retrieval, so counting the\n\t\t// sessions it handed back measures its window, not the match: every\n\t\t// query deeper than the window reported the window's own size and\n\t\t// capped: false, which told a consumer to stop checking exactly when\n\t\t// there was something to check. Take the tier's figures when it has\n\t\t// them; the paths that report none (a quoted query retried without\n\t\t// its quotes, served here under the relevance label) never truncated,\n\t\t// so what arrived is the whole of it.\n\t\to.Total, o.Capped = result.Total, result.Capped\n\t\tif o.Total >= relAt {\n\t\t\to.Total -= relAt\n\t\t}\n\t\tif o.Total < len(hits) {\n\t\t\to.Total = len(hits)\n\t\t}\n\t\ttierWindow = result.Capped\n\t\tif o.Sort == search.SortDate {\n\t\t\tsearch.ByDate(hits)\n\t\t\twindowRead = len(hits)\n\t\t}\n\t\tvar relCapped bool\n\t\thits, relCapped = capTierHits(hits, rankOpt)\n\t\to.Capped = o.Capped || relCapped\n\tdefault:\n\t\t// RunDetailed rather than Run: the JSON envelope reports how many\n\t\t// sessions matched before the cap, and that is not recoverable from a\n\t\t// list the cap has already trimmed.\n\t\t// Copies go before the cap: a fork repeating its source took a slot\n\t\t// and counted in the total (#5320, #5335).\n\t\tkeep := func(hs []search.Hit) []search.Hit { return dropCopiedHits(dir, hs) }\n\t\tdetailed, rerr := search.RunDetailedKeeping(ss, rankOpt, keep)\n\t\t// A date page drawn from the newest matches by their postings comes\n\t\t// back short when few of them say a quoted phrase and the rest were\n\t\t// too many to check. It is read whole then, as the screen does.\n\t\tif rerr == nil && o.Sort == search.SortDate && o.Window > 0 && len(detailed.Hits) < o.Window && detailed.Total > len(detailed.Hits) {\n\t\t\twhole := *o\n\t\t\twhole.Window, whole.Unread = 0, nil\n\t\t\tif r2, err2 := index.SearchWithRecoveryDetailed(dir, whole, io.Discard); err2 == nil && r2.Tier == result.Tier {\n\t\t\t\tss2, _ := policyFilterSessionsCounted(policy.ActivationSearch, search.WithoutIgnored(r2.Sessions))\n\t\t\t\twhole.Unread = r2.Unread\n\t\t\t\tif d2, e2 := search.RunDetailedKeeping(ss2, whole, keep); e2 == nil {\n\t\t\t\t\tdetailed, o.Unread = d2, r2.Unread\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif rerr != nil {\n\t\t\t// \"run:\" is the name of a function, and the reader of this line is\n\t\t\t// someone who mistyped a pattern (#2286). The only error that\n\t\t\t// reaches here in practice is the regexp compile, so it says which\n\t\t\t// input to look at, in the words the other bad flags use (#1602).\n\t\t\tif o.Regex {\n\t\t\t\treturn nil, false, 0, rePatternError(o.Query, rerr)\n\t\t\t}\n\t\t\treturn nil, false, 0, rerr\n\t\t}\n\t\thits, o.Total, o.Capped, o.TotalEstimated = detailed.Hits, detailed.Total, detailed.Capped, detailed.Estimated\n\t}\n\treturn hits, tierWindow, windowRead, nil\n}\n\n// printSearchMiss says why a search came back empty. It reports whether the\n// query looked like a mistyped command.\nfunc printSearchMiss(dir string, o search.Options, policyHidden int, sinceRaw, harnessRaw string, hinted bool) bool {\n\t// An empty search is a moment for the mark, but only at a terminal\n\t// and never into a pipe a script reads (#4624).\n\tif !o.JSON && logoWanted(os.Stdout) {\n\t\tmood, _ := searchCatMoment(true)\n\t\tprintLogoMood(os.Stdout, nil, mood)\n\t}\n\t// The policy is named before the generic advice: \"try fewer words\" is\n\t// wrong counsel for someone whose words were fine (#680). A filter the\n\t// caller set is the same kind of fact, and `deja last` has named it all\n\t// along (#715).\n\tswitch note := policyHiddenNote(policy.ActivationSearch, policyHidden); {\n\tcase note != \"\":\n\t\tfmt.Fprint(os.Stderr, note)\n\tcase activeFilters(o, sinceRaw, harnessRaw) != \"\":\n\t\tfmt.Fprintf(os.Stderr, \"deja: %q matched nothing under %s\\n\", o.Query, activeFilters(o, sinceRaw, harnessRaw))\n\t\tfmt.Fprint(os.Stderr, emptyRoleNote(dir, o.Role))\n\t\tfmt.Fprint(os.Stderr, olderThanWindow(dir, o.Since))\n\t\t// This branch does not go through printNoMatches, which is where\n\t\t// the line lives for the other miss, so it says it itself.\n\t\tfmt.Fprint(os.Stderr, ignoredHiddenNoteFor(\"answer\", index.IgnoredWithAllTerms(dir, query.Tokens(o.Query))))\n\tdefault:\n\t\treturn printNoMatchesHinted(os.Stderr, dir, o.Query, o.Regex, hinted) || hinted\n\t}\n\treturn false\n}\n\n// printSearchCapped says how much of a capped answer is shown.\nfunc printSearchCapped(o search.Options, shown int) {\n\t// The cap is silent everywhere else: 15 results look like the whole\n\t// answer, and nothing says another N are waiting behind --all. deja\n\t// narrates every other place the ladder hides a session, so it says\n\t// this one too.\n\t//\n\t// Except to a reader who already typed --all: there the list was cut by\n\t// an explicit --limit, or by the relevance tier's own retrieval window,\n\t// and neither of those lifts with the flag they are being sent to\n\t// (#1608). Say what is shown and leave the advice out.\n\ttotal := strconv.Itoa(o.Total)\n\tif o.TotalEstimated {\n\t\ttotal = \"about \" + total\n\t}\n\tif o.All {\n\t\tfmt.Fprintf(os.Stderr, \"deja: showing %d of %s\\n\", shown, total)\n\t} else {\n\t\tfmt.Fprintf(os.Stderr, \"deja: showing %d of %s — add --all to see the rest\\n\", shown, total)\n\t}\n}\n\n// printNeighbour narrates a co-occurrence swap. It is not a word form: the\n// corpus says these two words keep company, which is a different claim and\n// reads as a typo correction if it borrows the other sentence (#1786).\nfunc printNeighbour(w io.Writer, variants map[string][]string) {\n\tkeys := make([]string, 0, len(variants))\n\tfor token := range variants {\n\t\tkeys = append(keys, token)\n\t}\n\tsort.Strings(keys)\n\tfor _, token := range keys {\n\t\tfor _, variant := range variants[token] {\n\t\t\tif variant != \"\" && variant != token {\n\t\t\t\tfmt.Fprintf(w, \"deja: no session has those words together, so deja tried one this corpus keeps beside %q: %s\\n\", token, variant)\n\t\t\t}\n\t\t}\n\t}\n}\n\n// relevanceLead is the sentence above a relevance answer.\n//\n// It said \"no exact match\" whatever the answer held. The relevance tier is\n// also where a strict answer of fewer than thinAND sessions is published once\n// the ranking has been hung underneath it, and there the sentence is false:\n// over 93 two-word queries on a 2,422-session store, every one of the 20\n// answers labelled relevance carried a strict head of 1 to 9 sessions, so the\n// line disowned a real match every time it fired (#3815).\nfunc relevanceLead(strict int) string {\n\tif strict > 0 {\n\t\treturn fmt.Sprintf(\"deja: %s %s every word of the query; the rest below are ranked by relevance\", pluralSessions(strict), holdOrHolds(strict))\n\t}\n\treturn \"deja: no exact match; showing sessions ranked by relevance to the whole query\"\n}\n\nfunc holdOrHolds(n int) string {\n\tif n == 1 {\n\t\treturn \"holds\"\n\t}\n\treturn \"hold\"\n}\n\n// markStrictHits flags the hits of a relevance answer that hold every word of\n// the query, so a caller reading one hit is told what that hit is. The count\n// on the envelope says how many there are; the order does not, because the\n// merged ranking can put a ranked session above a strict one.\nfunc markStrictHits(hits []search.Hit, result index.SearchResult) []search.Hit {\n\tif result.Strict == 0 {\n\t\treturn hits\n\t}\n\tfor i := range hits {\n\t\thits[i].Strict = result.IsStrict(hits[i].Session)\n\t}\n\treturn hits\n}\n\nfunc printStemmed(w io.Writer, variants map[string][]string) {\n\tkeys := make([]string, 0, len(variants))\n\tfor token := range variants {\n\t\tkeys = append(keys, token)\n\t}\n\tsort.Strings(keys)\n\tfor _, token := range keys {\n\t\tfor _, variant := range variants[token] {\n\t\t\tif variant == \"\" {\n\t\t\t\tfmt.Fprintf(w, \"deja: ignoring %q — no session matches it together with the rest\\n\", token)\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tif variant != token {\n\t\t\t\tfmt.Fprintf(w, \"deja: no exact match, trying word forms: %s -> %s\\n\", token, variant)\n\t\t\t}\n\t\t}\n\t}\n}\n\n// otherWordFormsNote says that a word form the query did not use has sessions\n// of its own that this answer does not contain.\n//\n// The exact tier wins and stops, so `retry` returns what wrote \"retry\" and\n// never reaches \"retries\" — the stem tier below it only runs when exact comes\n// up empty. deja narrates every other time the ladder shapes an answer (close\n// spellings, dropped terms, the trust policy); this rung was the silent one,\n// and silence here reads as \"that is all there is\". Only the forms that bring\n// sessions the answer does not already hold are worth a line.\nfunc otherWordFormsNote(dir string, o query.Options, hits []search.Hit) string {\n\tif o.Regex || o.Tier != search.TierExact || len(hits) == 0 {\n\t\treturn \"\"\n\t}\n\tterms := query.Tokens(o.Query)\n\tif len(terms) == 0 || len(terms) > 4 {\n\t\treturn \"\"\n\t}\n\tforms := index.OtherWordForms(dir, terms)\n\tif len(forms) == 0 {\n\t\treturn \"\"\n\t}\n\tvar flat []string\n\tfor _, list := range forms {\n\t\tflat = append(flat, list...)\n\t}\n\t// Spoken sessions only: deja prints this very note into terminals, the\n\t// transcripts keep it, and the next index reads the forms deja generated\n\t// back as forms the store holds (#3820).\n\tcounts := index.TermSessionCountsSpoken(dir, flat)\n\tvar parts []string\n\tfor _, term := range terms {\n\t\tfor _, form := range forms[term] {\n\t\t\textra := counts[form] - sessionsHolding(hits, form)\n\t\t\tif extra <= 0 {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tparts = append(parts, fmt.Sprintf(\"%q in %d more\", form, extra))\n\t\t}\n\t}\n\tif len(parts) == 0 {\n\t\treturn \"\"\n\t}\n\treturn fmt.Sprintf(\"deja: word forms this answer leaves out: %s — search the form to see them\\n\", strings.Join(parts, \", \"))\n}\n\n// sessionsHolding counts the returned sessions that already contain a word\n// form, so the note reports what is missing rather than what is on the page.\nfunc sessionsHolding(hits []search.Hit, form string) int {\n\tn := 0\n\tfor _, h := range hits {\n\t\tfor _, m := range h.Session.Messages {\n\t\t\tif containsWord(strings.ToLower(m.Text), form) {\n\t\t\t\tn++\n\t\t\t\tbreak\n\t\t\t}\n\t\t}\n\t}\n\treturn n\n}\n\n// containsWord matches a whole word, not a substring: \"retry\" inside\n// \"retrying\" is a different form and counting it would hide the one the note\n// exists to name.\nfunc containsWord(low, word string) bool {\n\tfor i := 0; ; {\n\t\tj := strings.Index(low[i:], word)\n\t\tif j < 0 {\n\t\t\treturn false\n\t\t}\n\t\tstart := i + j\n\t\tend := start + len(word)\n\t\tbeforeOK := start == 0 || !isWordByte(low[start-1])\n\t\tafterOK := end == len(low) || !isWordByte(low[end])\n\t\tif beforeOK && afterOK {\n\t\t\treturn true\n\t\t}\n\t\ti = start + 1\n\t}\n}\n\nfunc isWordByte(b byte) bool {\n\treturn b >= 'a' && b <= 'z' || b >= 'A' && b <= 'Z' || b >= '0' && b <= '9' || b >= 0x80\n}\n\n// termCountLine names the terms that do match on their own, so \"try fewer\n// words\" says which. It stays quiet when every term is already unknown to the\n// store — there is nothing to drop then, and a row of zeroes is noise.\nfunc termCountLine(dir, q string) string {\n\tterms := query.Tokens(q)\n\tif len(terms) < 2 || len(terms) > 6 {\n\t\treturn \"\"\n\t}\n\tcounts := index.TermSessionCounts(dir, terms)\n\tvar parts []string\n\tfor _, t := range terms {\n\t\tif counts[t] > 0 {\n\t\t\tparts = append(parts, fmt.Sprintf(\"%q in %d\", t, counts[t]))\n\t\t}\n\t}\n\tif len(parts) == 0 || len(parts) == len(terms) && len(terms) > 3 {\n\t\treturn \"\"\n\t}\n\treturn fmt.Sprintf(\"deja: on their own: %s — no session has them together\\n\", strings.Join(parts, \", \"))\n}\n\n// printNoMatches says how big the store actually is, not how many sessions the\n// query happened to load.\n//\n// On the index-backed path the loaded set is empty by definition when nothing\n// matched, so this printed \"no matches in 0 indexed sessions\" for a perfectly\n// healthy index — and internal/index/manifest.go reserves that exact sentence\n// as the signature of a corrupt store, on the grounds that a reader told the\n// index holds zero sessions concludes the tool is broken rather than that\n// their query missed. It fired on every ordinary miss, so the signature could\n// not be used to recognise the failure it was written for (#637).\nfunc printNoMatches(w io.Writer, dir, q string, regex bool) (mistypedCommand bool) {\n\treturn printNoMatchesHinted(w, dir, q, regex, false)\n}\n\n// printNoMatchesHinted is printNoMatches for a search whose command hint was\n// already printed before it ran, so the miss does not say it twice.\nfunc printNoMatchesHinted(w io.Writer, dir, q string, regex, hinted bool) (mistypedCommand bool) {\n\t// An empty store is not a query problem: \"fewer words\" cannot help when\n\t// nothing is indexed, and `last`, `blame` and the brief all say what to do\n\t// instead. Search is the command a new machine reaches for first (#832).\n\tif n, err := index.SessionCount(dir); err == nil && n == 0 {\n\t\t// \"Zero indexed sessions\" has two very different causes, and the early\n\t\t// return named only the first: a machine with no history, and a machine\n\t\t// where the reader forgot everything themselves. `deja index` cannot\n\t\t// bring back a tombstoned session (#844).\n\t\tif note := hiddenByOwnSettings(); note != \"\" {\n\t\t\tfmt.Fprintf(w, \"deja: no matches for %q\\n\", q)\n\t\t\tfmt.Fprint(w, note)\n\t\t\treturn\n\t\t}\n\t\tfmt.Fprintln(w, emptyIndexHint(fmt.Sprintf(\"no matches for %q\", q)))\n\t\treturn\n\t}\n\t// Nothing to look up: very short tokens are dropped and punctuation is\n\t// trimmed, so this query never reached the index. \"Try fewer words\"\n\t// cannot be followed with one word, or none (#828). The message does not\n\t// state the rule — the cut is on bytes, so \"л\" and \"舵\" are long enough\n\t// while \"p\" is not, and a rule that reads false to half the world's\n\t// alphabets is worse than none.\n\t// Both sentences below are about the word index, and --re does not use it:\n\t// a regex is matched against the text itself, so an emoji it did not find\n\t// is a miss like any other rather than something deja cannot look up.\n\tif !regex && len(query.Tokens(q)) == 0 {\n\t\t// Length is the wrong reason for a query that holds no word at all: an\n\t\t// emoji is four bytes, and it was dropped for being a symbol. Sending\n\t\t// that reader after a longer word sends them after nothing (#2133).\n\t\tif !hasIndexableRune(q) {\n\t\t\tfmt.Fprintf(w, \"deja: nothing to search for in %q — deja indexes words, and emoji, symbols and punctuation are not words\\n\", q)\n\t\t\treturn\n\t\t}\n\t\tfmt.Fprintf(w, \"deja: nothing to search for in %q — every word in it is too short to look up\\n\", q)\n\t\treturn\n\t}\n\t// The size worth naming is the part of the store this path may read. Under\n\t// a trust rule the two differ, and \"no matches in 1 indexed session — try\n\t// fewer words\" sent the reader after a wording problem in a session the\n\t// rule never let search open (#986).\n\tif reach, trusted, total, ok := reachableSessionCount(dir); ok && reach == 0 && total > 0 {\n\t\tfmt.Fprintf(w, \"deja: no matches for %q\\n\", q)\n\t\t// Which rule emptied the path. Counting the ignore rule here (#2707)\n\t\t// put a store hidden by a path pattern under a sentence about the\n\t\t// trust policy, quoting a trust rule that allows everything.\n\t\tif trusted == 0 {\n\t\t\tfmt.Fprintf(w, \"deja: the trust policy withholds every indexed session from this path (%s: %s)%s\\n\",\n\t\t\t\tpolicy.ActivationSearch, policy.Load().Describe(policy.ActivationSearch), seePolicyFile())\n\t\t} else {\n\t\t\tfmt.Fprintf(w, \"deja: the ignore rule withholds every indexed session from this path (%s)%s\\n\",\n\t\t\t\tstrings.Join(policy.Load().IgnorePatterns(), \", \"), seePolicyFile())\n\t\t}\n\t\treturn\n\t} else if ok {\n\t\tfmt.Fprint(w, fitNotice(w, fmt.Sprintf(\"deja: no matches in %d indexed session%s — %s (query %q)\\n\", reach, pluralS(reach), missAdvice(q, regex), q)))\n\t} else if n, err := index.SessionCount(dir); err == nil {\n\t\tfmt.Fprint(w, fitNotice(w, fmt.Sprintf(\"deja: no matches in %d indexed session%s — %s (query %q)\\n\", n, pluralS(n), missAdvice(q, regex), q)))\n\t} else {\n\t\tfmt.Fprintf(w, \"deja: no matches — %s (query %q)\\n\", missAdvice(q, regex), q)\n\t}\n\t// Before advising fewer words: the sessions that hold every one of them may\n\t// exist and be covered by the ignore rule, in which case rewording is the\n\t// wrong advice and the count is the answer (#2562).\n\tif note := ignoredHiddenNoteFor(\"answer\", index.IgnoredWithAllTerms(dir, query.Tokens(q))); note != \"\" {\n\t\tfmt.Fprint(w, note)\n\t}\n\t// Which word to drop is the reader's next question, and deja read the\n\t// per-term counts to decide there was no intersection (#826). Not for a\n\t// pattern: its words are not looked up together, so \"no session has them\n\t// together\" is not why it missed.\n\tif line := termCountLine(dir, q); line != \"\" && !regex {\n\t\tfmt.Fprint(w, line)\n\t}\n\t// The first thing anyone types is a guess at a command name, and a wrong\n\t// guess falls through to search — where the advice is to use fewer words,\n\t// which cannot help someone who was not searching (#674). Falling through\n\t// stays the default; an empty result is where the other reading is worth\n\t// naming.\n\tif hint := commandHint(q); hint != \"\" && !hinted {\n\t\tfmt.Fprint(w, hint)\n\t\tmistypedCommand = true\n\t}\n\t// Last of the reasons a miss is not a miss, and the only one where deja is\n\t// holding the answer rather than withholding it.\n\tif hint := roleServedHint(dir, q); hint != \"\" {\n\t\tfmt.Fprint(w, hint)\n\t}\n\tif note := hiddenByOwnSettings(); note != \"\" {\n\t\tfmt.Fprint(w, note)\n\t}\n\treturn mistypedCommand\n}\n\n// missAdvice is what to try after a miss. \"Try --re\" said to someone who used\n// it is advice they already followed; a pattern misses for its own reasons —\n// an anchor, since ^ and $ hold at each line, or being stricter than the text.\nfunc missAdvice(q string, regex bool) string {\n\tif !regex {\n\t\treturn \"try fewer words or --re\"\n\t}\n\tif re, err := syntax.Parse(q, syntax.Perl); err == nil && hasAnchor(re) {\n\t\treturn \"try the pattern without ^ or $, a looser one, or plain words without --re\"\n\t}\n\treturn \"try a looser pattern, or plain words without --re\"\n}\n\n// hasAnchor reports a ^ or $ in a parsed pattern; one inside a class or\n// escaped is a character, not an anchor.\nfunc hasAnchor(re *syntax.Regexp) bool {\n\tswitch re.Op { //nolint:exhaustive // only the four anchor ops answer here; the rest recurse below\n\tcase syntax.OpBeginLine, syntax.OpEndLine, syntax.OpBeginText, syntax.OpEndText:\n\t\treturn true\n\t}\n\treturn slices.ContainsFunc(re.Sub, hasAnchor)\n}\n\n// roleServedHint names the answer deja is holding but ranking will never\n// return.\n//\n// Commands, file lists and edits are 38% of the record log and none of it\n// reaches ranking, on purpose: a path that happens to contain the words of a\n// question is not an answer to it. `how` and `blame` serve those roles when\n// asked for by role — so a word that lives only in a command or a filename\n// misses here while both of them answer it, and \"try fewer words\" is counsel no\n// rewording can follow, the same wrong turn #2562 and #686 closed for the other\n// reasons a miss is not a miss (#2634).\n//\n// Neither half costs a record-log scan: the commands table is a prebuilt\n// artefact and the touched-file lists are one metadata read.\nfunc roleServedHint(dir, q string) string {\n\tterms := query.Tokens(q)\n\tif len(terms) == 0 {\n\t\treturn \"\"\n\t}\n\tvar out strings.Builder\n\tif n := commandsMatchingWords(dir, terms); n > 0 {\n\t\tmatch := \"match\"\n\t\tif n == 1 {\n\t\t\tmatch = \"matches\"\n\t\t}\n\t\tout.WriteString(howOfferLine(n, match, terms))\n\t}\n\tif n, name := sessionsTouchingWords(dir, terms); n > 0 {\n\t\tfmt.Fprintf(&out, \"deja: %d session%s touched %s — `deja blame %s`\\n\",\n\t\t\tn, pluralS(n), search.SafeLine(name), pasteSafe(name))\n\t}\n\treturn out.String()\n}\n\n// commandsMatchingWords counts the commands in the recurring-command table that\n// hold every one of these words.\n//\n// Commands rather than sessions, because the table cannot give an honest\n// session count here: one session that ran two matching commands appears under\n// both, ByProject is capped at commandProjectCap, and summing either would\n// state a number that is wrong in a direction the reader cannot see. How many\n// commands match is exact, and it is the number that decides whether `deja how`\n// is worth typing.\n//\n// The trust policy keys on the project, which is what the table carries, so a\n// command is counted only where a project this path may read has it. The ignore\n// rule matches on path or project and the table has no path, so a session\n// ignored by path alone is not excluded here — the same gap `hook-tool` has.\nfunc commandsMatchingWords(dir string, terms []string) int {\n\tpol := policy.Load()\n\tn := 0\n\tfor _, u := range index.ReadCommands(dir) {\n\t\tlow := strings.ToLower(u.Command)\n\t\tmatched := true\n\t\tfor _, t := range terms {\n\t\t\tif !commandMentions(low, strings.ToLower(t)) {\n\t\t\t\tmatched = false\n\t\t\t\tbreak\n\t\t\t}\n\t\t}\n\t\tif !matched {\n\t\t\tcontinue\n\t\t}\n\t\tfor proj := range u.ByProject {\n\t\t\tif pol.Allows(policy.ActivationSearch, proj) && !pol.Ignored(\"\", proj) {\n\t\t\t\tn++\n\t\t\t\tbreak\n\t\t\t}\n\t\t}\n\t}\n\treturn n\n}\n\n// howOfferLine is the half of the hint that offers `deja how`.\n//\n// The words go over as words: `deja how` ANDs its arguments and a quoted\n// phrase becomes one term it then requires contiguously, so quoting the whole\n// query handed over a command that answers \"no command on this machine\n// mentions …\" under a line that had just counted three (#2768).\nfunc howOfferLine(n int, match string, terms []string) string {\n\t// A term can start with a dash — someone asking about `-run` or `--limit`\n\t// — and `deja how` would read it as a flag it does not have, or as one it\n\t// does and swallow the next word. The command's own escape says the rest\n\t// is the query.\n\tdashed := \"\"\n\tfor _, t := range terms {\n\t\tif strings.HasPrefix(t, \"-\") {\n\t\t\tdashed = \"-- \"\n\t\t\tbreak\n\t\t}\n\t}\n\treturn fmt.Sprintf(\"deja: %d command%s this machine ran %s it — `deja how %s%s`\\n\",\n\t\tn, pluralS(n), match, dashed, pasteSafeWords(terms))\n}\n\n// sessionsTouchingWords counts the sessions that touched a file whose name\n// holds every one of these words, and names one such file so the reader has\n// something to hand to blame.\nfunc sessionsTouchingWords(dir string, terms []string) (int, string) {\n\tmetas, err := index.AllMeta(dir)\n\tif err != nil {\n\t\treturn 0, \"\"\n\t}\n\tpol := policy.Load()\n\tn, name := 0, \"\"\n\tfor _, meta := range metas {\n\t\tif !pol.Allows(policy.ActivationSearch, meta.Project) || pol.Ignored(meta.Path, meta.Project) {\n\t\t\tcontinue\n\t\t}\n\t\tfor _, p := range meta.Touched {\n\t\t\tbase := filepath.Base(filepath.FromSlash(p))\n\t\t\tlow := strings.ToLower(base)\n\t\t\tmatched := true\n\t\t\tfor _, t := range terms {\n\t\t\t\tif !strings.Contains(low, strings.ToLower(t)) {\n\t\t\t\t\tmatched = false\n\t\t\t\t\tbreak\n\t\t\t\t}\n\t\t\t}\n\t\t\tif matched {\n\t\t\t\tn++\n\t\t\t\tif name == \"\" {\n\t\t\t\t\tname = base\n\t\t\t\t}\n\t\t\t\tbreak\n\t\t\t}\n\t\t}\n\t}\n\treturn n, name\n}\n\n// hiddenByOwnSettings names the states the reader created themselves and can\n// undo. \"Forgotten\", \"excluded by my own pattern\" and \"never happened\" were one\n// answer, and \"try fewer words\" is wrong counsel for the first two (#686).\nfunc hiddenByOwnSettings() string {\n\tvar parts []string\n\tif n := len(index.Tombstones()); n > 0 {\n\t\tparts = append(parts, fmt.Sprintf(\"%d session%s forgotten (`deja forget --list`)\", n, pluralS(n)))\n\t}\n\t// Counted apart, because they are different rules and the reader acts on\n\t// them differently: a project pattern hides work deja read, and a\n\t// `harness:` line means a whole store was never walked (#3499). Calling\n\t// both \"project patterns\" told someone who had excluded their only store\n\t// that a project of theirs was hidden.\n\tstores := sources.ExcludedHarnesses()\n\tif n := projectExcludePatterns(); n > 0 {\n\t\tparts = append(parts, fmt.Sprintf(\"%d project pattern%s excluded from indexing (%s)\", n, pluralS(n), sources.ExcludePath()))\n\t}\n\tif n := len(stores); n > 0 {\n\t\tsettings := map[string]bool{}\n\t\tfor name := range stores {\n\t\t\tsettings[harnessExclusionSource(name)] = true\n\t\t}\n\t\tnames := make([]string, 0, len(settings))\n\t\tfor name := range settings {\n\t\t\tnames = append(names, name)\n\t\t}\n\t\tsort.Strings(names)\n\t\tparts = append(parts, fmt.Sprintf(\"%d store%s not read at all (%s)\", n, pluralS(n), strings.Join(names, \", \")))\n\t}\n\tif len(parts) == 0 {\n\t\treturn \"\"\n\t}\n\treturn \"deja: this machine also has \" + strings.Join(parts, \", \") + \"\\n\"\n}\n\n// commandHint reads an empty search as a possible mistyped subcommand. It\n// stays quiet unless a command name is within one edit of the first word: an\n// empty search is usually an empty search, and a hint on every miss is noise\n// that teaches people to skip the last line.\nfunc commandHint(q string) string {\n\tfirst, _, _ := strings.Cut(strings.TrimSpace(q), \" \")\n\tif first == \"\" || strings.HasPrefix(first, \"-\") {\n\t\treturn \"\"\n\t}\n\t// A hint is about a guess at a command, and a guess is short: a command\n\t// with an argument or two. \"hook up the pool\" is a sentence, and a hint\n\t// there is noise on top of a search that already failed — the same lesson\n\t// #715 learned about short words (#2115).\n\tif !looksLikeAnInvocation(q) {\n\t\treturn \"\"\n\t}\n\tlow := strings.ToLower(first)\n\t// A guess with an exact answer behind it. `deja hook context` is the\n\t// hyphen-free spelling of a command that exists, and the candidate list\n\t// below drops every `hook-` name on the grounds that plumbing is not\n\t// something anyone means to type — which is right about proposing it and\n\t// wrong about hiding it from the reader who typed its own stem (#2115).\n\tif hint := hyphenatedCommandHint(q, low); hint != \"\" {\n\t\treturn hint\n\t}\n\t// The word deja's own MCP tool is called, and the one the documentation\n\t// uses throughout, so `deja recall <words>` is a fair guess at the shell\n\t// form. Nothing is near it by name, so the hint said nothing at all —\n\t// the same shape as the curated answers below (#2115).\n\tif low == \"recall\" {\n\t\trest := strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(q), first))\n\t\tif rest != \"\" {\n\t\t\treturn fmt.Sprintf(\"deja: %q is what the MCP tool is called — from a shell it is `deja %q`, and `deja hook-prompt` is the per-prompt recall\\n\", first, rest)\n\t\t}\n\t\treturn fmt.Sprintf(\"deja: %q is what the MCP tool is called — from a shell it is `deja <query>`, and `deja hook-prompt` is the per-prompt recall\\n\", first)\n\t}\n\t// A one- or two-letter word is a word, not a mistyped command name. Any\n\t// prefix counts as \"near\" — so \"a\" reached `deja aider` and every sentence\n\t// starting with a short word got a hint (#715, my own regression from\n\t// #674).\n\tif len([]rune(low)) < 4 {\n\t\treturn \"\"\n\t}\n\tif _, ok := commands[low]; ok {\n\t\treturn \"\" // reached search only because it was used as a word\n\t}\n\tif slices.Contains([]string{\"search\", \"show\", \"last\", \"aider\", \"goose\"}, low) {\n\t\treturn \"\"\n\t}\n\t// The switch in run() handles these before the map is consulted, so the\n\t// map alone would miss the commonest words of all — \"serch\" landed on\n\t// \"bench\" while `search` was one letter away.\n\t// The same shape for the other undo nobody can guess: removing a note is\n\t// `forget` on the note's own id, and the reader who typed this has no way\n\t// to know a note has an id at all (#1085).\n\t// brew and npm call it upgrade, and three edits is too far for the\n\t// nearest-name match to reach `update`. The search still runs: \"upgrade\"\n\t// is also something people search their history for.\n\tif strings.EqualFold(first, \"upgrade\") {\n\t\treturn \"deja: \\\"upgrade\\\" is not a command — `deja update` updates deja itself\\n\"\n\t}\n\tif strings.EqualFold(first, \"unpromote\") || strings.EqualFold(first, \"demote\") {\n\t\treturn \"deja: \\\"\" + first + \"\\\" is not a command — `deja promote <id> --state rejected` takes a decision back, and `deja forget --session deja-note-<harness>-<id>` removes the note itself\\n\"\n\t}\n\tnear := nearestTarget(first, commandHintNames())\n\tif near == \"\" {\n\t\treturn \"\"\n\t}\n\t// \"unforget\" is the one wrong guess with a real answer behind it, and\n\t// `deja forget` alone sends the reader back to a list that used to name\n\t// nothing (#919).\n\tif strings.EqualFold(first, \"unforget\") {\n\t\treturn \"deja: \\\"unforget\\\" is not a command — `deja forget --unforget <id>` is, and `deja forget --list` names the ids\\n\"\n\t}\n\treturn fmt.Sprintf(\"deja: %q is not a command — did you mean `deja %s`?\\n\", first, near)\n}\n\nfunc commandHintNames() []string {\n\tnames := []string{\"search\", \"show\", \"last\", \"aider\", \"goose\"}\n\tfor name := range commands {\n\t\t// Hidden plumbing is not something anyone means to type.\n\t\tif strings.HasPrefix(name, \"-\") || strings.HasPrefix(name, \"hook-\") {\n\t\t\tcontinue\n\t\t}\n\t\tnames = append(names, name)\n\t}\n\tsort.Strings(names)\n\treturn names\n}\n\n// hyphenatedCommandHint answers the guess that spelled a hyphenated command\n// with a space: the two words joined name a real one, or the first word is the\n// stem of some and there is no second word to join (#2115).\nfunc hyphenatedCommandHint(q, low string) string {\n\trest := strings.Fields(strings.TrimSpace(q))\n\tif len(rest) > 1 {\n\t\tjoined := low + \"-\" + strings.ToLower(rest[1])\n\t\tif _, ok := commands[joined]; ok {\n\t\t\treturn fmt.Sprintf(\"deja: %q is not a command — did you mean `deja %s`?\\n\", low+\" \"+rest[1], joined)\n\t\t}\n\t}\n\t// Only the stem on its own. With words after it that do not join into a\n\t// command, the reader is searching — \"hook up the pool\" is a sentence, and\n\t// a hint about `hook-context` there is noise on top of a failed search.\n\tif len(rest) != 1 {\n\t\treturn \"\"\n\t}\n\tvar stems []string\n\tfor name := range commands {\n\t\tif strings.HasPrefix(name, low+\"-\") {\n\t\t\tstems = append(stems, name)\n\t\t}\n\t}\n\tif len(stems) == 0 {\n\t\treturn \"\"\n\t}\n\tsort.Strings(stems)\n\tif len(stems) > 3 {\n\t\tstems = stems[:3]\n\t}\n\treturn fmt.Sprintf(\"deja: %q is not a command on its own — `deja %s` and the rest of that family are; `deja help` names them\\n\",\n\t\tlow, strings.Join(stems, \"`, `deja \"))\n}\n\n// looksLikeAnInvocation separates a guess at a command from prose. A command\n// and an argument or two is short; \"recall the decision we made about the pool\"\n// is a sentence, and the hint is about the first kind (#2115).\nfunc looksLikeAnInvocation(q string) bool {\n\treturn len(strings.Fields(q)) <= 3\n}\n\n// hasIndexableRune says whether a query holds anything the index could have\n// kept. Letters and digits are what the tokenizer keeps; everything else is a\n// separator, which is why an emoji-only query reaches the index as nothing.\nfunc hasIndexableRune(q string) bool {\n\tfor _, r := range q {\n\t\tif unicode.IsLetter(r) || unicode.IsDigit(r) {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\n// sinceRawArg recovers the text the reader typed after --since. parseSearch\n// keeps only the parsed duration, and the search path had nothing else to hand\n// activeFilters, so it reported \"since 720h0m0s\" for `--since 30d` (#1059).\n// Last wins, as in parseSearch.\nfunc sinceRawArg(args []string) string {\n\targs = splitEqualsForms(args)\n\traw := \"\"\n\tfor i := 0; i+1 < len(args); i++ {\n\t\tif args[i] == \"--since\" {\n\t\t\traw = args[i+1]\n\t\t}\n\t}\n\treturn raw\n}\n\n// olderThanWindow names the store's own range when --since cut off everything\n// in it. Without it someone returning to a year-old store is told their query\n// matched nothing — advice about the query, when it was the window that\n// emptied the result and no query under it could have returned anything.\n// `deja stats` has said this since #854; search and `last` had not (#1059).\nfunc olderThanWindow(dir string, since time.Duration) string {\n\tif since <= 0 {\n\t\treturn \"\"\n\t}\n\t// Servable: this is advice on a search that came back empty, so the\n\t// sessions it counts have to be the ones search could have read (#2650).\n\tov, err := index.OverviewServable(dir)\n\tif err != nil || ov.Sessions == 0 || ov.Newest.IsZero() {\n\t\treturn \"\"\n\t}\n\tif !ov.Newest.Before(time.Now().Add(-since)) {\n\t\treturn \"\"\n\t}\n\treturn fmt.Sprintf(\"deja: every one of the %d indexed sessions is older than that window — the newest is %s\\n\",\n\t\tov.Sessions, ov.Newest.Local().Format(\"2006-01-02\"))\n}\n\n// checkHarness rejects a --harness value deja does not know. A typo used to be\n// indistinguishable from a real harness with no sessions — both said \"matched\n// nothing under harness X\" — so `--harness cluade` read as \"you have no claude\n// history\" instead of \"that is not a harness\". A known-but-empty harness is\n// still valid; only an unknown name is refused (#1113).\n// It also normalises, which is why it takes a pointer: the notes store is\n// stored as \"deja\" and narrated by the index run as \"notes\", and retrieval has\n// accepted both since #1888 — but this check ran first and refused the printed\n// name as a typo, so nothing below it ever saw the alias, and `deja stats`\n// compares the stored name exactly (#2191).\nfunc checkHarness(name *string) error {\n\tif *name == \"notes\" {\n\t\t*name = \"deja\"\n\t}\n\tif *name == \"\" || sources.IsKnownHarness(*name) {\n\t\treturn nil\n\t}\n\treturn fmt.Errorf(\"%q is not a harness deja knows — one of: %s\", *name, strings.Join(sources.HarnessNames(), \", \"))\n}\n\n// knownRoles is the set `--role` accepts. It lists the documented spellings the\n// help text prints plus \"tool-output\", the stored form \"tool\" is an alias for —\n// both reach tool records, so both must be accepted.\nvar knownRoles = []string{\n\t\"user\", \"assistant\", \"tool\", sources.RoleToolOutput,\n\tsources.RoleFiles, sources.RoleCommand, sources.RoleEdit, sources.RoleSummary,\n}\n\n// checkRole rejects a --role value that is not a known role. Like an unknown\n// --harness, a typo used to be indistinguishable from a real role with no\n// matches: `--role toool` said \"matched nothing under role toool\" instead of\n// naming the mistake (#1113).\nfunc checkRole(role string) error {\n\tif role == \"\" {\n\t\treturn nil\n\t}\n\tif slices.Contains(knownRoles, role) {\n\t\treturn nil\n\t}\n\treturn fmt.Errorf(\"%q is not a role deja knows — one of: %s\", role, strings.Join(knownRoles, \", \"))\n}\n\n// emptyRoleNote says when a role found nothing because the store holds none of\n// that kind, rather than because the query missed.\n//\n// deja advertises that it indexes the work and not only the talk, and a harness\n// that records no tool calls gives a transcript that looks complete: `--role\n// tool` came back the same way a bad query does, and the reader had no way to\n// tell \"not found\" from \"not recorded\" (#1321). Only asked when a role-filtered\n// search already returned nothing.\nfunc emptyRoleNote(dir, role string) string {\n\tif role == \"\" {\n\t\treturn \"\"\n\t}\n\tstored := role\n\tif role == \"tool\" {\n\t\tstored = sources.RoleToolOutput\n\t}\n\tif index.HasRecordOfRole(dir, stored) {\n\t\treturn \"\"\n\t}\n\treturn fmt.Sprintf(\"deja: this index holds no %s records at all — the harnesses it read do not write them, or wrote none yet\\n\", role)\n}\n\n// activeFilters names the filters a caller set, so an empty result can say\n// which of them emptied it rather than blaming the index. sinceRaw carries\n// what the reader actually typed: \"168h0m0s\" is not the flag they passed.\nfunc activeFilters(o search.Options, sinceRaw, harnessRaw string) string {\n\tvar parts []string\n\tif o.Harness != \"\" {\n\t\t// Same reason as sinceRaw: `--harness notes` is stored as \"deja\", and\n\t\t// telling someone their \"deja\" filter matched nothing names a flag\n\t\t// they did not pass (#2191).\n\t\tname := o.Harness\n\t\tif harnessRaw != \"\" {\n\t\t\tname = harnessRaw\n\t\t}\n\t\tparts = append(parts, fmt.Sprintf(\"harness %q\", name))\n\t}\n\tif o.Project != \"\" {\n\t\tparts = append(parts, fmt.Sprintf(\"project %q\", o.Project))\n\t}\n\tif o.Role != \"\" {\n\t\tparts = append(parts, fmt.Sprintf(\"role %q\", o.Role))\n\t}\n\tif o.Session != \"\" {\n\t\tparts = append(parts, fmt.Sprintf(\"session %q\", o.Session))\n\t}\n\t// The one filter this did not know about, and the one most likely to match\n\t// nothing: --from exists for the multi-machine case, and the name a reader\n\t// types comes off another machine. Unnamed, it fell through to \"no sessions\n\t// indexed yet — run `deja index`\" on a store that was fine (#2642).\n\tif o.From != \"\" {\n\t\tparts = append(parts, fmt.Sprintf(\"from %q\", o.From))\n\t}\n\t// The same predicate filterRecentSources uses. parseDur accepts a negative\n\t// duration, and a negative Since filters nothing — naming it would report a\n\t// filter that was never applied and hide the empty-store advice, which is\n\t// the right answer there.\n\tif o.Since > 0 {\n\t\tsince := sinceRaw\n\t\tif since == \"\" {\n\t\t\tsince = o.Since.String()\n\t\t}\n\t\tparts = append(parts, \"since \"+since)\n\t}\n\tswitch len(parts) {\n\tcase 0:\n\t\treturn \"\"\n\tcase 1:\n\t\treturn parts[0]\n\tdefault:\n\t\treturn strings.Join(parts[:len(parts)-1], \", \") + \" and \" + parts[len(parts)-1]\n\t}\n}\n\n// printSpellings names the words the close tier substituted. ctx uses this\n// rather than printFuzzy: \"did you mean the command\" is advice for a person\n// at a shell, and ctx is called by an agent that typed nothing.\nfunc printSpellings(w io.Writer, variants map[string][]string) {\n\tkeys := make([]string, 0, len(variants))\n\tfor token := range variants {\n\t\tkeys = append(keys, token)\n\t}\n\tsort.Strings(keys)\n\tfor _, token := range keys {\n\t\tfor _, variant := range variants[token] {\n\t\t\tif variant != token {\n\t\t\t\tfmt.Fprintf(w, \"deja: no exact match, trying close spellings: %s -> %s\\n\", token, variant)\n\t\t\t}\n\t\t}\n\t}\n}\n\nfunc printFuzzy(w io.Writer, variants map[string][]string) {\n\tprintSpellings(w, variants)\n\tkeys := make([]string, 0, len(variants))\n\tfor token := range variants {\n\t\tkeys = append(keys, token)\n\t}\n\tsort.Strings(keys)\n\tfor _, token := range keys {\n\t\tfor _, variant := range variants[token] {\n\t\t\t// A misspelled subcommand is searched for as a word: `deja\n\t\t\t// isntall` corrects to \"install\" and returns sessions that\n\t\t\t// mention installing, which is not what the typist wanted.\n\t\t\t// Spelled correctly it would have run the command, so the only\n\t\t\t// case this fires on is the one where the hint is wanted.\n\t\t\tif variant != token && isSubcommand(variant) {\n\t\t\t\tfmt.Fprintf(w, \"deja: `%s` is also a command — run `deja %s` if that is what you meant\\n\", variant, variant)\n\t\t\t\treturn\n\t\t\t}\n\t\t}\n\t}\n}\n\n// isSubcommand reports whether a word names something deja can run.\nfunc isSubcommand(word string) bool {\n\tif _, ok := commands[word]; ok {\n\t\treturn true\n\t}\n\tswitch word {\n\tcase \"show\", \"last\", \"help\":\n\t\treturn true\n\t}\n\treturn false\n}\n\n// noteAmbiguousPrefix says when a selector reached more than one session.\n//\n// The prefix picks the newest of its matches, which is the right default and\n// was a silent one: \"2\" resolved eleven sessions on a real store. `show`\n// learned to say so in #719 and #859; promote, handoff, resume and share\n// resolve the same way and still picked in silence — promote records a state\n// against whichever session it chose (#872).\nfunc noteAmbiguousPrefix(dir, id, action string) {\n\t// Counted under the rule the reader is searching by: a session the policy\n\t// withholds is not one they can reach with a longer prefix (#2401).\n\tpol := policy.Load()\n\tn := index.PrefixMatchesAllowed(dir, id, func(project string) bool {\n\t\treturn pol.Allows(policy.ActivationSearch, project)\n\t})\n\tif n <= 1 {\n\t\treturn\n\t}\n\t// When the matches are the same id in different harnesses there is no\n\t// longer prefix to reach for, and naming the harness is the only thing\n\t// that separates them (#719). The `harness:id` form is the one every\n\t// command that resolves a selector accepts — show/last also take\n\t// --harness, but promote/handoff/resume/share do not, so advising the\n\t// flag sent those readers into \"unknown flag --harness\".\n\tif hs := index.PrefixHarnesses(dir, id); len(hs) > 1 {\n\t\tforms := make([]string, len(hs))\n\t\tfor i, h := range hs {\n\t\t\tforms[i] = h + \":\" + id\n\t\t}\n\t\tfmt.Fprintf(os.Stderr, \"deja: %d sessions share the id %q — %s the most recent; name one as %s\\n\",\n\t\t\tlen(hs), id, action, strings.Join(forms, \" or \"))\n\t\treturn\n\t}\n\t// \"A longer prefix\" is not available when the reader copied an elided id\n\t// off a result line: the characters that would disambiguate are the ones\n\t// the elision replaced (#859).\n\tadvice := \"use a longer prefix for another\"\n\tif strings.Contains(id, \"…\") {\n\t\tadvice = \"the ids differ in the middle the line elides — `deja last` prints them whole\"\n\t}\n\tfmt.Fprintf(os.Stderr, \"deja: %d sessions match %q — %s the most recent; %s\\n\", n, id, action, advice)\n}\n\n// ambiguousJSONPrefix refuses a --json read whose prefix names more than one\n// session, and says what separates them.\nfunc ambiguousJSONPrefix(dir, id string) error {\n\tpol := policy.Load()\n\tn := index.PrefixMatchesAllowed(dir, id, func(project string) bool {\n\t\treturn pol.Allows(policy.ActivationSearch, project)\n\t})\n\tif n <= 1 {\n\t\treturn nil\n\t}\n\tif hs := index.PrefixHarnesses(dir, id); len(hs) > 1 {\n\t\treturn fmt.Errorf(\"%d sessions share the id %q — --json reads one; add --harness %s\", len(hs), id, strings.Join(hs, \" or --harness \"))\n\t}\n\treturn fmt.Errorf(\"%d sessions match %q — --json reads one; use a longer prefix (`deja last` prints ids whole)\", n, id)\n}\n\n// searchAllows is the rule the ambiguity counts are taken under (#2401).\nfunc searchAllows() func(string) bool {\n\tpol := policy.Load()\n\treturn func(project string) bool { return pol.Allows(policy.ActivationSearch, project) }\n}\n\n// ambiguousJSONPrefixIn is ambiguousJSONPrefix within one harness: --harness\n// narrows the prefix, and a prefix it still leaves ambiguous is refused the\n// same way.\nfunc ambiguousJSONPrefixIn(dir, id, harness string) error {\n\tif n := index.PrefixMatchesIn(dir, id, harness, searchAllows()); n > 1 {\n\t\treturn fmt.Errorf(\"%d %s sessions match %q — --json reads one; use a longer prefix (`deja last` prints ids whole)\", n, harness, id)\n\t}\n\treturn nil\n}\n\n// noteAmbiguousPrefixIn is noteAmbiguousPrefix within one harness.\nfunc noteAmbiguousPrefixIn(dir, id, harness, action string) {\n\tif n := index.PrefixMatchesIn(dir, id, harness, searchAllows()); n > 1 {\n\t\tfmt.Fprintf(os.Stderr, \"deja: %d %s sessions match %q — %s the most recent; use a longer prefix for another\\n\", n, harness, id, action)\n\t}\n}\n\n// pickedOnScreen is the session the interactive screen handed to resume or\n// handoff. It is looked up by its exact identity, with no refresh first: after\n// an upgrade the refresh is a full rebuild, and the person who picked a\n// session watched \"waiting for it to finish\" under a closed screen. And an id\n// is not a prefix: one that starts another session's id handed off \"the most\n// recent\" of them, which need not be the one picked.\nvar pickedOnScreen *model.Session\n\nfunc findByPrefix(dir, p string) (model.Session, bool, error) { //nolint:unparam // handoff.go and coverage_extra_test.go read the error\n\tif s := pickedOnScreen; s != nil && p == s.ID {\n\t\tif full, ok, err := index.FindByIdentity(dir, s.Harness, s.ID); err == nil && ok {\n\t\t\treturn full, true, nil\n\t\t}\n\t}\n\tif err := ensureForCLIRead(dir); err == nil {\n\t\tif s, ok, err := lookupUnlessNew(dir, func() (model.Session, bool, error) { return index.FindByPrefix(dir, p) }); err == nil {\n\t\t\tif ok {\n\t\t\t\tnoteForgottenSource(s, p, true)\n\t\t\t}\n\t\t\treturn s, ok, nil\n\t\t}\n\t}\n\tss := loadFileSources()\n\tss = append(ss, sources.LoadOpencodePrefix(p)...)\n\ts, ok := search.FindByPrefix(ss, p)\n\treturn s, ok, nil\n}\n\n// findByPrefixHarness resolves an id prefix within one harness, so the\n// documented \"deja show <id-prefix> --harness name\" form works.\n// The prefix is resolved among that harness's sessions: picking the newest\n// across every harness and then refusing it said no session matches while one\n// in the named harness started with the prefix.\nfunc findByPrefixHarness(dir, p, harness string) (model.Session, bool) {\n\tif err := ensureForCLIRead(dir); err == nil {\n\t\tif s, ok, err := lookupUnlessNew(dir, func() (model.Session, bool, error) { return index.FindByPrefixIn(dir, p, harness) }); err == nil {\n\t\t\tif ok {\n\t\t\t\tnoteForgottenSource(s, p, true)\n\t\t\t}\n\t\t\treturn s, ok\n\t\t}\n\t}\n\tvar ss []model.Session\n\tfor _, s := range append(loadFileSources(), sources.LoadOpencodePrefix(p)...) {\n\t\tif strings.EqualFold(s.Harness, harness) {\n\t\t\tss = append(ss, s)\n\t\t}\n\t}\n\treturn search.FindByPrefix(ss, p)\n}\n\n// ensureForCLIRead brings the index up to date before `last` or `show` reads\n// it, unless another deja holds the index lock. A hook refresh or `deja index`\n// holds it for its whole pass, and a scheduled `deja last` sat at no CPU for\n// over an hour behind them while the snapshot on disk had the answer. The\n// holder may be a reader that updates nothing, so the refresh goes to the\n// detached warmup, as a search's does. The line goes out once: `show\n// --harness` comes through here twice when the exact id misses.\nfunc ensureForCLIRead(dir string) error {\n\tbusy, err := index.EnsureUnlessBusy(dir, os.Stderr)\n\tansweredFromSnapshot.Store(busy)\n\tif line := manualIndexLine(dir); err == nil && line != \"\" {\n\t\tsaidManualIndex.Do(func() { fmt.Fprintln(os.Stderr, line) })\n\t}\n\tif busy {\n\t\trequestWarmup(dir)\n\t\tsaidReadingAsItWas.Do(func() {\n\t\t\tc := index.SnapshotCoverage(dir)\n\t\t\tc.Stale = true\n\t\t\tfmt.Fprintln(os.Stderr, \"deja: \"+coverageLine(c))\n\t\t})\n\t}\n\treturn err\n}\n\nvar saidReadingAsItWas sync.Once\n\n// saidManualIndex keeps the index-date line to one per command.\nvar saidManualIndex sync.Once\n\n// answeredFromSnapshot is whether the last ensureForCLIRead skipped the update\n// because another deja held the lock.\nvar answeredFromSnapshot atomic.Bool\n\n// lookupUnlessNew runs an id lookup against the snapshot and, when it misses\n// while another deja holds the lock, waits for the index and looks again. A\n// lock held at session start is a hook refresh reading the session that just\n// began, so the id someone copied from it is the one the snapshot cannot have\n// yet: answering \"no session matches\" for it at once was worse than the wait\n// the snapshot read saves.\nfunc lookupUnlessNew(dir string, find func() (model.Session, bool, error)) (model.Session, bool, error) {\n\ts, ok, err := find()\n\tif err != nil || ok || !answeredFromSnapshot.Load() {\n\t\treturn s, ok, err\n\t}\n\tif index.Ensure(dir, \"\", false, os.Stderr) != nil {\n\t\treturn s, ok, err\n\t}\n\treturn find()\n}\n\nfunc recent(dir string, n int) ([]model.Session, error) {\n\treturn recentMatching(dir, n, search.Options{})\n}\n\nfunc recentMatching(dir string, n int, o search.Options) ([]model.Session, error) {\n\tif err := ensureForCLIRead(dir); err == nil {\n\t\tif o.Role != \"\" {\n\t\t\t// The role has to travel into the index query, not just the filter\n\t\t\t// below: a scan with no role set drops file, command and edit\n\t\t\t// records on the way out — they are indexed but served only when\n\t\t\t// asked for — so `last --role files` saw sessions with the very\n\t\t\t// records it was selecting on already removed.\n\t\t\tss, err := index.SearchWithRecovery(dir, search.Options{All: true, Role: o.Role}, io.Discard)\n\t\t\tif err == nil {\n\t\t\t\tss = filterRecentSources(ss, o)\n\t\t\t\treturn search.Recent(ss, n), nil\n\t\t\t}\n\t\t} else if ss, _, err := index.RecentMatchingCounted(dir, n, o); err == nil {\n\t\t\treturn ss, nil\n\t\t}\n\t}\n\tss := filterRecentSources(loadFileSources(), o)\n\tif o.Harness == \"\" || o.Harness == \"opencode\" {\n\t\tss = append(ss, filterRecentSources(sources.LoadOpencodeRecent(n), o)...)\n\t}\n\treturn search.Recent(ss, n), nil\n}\n\nvar lastFlags = []string{\"--json\", \"--project\", \"--harness\", \"--from\", \"--since\", \"--role\", \"--limit\"}\n\nfunc parseLast(args []string) (int, search.Options, string, error) {\n\tsinceRaw := \"\"\n\tn := 10\n\tseenN := false\n\to := search.Options{}\n\tfor i := 0; i < len(args); i++ {\n\t\ta := args[i]\n\t\tswitch a {\n\t\tcase \"--json\":\n\t\t\to.JSON = true\n\t\tcase \"--harness\", \"--project\", \"--since\", \"--role\", \"--from\":\n\t\t\tif i+1 >= len(args) {\n\t\t\t\treturn n, o, sinceRaw, fmt.Errorf(\"%s needs value\", a)\n\t\t\t}\n\t\t\ti++\n\t\t\tv := args[i] //nolint:gosec // bounds checked before i++\n\t\t\t// Empty is how \"no filter\" is spelled inside deja, so an empty\n\t\t\t// argument reached the search as no filter at all and a scripted\n\t\t\t// `--project \"$PROJECT\"` with the variable unset quietly returned\n\t\t\t// the whole store (#1612). It is the same mistake as leaving the\n\t\t\t// value off, so it gets the same sentence.\n\t\t\tif strings.TrimSpace(v) == \"\" {\n\t\t\t\treturn n, o, sinceRaw, fmt.Errorf(\"%s needs value\", a)\n\t\t\t}\n\t\t\tswitch a {\n\t\t\tcase \"--harness\":\n\t\t\t\to.Harness = v\n\t\t\tcase \"--project\":\n\t\t\t\to.Project = v\n\t\t\tcase \"--role\":\n\t\t\t\to.Role = v\n\t\t\tcase \"--from\":\n\t\t\t\to.From = v\n\t\t\tdefault:\n\t\t\t\td, err := parseDur(v)\n\t\t\t\tif err != nil {\n\t\t\t\t\treturn n, o, sinceRaw, err\n\t\t\t\t}\n\t\t\t\to.Since = d\n\t\t\t\tsinceRaw = v\n\t\t\t}\n\t\tdefault:\n\t\t\tif strings.HasPrefix(a, \"-\") {\n\t\t\t\tif flagName(a) == \"--limit\" {\n\t\t\t\t\t// The two commands beside this one take --limit, so the\n\t\t\t\t\t// reader is carrying it over rather than guessing; the\n\t\t\t\t\t// count last takes is a bare argument (#3405).\n\t\t\t\t\treturn n, o, sinceRaw, fmt.Errorf(\"last: unknown flag %q — the count is a bare argument, `deja last 3`\", a)\n\t\t\t\t}\n\t\t\t\treturn n, o, sinceRaw, unknownFlag(\"last\", a, lastFlags)\n\t\t\t}\n\t\t\t// The only bare argument last takes is the count. Dropping anything\n\t\t\t// else in silence answered `deja last api-gateway` — the filter the\n\t\t\t// help spells `--project api-gateway` — with ten sessions from every\n\t\t\t// project and no sign the word did nothing (#1618).\n\t\t\tx, err := strconv.Atoi(a)\n\t\t\tif err != nil || x < 1 {\n\t\t\t\treturn n, o, sinceRaw, fmt.Errorf(\"last: %q is not a count — use `deja last 5`, or --project/--harness to narrow\", a)\n\t\t\t}\n\t\t\tif seenN {\n\t\t\t\treturn n, o, sinceRaw, fmt.Errorf(\"last takes one count, got %d and %q\", n, a)\n\t\t\t}\n\t\t\tn, seenN = x, true\n\t\t}\n\t}\n\treturn n, o, sinceRaw, nil\n}\n\nfunc filterRecentSources(ss []model.Session, o search.Options) []model.Session {\n\t// These are sessions read straight off this machine's stores, so they are\n\t// local by definition: asking for another machine's work must not hand\n\t// back this one's.\n\tif o.From != \"\" && !strings.EqualFold(o.From, \"local\") {\n\t\treturn nil\n\t}\n\tif o.Harness == \"\" && o.Project == \"\" && o.Since <= 0 && o.Role == \"\" {\n\t\treturn ss\n\t}\n\tcut := time.Time{}\n\tif o.Since > 0 {\n\t\tcut = time.Now().Add(-o.Since)\n\t}\n\tout := make([]model.Session, 0, len(ss))\n\tproject := strings.ToLower(o.Project)\n\tfor _, s := range ss {\n\t\tif o.Harness != \"\" && s.Harness != o.Harness {\n\t\t\tcontinue\n\t\t}\n\t\tif project != \"\" && !strings.Contains(strings.ToLower(s.Project), project) {\n\t\t\tcontinue\n\t\t}\n\t\tif !cut.IsZero() && s.Updated.Before(cut) {\n\t\t\tcontinue\n\t\t}\n\t\tif o.Role != \"\" && !sessionHasRole(s, o.Role) {\n\t\t\tcontinue\n\t\t}\n\t\tout = append(out, s)\n\t}\n\treturn out\n}\n\n// sessionHasRole accepts the role names the help text documents. `--role tool`\n// is what `deja help` promises and \"tool-output\" is what is stored, so the\n// documented spelling matched nothing here while `deja search --role tool` —\n// which grew the alias in #623 — worked (#717).\nfunc sessionHasRole(s model.Session, role string) bool {\n\tfor _, m := range s.Messages {\n\t\tif m.Role == role || (role == \"tool\" && m.Role == \"tool-output\") {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\nfunc firstUserTitle(s model.Session) string {\n\tfor _, msg := range s.Messages {\n\t\tif msg.Role != \"user\" {\n\t\t\tcontinue\n\t\t}\n\t\tt := strings.Join(strings.Fields(msg.Text), \" \")\n\t\tr := []rune(t)\n\t\tif len(r) > 60 {\n\t\t\treturn strings.TrimSpace(string(r[:60])) + \"…\"\n\t\t}\n\t\treturn t\n\t}\n\treturn \"\"\n}\n\nfunc parseSearch(args []string) (search.Options, error) {\n\to := search.Options{}\n\tvar q []string\n\t// --limit=100 used to fall through and be searched for as a query term,\n\t// silently returning results for a different question than the one asked.\n\targs = splitEqualsForms(args)\n\tfor i := 0; i < len(args); i++ {\n\t\ta := args[i]\n\t\tif a == \"--\" {\n\t\t\t// End of options: the rest is the query verbatim, even a word that\n\t\t\t// spells a flag. Without this there is no way to search for the\n\t\t\t// literal text of a flag name — `deja -- --json` kept parsing\n\t\t\t// --json as the flag and left \"--\" stranded in the query.\n\t\t\tq = append(q, args[i+1:]...)\n\t\t\tbreak\n\t\t}\n\t\tswitch a {\n\t\tcase \"--json\":\n\t\t\to.JSON = true\n\t\tcase \"--re\":\n\t\t\to.Regex = true\n\t\tcase \"--all\":\n\t\t\to.All = true\n\t\tcase \"--no-embed\":\n\t\t\to.NoEmbed = true\n\t\tcase \"--harness\", \"--project\", \"--since\", \"--role\", \"--limit\", \"--session\", \"--sort\":\n\t\t\tif i+1 >= len(args) {\n\t\t\t\treturn o, fmt.Errorf(\"%s needs value\", a)\n\t\t\t}\n\t\t\ti++\n\t\t\tv := args[i]\n\t\t\t// Empty is how \"no filter\" is spelled inside deja, so an empty\n\t\t\t// argument reached the search as no filter at all and a scripted\n\t\t\t// `--project \"$PROJECT\"` with the variable unset quietly returned\n\t\t\t// the whole store (#1612). It is the same mistake as leaving the\n\t\t\t// value off, so it gets the same sentence.\n\t\t\tif strings.TrimSpace(v) == \"\" {\n\t\t\t\treturn o, fmt.Errorf(\"%s needs value\", a)\n\t\t\t}\n\t\t\tswitch a {\n\t\t\tcase \"--harness\":\n\t\t\t\to.Harness = v\n\t\t\tcase \"--project\":\n\t\t\t\to.Project = v\n\t\t\tcase \"--role\":\n\t\t\t\to.Role = v\n\t\t\tcase \"--session\":\n\t\t\t\to.Session = v\n\t\t\tcase \"--sort\":\n\t\t\t\tswitch strings.ToLower(v) {\n\t\t\t\tcase search.SortDate, \"newest\":\n\t\t\t\t\to.Sort = search.SortDate\n\t\t\t\tcase search.SortRelevance:\n\t\t\t\t\to.Sort = search.SortRelevance\n\t\t\t\tdefault:\n\t\t\t\t\treturn o, fmt.Errorf(\"--sort takes date or relevance, not %q\", v)\n\t\t\t\t}\n\t\t\tcase \"--limit\":\n\t\t\t\tn, err := strconv.Atoi(v)\n\t\t\t\tif err != nil || n < 1 || n > 100 {\n\t\t\t\t\treturn o, errors.New(\"--limit needs an integer from 1 to 100\")\n\t\t\t\t}\n\t\t\t\to.Limit = n\n\t\t\tdefault:\n\t\t\t\td, err := parseDur(v)\n\t\t\t\tif err != nil {\n\t\t\t\t\treturn o, err\n\t\t\t\t}\n\t\t\t\to.Since = d\n\t\t\t}\n\t\tdefault:\n\t\t\t// A query may legitimately start with a dash — `deja search\n\t\t\t// \"--retry budget\"` is a real search. A token one edit away from a\n\t\t\t// real flag is not: folding `--limti` into the query turned a\n\t\t\t// working search into \"you have no such memory\" (#755).\n\t\t\tif nearestSearchFlag(a) != \"\" {\n\t\t\t\treturn o, unknownFlag(\"search\", a, searchFlags)\n\t\t\t}\n\t\t\t// A flag deja takes elsewhere is not a typo and is nowhere near a\n\t\t\t// search flag by edit distance, so it went into the query and the\n\t\t\t// search that would have found everything reported nothing (#2249).\n\t\t\tif cmd := flagsOfOtherCommands[a]; cmd != \"\" {\n\t\t\t\treturn o, fmt.Errorf(\"%s is a flag of `deja %s`, not of search — put it after `--` to search for the text\", a, cmd)\n\t\t\t}\n\t\t\t// A --word after the query is a flag deja does not have. Taken as\n\t\t\t// a query term it turned `deja goroutines --bogus` into a search\n\t\t\t// for both words that found nothing, where the word alone had 40\n\t\t\t// hits. A query that starts with one (`--retry budget`), a phrase\n\t\t\t// with a dash inside, or a single dash is still a query.\n\t\t\tif len(q) > 0 && flagShaped(a) {\n\t\t\t\treturn o, fmt.Errorf(\"search: unknown flag %q — `deja search --help` lists its flags; put it after `--` to search for the text\", a)\n\t\t\t}\n\t\t\tq = append(q, a)\n\t\t}\n\t}\n\t// Match the NFC canonicalisation ingest applies to stored text, so a query\n\t// typed in either normalisation reaches the same records (#1098). Trim\n\t// surrounding space: a leading space left the exact-match tier hunting for\n\t// \" token\" and an exact-only term (an error code, a coined name) missed,\n\t// while a real word was rescued by its word-forms and hid the gap.\n\to.Query = nfcfold.Compose(strings.TrimSpace(strings.Join(q, \" \")))\n\tif o.Query == \"\" {\n\t\treturn o, errors.New(\"query required\")\n\t}\n\treturn o, nil\n}\n\n// flagShaped reports whether a token reads as a long flag: two dashes, then\n// letters, digits and inner dashes, nothing else.\nfunc flagShaped(a string) bool {\n\tif len(a) < 3 || !strings.HasPrefix(a, \"--\") {\n\t\treturn false\n\t}\n\tfor i, r := range a[2:] {\n\t\tswitch {\n\t\tcase r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z':\n\t\tcase r >= '0' && r <= '9', r == '-' && i > 0:\n\t\tdefault:\n\t\t\treturn false\n\t\t}\n\t}\n\treturn true\n}\n\n// flagsOfOtherCommands names the command each flag belongs to, for the tokens\n// that are real deja flags somewhere but not here. Only exact matches: a query\n// may legitimately start with a dash, and `--` still ends option parsing.\nvar flagsOfOtherCommands = map[string]string{\n\t\"--offset\":           \"show\",\n\t\"--span\":             \"restore\",\n\t\"--out\":              \"restore\",\n\t\"--force\":            \"restore\",\n\t\"--tag\":              \"remember\",\n\t\"--deep\":             \"doctor\",\n\t\"--offline\":          \"doctor\",\n\t\"--dry-run\":          \"forget\",\n\t\"--all-matches\":      \"forget\",\n\t\"--list\":             \"forget\",\n\t\"--unforget\":         \"forget\",\n\t\"--before\":           \"forget\",\n\t\"--to\":               \"handoff\",\n\t\"--exec\":             \"resume\",\n\t\"--write-back\":       \"resume\",\n\t\"--app\":              \"resume\",\n\t\"--plain\":            \"hook-prompt\",\n\t\"--crush\":            \"hook-tool\",\n\t\"--junie\":            \"hook-prompt\",\n\t\"--no-open\":          \"view\",\n\t\"--full\":             \"sync export\",\n\t\"--include-imported\": \"sync export\",\n\t\"--peer\":             \"sync export\",\n\t\"--pull\":             \"sync ssh\",\n\t\"--both\":             \"sync ssh\",\n\t\"--from\":             \"last\",\n\t\"--last\":             \"log\",\n\t\"--seed\":             \"bench\",\n}\n\n// searchFlags is every flag the bare search form accepts, for the typo check.\n// The flags each converted command takes, in the order its own parser lists\n// them. A list that drifts from its parser costs a wrong suggestion, not a\n// wrong refusal, and unknown_flag_lists_test.go holds them together.\nvar (\n\tindexFlags  = []string{\"--rebuild\", \"--quiet\"}\n\tshowFlags   = []string{\"--json\", \"--harness\", \"--offset\", \"--limit\"}\n\tforgetFlags = []string{\n\t\t\"--list\", \"--dry-run\", \"--all-matches\",\n\t\t\"--session\", \"--project\", \"--before\", \"--unforget\",\n\t}\n\tstatsFlags = []string{\n\t\t\"--json\", \"--html\", \"--redaction\", \"--impact\", \"--card\", \"--year\",\n\t\t\"--harness\", \"--project\", \"--since\", \"--role\",\n\t}\n\tdoctorFlags   = []string{\"--json\", \"--offline\", \"--deep\", \"--all\"}\n\tviewFlags     = []string{\"--out\", \"--no-open\"}\n\tlogFlags      = []string{\"--json\", \"--last\"}\n\trememberFlags = []string{\"--project\", \"--tag\"}\n\trestoreFlags  = []string{\"--force\", \"--span\", \"--out\", \"--all\"}\n\tpromoteFlags  = []string{\"--state\", \"--note\", \"--to\", \"--tag\"}\n\thandoffFlags  = []string{\"--to\", \"--exec\"}\n)\n\nvar searchFlags = []string{\n\t\"--json\", \"--re\", \"--all\", \"--no-embed\", \"--rebuild\",\n\t\"--harness\", \"--project\", \"--since\", \"--role\", \"--limit\", \"--session\", \"--sort\",\n}\n\n// nearestSearchFlag names the search flag a token was probably meant to be.\n// The rule it introduced is now every command's, in nearestKnownFlag; this is\n// the search-shaped name for it, kept because search is the one command where\n// the answer also decides whether a dashed token is a query term.\n//\n// --sort is left out of the near misses: --soft, --port and --short are one\n// edit from it and are things people search for (`git reset --soft`).\nfunc nearestSearchFlag(a string) string {\n\treturn nearestKnownFlag(a, searchNearMissFlags)\n}\n\nvar searchNearMissFlags = func() []string {\n\tvar out []string\n\tfor _, f := range searchFlags {\n\t\tif f != \"--sort\" {\n\t\t\tout = append(out, f)\n\t\t}\n\t}\n\treturn out\n}()\n\n// blameMode is what the caller asked for beyond the hits: the line answer on\n// its own (`--attribution`), as JSON, and whether to record it in\n// refs/notes/deja (#3723).\ntype blameMode struct {\n\tJSON        bool\n\tAttribution bool\n\tGitNote     bool\n\t// AllProjects answers from the whole machine. A path names a file in this\n\t// checkout, so by default sessions in other projects are left out.\n\tAllProjects bool\n}\n\nfunc parseBlame(args []string) (string, search.BlameOptions, blameMode, error) {\n\to := search.BlameOptions{}\n\tmode := blameMode{}\n\tvar path string\n\tfor i := 0; i < len(args); i++ {\n\t\ta := args[i]\n\t\tswitch a {\n\t\tcase \"--\":\n\t\t\t// The rest is the path, dash or not — the spelling search, fix and\n\t\t\t// how already take. A file really named `-report.md` was otherwise\n\t\t\t// unreachable, and the refusal reads to a caller like a file\n\t\t\t// nobody has ever touched.\n\t\t\tif i+1 < len(args) {\n\t\t\t\tif path != \"\" {\n\t\t\t\t\treturn \"\", o, mode, errors.New(\"blame accepts one path\")\n\t\t\t\t}\n\t\t\t\tpath = args[i+1]\n\t\t\t}\n\t\t\ti++\n\t\tcase \"--json\":\n\t\t\tmode.JSON = true\n\t\tcase \"--attribution\":\n\t\t\t// The line answer on its own, without the file's listing under it:\n\t\t\t// a caller asking about a line wants one answer, and --json turns\n\t\t\t// it into the object that answer needs (#3723).\n\t\t\tmode.Attribution = true\n\t\tcase \"--git-note\":\n\t\t\tmode.GitNote = true\n\t\tcase \"--all\":\n\t\t\to.All = true\n\t\tcase \"--all-projects\":\n\t\t\tmode.AllProjects = true\n\t\tcase \"--harness\", \"--project\", \"--since\":\n\t\t\tif i+1 >= len(args) {\n\t\t\t\treturn \"\", o, mode, fmt.Errorf(\"%s needs value\", a)\n\t\t\t}\n\t\t\ti++\n\t\t\tif strings.TrimSpace(args[i]) == \"\" { //nolint:gosec // bounds checked before i++\n\t\t\t\t// Empty is how \"no filter\" is spelled inside deja (#1612).\n\t\t\t\treturn \"\", o, mode, fmt.Errorf(\"%s needs value\", a)\n\t\t\t}\n\t\t\tswitch a {\n\t\t\tcase \"--harness\":\n\t\t\t\to.Harness = args[i] //nolint:gosec // bounds checked before i++\n\t\t\tcase \"--project\":\n\t\t\t\to.Project = args[i] //nolint:gosec // bounds checked before i++\n\t\t\tcase \"--since\":\n\t\t\t\td, err := parseDur(args[i]) //nolint:gosec // bounds checked before i++\n\t\t\t\tif err != nil {\n\t\t\t\t\treturn \"\", o, mode, err\n\t\t\t\t}\n\t\t\t\to.Since = d\n\t\t\t}\n\t\tdefault:\n\t\t\tif strings.HasPrefix(a, \"-\") {\n\t\t\t\tif flagName(a) == \"--limit\" {\n\t\t\t\t\t// blame widens with --all rather than a count (#3405).\n\t\t\t\t\treturn \"\", o, mode, fmt.Errorf(\"blame: unknown flag %q — it takes --all to show every session\", a)\n\t\t\t\t}\n\t\t\t\treturn \"\", o, mode, fmt.Errorf(\"blame: unknown flag %q; a path or question that starts with a dash goes after `--`\", a)\n\t\t\t}\n\t\t\tif path != \"\" {\n\t\t\t\treturn \"\", o, mode, errors.New(\"blame accepts one path\")\n\t\t\t}\n\t\t\tpath = a\n\t\t}\n\t}\n\tif path == \"\" {\n\t\treturn \"\", o, mode, errors.New(\"blame needs a path — `deja blame <file>` or `deja blame <file>:<line>`\")\n\t}\n\treturn path, o, mode, nil\n}\n\nfunc runBlame(dir string, args []string) error {\n\tpath, o, mode, err := parseBlame(args)\n\tif err != nil {\n\t\treturn err\n\t}\n\tjsonOutput := mode.JSON\n\t// A typo'd harness must name the mistake, not read as \"nobody touched this\n\t// file under harness X\" — the same reason search and the MCP blame validate\n\t// it (#1113). blame has no --role to check.\n\tif herr := checkHarness(&o.Harness); herr != nil {\n\t\treturn herr\n\t}\n\ttarget, err := search.ResolveBlamePath(path)\n\tif err != nil {\n\t\treturn err\n\t}\n\t// Both of the line-level flags answer about a line and have nothing to say\n\t// about a file. Refusing here, by name, beats answering about the whole\n\t// file and leaving the caller to notice their `:42` went nowhere (#3726).\n\tif (mode.Attribution || mode.GitNote) && target.Line <= 0 {\n\t\tflag := \"--attribution\"\n\t\tif mode.GitNote {\n\t\t\tflag = \"--git-note\"\n\t\t}\n\t\tif target.LineNote != \"\" {\n\t\t\treturn fmt.Errorf(\"blame %s: %s\", flag, target.LineNote)\n\t\t}\n\t\treturn fmt.Errorf(\"blame %s answers about one line — `deja blame %s:42 %s`\", flag, path, flag)\n\t}\n\t// Before the answer, because the answer is about the file and the reader\n\t// asked about a line: said afterwards it reads as a footnote to a result\n\t// they think is line-level (#3738).\n\tif target.LineNote != \"\" && !jsonOutput {\n\t\tfmt.Fprintf(os.Stderr, \"deja: %s — answering for the whole file\\n\", target.LineNote)\n\t}\n\t// A path names a file in this checkout. Other repos have their own\n\t// internal/pool/pool.go, and their sessions are about that file, not this\n\t// one; they were listed in among this project's.\n\tscope := blameScope(howCwd(), target, o.Project, mode.AllProjects)\n\twantAll := o.All\n\tif len(scope) > 0 {\n\t\to.All = true\n\t}\n\thits, hidden, total, err := findBlameHits(dir, target, o, policy.ActivationSearch, os.Stderr)\n\tif err != nil {\n\t\treturn fmt.Errorf(\"blame search: %w\", err)\n\t}\n\telsewhere, onlyElsewhere := 0, false\n\tif len(scope) > 0 {\n\t\tvar in []search.BlameHit\n\t\tfor _, h := range hits {\n\t\t\tif howProjectMatches(h.Session.Project, scope) {\n\t\t\t\tin = append(in, h)\n\t\t\t}\n\t\t}\n\t\telsewhere = len(hits) - len(in)\n\t\tif len(in) > 0 {\n\t\t\thits = in\n\t\t} else {\n\t\t\tonlyElsewhere = len(hits) > 0\n\t\t}\n\t\ttotal = len(hits)\n\t\to.All = wantAll\n\t\thits = search.CapBlame(hits, o)\n\t}\n\tif onlyElsewhere && !jsonOutput && !mode.Attribution && !mode.GitNote {\n\t\tfmt.Fprintf(os.Stderr, \"deja: no session in %s mentions %s — these are from other projects\\n\", howScopeName(scope), target.Base)\n\t}\n\t// The line answer alone, in either rendering, and nothing about the file\n\t// under it: that is what was asked for.\n\tif mode.Attribution || mode.GitNote {\n\t\treturn blameLineOnly(os.Stdout, dir, target, hits, mode)\n\t}\n\t// A line was asked about, so answer about the line first: git says which\n\t// commit wrote it, and the store says which session wrote the text that\n\t// commit replaced (#1181). Before the branches below, because a file no\n\t// session mentions still has a commit behind the line — and \"no session\n\t// wrote this\" is the answer, not silence.\n\tif target.Line > 0 && !jsonOutput {\n\t\tlineBlame(os.Stdout, dir, target, hits)\n\t}\n\tif jsonOutput {\n\t\t// The session object search returns, source and all: a consumer\n\t\t// telling local sessions from imported ones reads it on both.\n\t\tfor i := range hits {\n\t\t\thits[i].Session.SetSource(os.Getenv(\"DEJA_SOURCE_INSTANCE\"))\n\t\t}\n\t\tsearch.PrintBlame(os.Stdout, hits, true)\n\t\treturn nil\n\t}\n\tif len(hits) == 0 {\n\t\t// The file was edited — a rule withheld the session that touched it.\n\t\t// \"no sessions mention it\" reads as looked-and-absent, the misread\n\t\t// search and last already avoid by naming the rule (#686, #680).\n\t\tif note := policyHiddenNote(policy.ActivationSearch, hidden); note != \"\" {\n\t\t\tfmt.Fprint(os.Stderr, note)\n\t\t\treturn nil\n\t\t}\n\t\t// And the other rule that empties this answer, which said nothing here\n\t\t// while the listing and search both named it (#2632). Before the count\n\t\t// below, for the same reason it goes before \"try fewer words\": a\n\t\t// denominator that includes the ignored sessions reads as a store that\n\t\t// was searched and came back empty.\n\t\tif note := ignoredHiddenNoteFor(\"answer\", ignoredTouching(dir, target)); note != \"\" {\n\t\t\tfmt.Fprint(os.Stderr, note)\n\t\t\treturn nil\n\t\t}\n\t\t// \"run deja index\" is advice for an empty store. With sessions in the\n\t\t// index it is advice for a state the tool is not in — indexing changes\n\t\t// nothing and doctor reports the stores as found — and it sends the\n\t\t// reader to fix an index that is fine (#637, same shape).\n\t\tif n, err := index.SessionCount(dir); err == nil && n > 0 {\n\t\t\tfmt.Fprintf(os.Stderr, \"deja: no sessions mention %s — searched %d indexed session%s\\n\", target.Base, n, pluralS(n))\n\t\t} else {\n\t\t\tfmt.Fprintln(os.Stderr, emptyIndexHint(\"no sessions mention \"+target.Base))\n\t\t}\n\t\treturn nil\n\t}\n\tsearch.PrintBlameWidth(os.Stdout, hits, printableWidth(os.Stdout))\n\t// The name the reader has is the one in their editor, and a rename drops\n\t// everything said under the old one out of this answer (#1627).\n\tif note := earlierNameNote(dir, path, target); note != \"\" {\n\t\tfmt.Fprint(os.Stderr, note)\n\t}\n\t// blame answers \"who touched this file\". Ten blocks and nothing else reads\n\t// as all of them, the misread search already avoids with the same sentence\n\t// (#2299). --json keeps its bare array: a machine consumer reading a total\n\t// would need a different shape, and that is a break, not a note.\n\tif total > len(hits) {\n\t\tfmt.Fprintf(os.Stderr, \"deja: showing %d of %d — add --all to see the rest\\n\", len(hits), total)\n\t}\n\tif elsewhere > 0 && !onlyElsewhere {\n\t\tfmt.Fprintln(os.Stderr, fitLine(os.Stderr, fmt.Sprintf(\"deja: %d session%s in other projects mention their own %s — --all-projects lists them\", elsewhere, pluralS(elsewhere), target.Base)))\n\t}\n\treturn nil\n}\n\n// blameScope is the project a blame answers from: the working directory's,\n// when the file lies inside it and nothing else was asked for. A file outside\n// the working directory, --project and --all-projects all leave it to the\n// rest of the options.\nfunc blameScope(cwd string, target search.BlameTarget, project string, allProjects bool) []string {\n\tif allProjects || strings.TrimSpace(project) != \"\" || cwd == \"\" {\n\t\treturn nil\n\t}\n\trel, err := filepath.Rel(cwd, target.FullPath)\n\tif err != nil || rel == \"..\" || strings.HasPrefix(rel, \"..\"+string(filepath.Separator)) {\n\t\treturn nil\n\t}\n\treturn howScope(cwd, \"\", false)\n}\n\nfunc findBlameHits(dir string, target search.BlameTarget, o search.BlameOptions, activation string, progress io.Writer) ([]search.BlameHit, int, int, error) { //nolint:unparam // blame tests in blame_*_test.go pass it\n\thits, hidden, total, _, err := blameHits(dir, target, o, activation, progress, false)\n\treturn hits, hidden, total, err\n}\n\n// findBlameHitsStale is findBlameHits for a caller that must not wait: it\n// serves the snapshot on disk while a rebuild runs, the way recall does, and\n// hands the rebuild to the detached warmup. blame is the tool an agent calls\n// before editing a file, so declining for the length of a refresh means the\n// edit happens without the history (#1784). The CLI keeps the blocking path —\n// someone typed it and is watching the progress (#1306).\nfunc findBlameHitsStale(dir string, target search.BlameTarget, o search.BlameOptions, activation string, progress io.Writer) ([]search.BlameHit, int, int, bool, error) {\n\treturn blameHits(dir, target, o, activation, progress, true)\n}\n\nfunc blameHits(dir string, target search.BlameTarget, o search.BlameOptions, activation string, progress io.Writer, stale bool) ([]search.BlameHit, int, int, bool, error) {\n\tquery := search.Options{Query: target.Stem, Harness: o.Harness, Project: o.Project, Since: o.Since, All: true}\n\trefreshing := false\n\tif stale {\n\t\tvar err error\n\t\tif refreshing, err = index.EnsureForSearchStale(dir, query, progress); err != nil {\n\t\t\treturn nil, 0, 0, false, err\n\t\t} else if refreshing && !warmupRunning(dir) {\n\t\t\trequestWarmup(dir)\n\t\t}\n\t} else if err := index.EnsureForSearch(dir, query, false, progress); err != nil {\n\t\treturn nil, 0, 0, false, err\n\t}\n\tresult, err := index.SearchWithRecoveryDetailed(dir, query, progress)\n\tif err != nil {\n\t\treturn nil, 0, 0, false, err\n\t}\n\tall := search.Blame(withFileTouchers(dir, result.Sessions, target), target, o)\n\tvisible := policyFilterBlame(activation, all)\n\t// Cap after the trust filter, not before: cutting first meant a withheld\n\t// session ate one of the ten slots, so a reader could get eight hits with\n\t// forty sessions still waiting behind --all.\n\thits := search.CapBlame(visible, o)\n\tattachBlameLifecycles(hits)\n\treturn hits, len(all) - len(visible), len(visible), refreshing, nil\n}\n\n// blameToucherCap bounds how many extra sessions a blame reads from the\n// manifest. Measured on 500 sessions all touching one file: 0.08s uncapped\n// against 0.02s capped, with the same ten at the top.\nconst blameToucherCap = 50\n\n// ignoredTouching counts the sessions that touched this file and are covered by\n// the ignore rule. Not IgnoredWithAllTerms, which the other surfaces use: that\n// reads the text postings, and a file path reaches the index as a `files`\n// record, which is served by role and never ranked — so the count for a blame\n// has to come from the same Touched lists blame itself reads (#2632).\nfunc ignoredTouching(dir string, target search.BlameTarget) int {\n\tmetas, err := index.AllMeta(dir)\n\tif err != nil {\n\t\treturn 0\n\t}\n\tpol := policy.Load()\n\tbase := strings.ToLower(filepath.Base(target.FullPath))\n\tn := 0\n\tfor _, meta := range metas {\n\t\tif !pol.Ignored(meta.Path, meta.Project) {\n\t\t\tcontinue\n\t\t}\n\t\tfor _, p := range meta.Touched {\n\t\t\tif strings.ToLower(filepath.Base(filepath.FromSlash(p))) == base {\n\t\t\t\tn++\n\t\t\t\tbreak\n\t\t\t}\n\t\t}\n\t}\n\treturn n\n}\n\n// withFileTouchers adds the sessions that edited or opened the file but never\n// said its name.\n//\n// blame picks its candidates with an ordinary search for the file's stem, and\n// the paths a tool call recorded do not answer one: the newer session that\n// actually changed pool.go was invisible while an older one that only\n// mentioned it in passing was the answer (#688). The manifest already knows\n// which files each session touched, so this costs one metadata read.\nfunc withFileTouchers(dir string, ss []model.Session, target search.BlameTarget) []model.Session {\n\tmetas, err := index.AllMeta(dir)\n\tif err != nil {\n\t\treturn ss\n\t}\n\t// Where each session sits, not merely whether it is here: search returns\n\t// sessions with only their matching messages attached, so one that matched\n\t// on speech arrives with its `files` record stripped. Skipping it as\n\t// \"already present\" is how mentioning the subject removed a session from\n\t// its own file's blame (#723) — it has to be replaced by the full record.\n\tat := make(map[string]int, len(ss))\n\tfor i, s := range ss {\n\t\tat[s.Harness+\":\"+s.ID] = i\n\t}\n\tbase := strings.ToLower(filepath.Base(target.FullPath))\n\t// Newest first, so the cap below keeps the sessions a \"who last worked on\n\t// this\" question is actually about.\n\t// Identity breaks ties, or which sessions survive the cap depends on Go's\n\t// map order and two runs disagree — the same failure as #668.\n\tsort.Slice(metas, func(i, j int) bool { return newestFirst(metas[i], metas[j]) })\n\t// Pick the identities first and read them in one pass: per-identity reads\n\t// stream the whole record log each time, so the cap alone did not bound\n\t// the cost — 50 sessions meant 50 scans (#1069).\n\tvar want []index.Identity\n\tfor _, meta := range metas {\n\t\t// A file like main.go is touched by everything, and each addition is a\n\t\t// record read. Ten hits are printed; this is far more than enough to\n\t\t// rank them.\n\t\tif len(want) >= blameToucherCap {\n\t\t\tbreak\n\t\t}\n\t\tfor _, p := range meta.Touched {\n\t\t\tif strings.ToLower(filepath.Base(filepath.FromSlash(p))) != base {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\twant = append(want, index.Identity{Harness: meta.Harness, ID: meta.ID})\n\t\t\tbreak\n\t\t}\n\t}\n\tfull, err := index.FindManyByIdentity(dir, want)\n\tif err != nil {\n\t\treturn ss\n\t}\n\tfor _, s := range full {\n\t\t// The manifest is keyed by identity, so each session reaches this once\n\t\t// — there is no second visit to record a position for.\n\t\tif i, present := at[s.Harness+\":\"+s.ID]; present {\n\t\t\tss[i] = s\n\t\t} else {\n\t\t\tss = append(ss, s)\n\t\t}\n\t}\n\treturn ss\n}\n\n// parseDur is the window a reader asked to look back over, so it has to be one:\n// zero or less used to parse and then disappear, because every caller cuts on\n// `Since > 0` — `--since -1d` searched the whole store and nothing in the answer\n// said the filter had been dropped (#1610). parseDurAny is the raw form, for\n// `forget --before`, which has its own word for the same mistake.\nfunc parseDur(s string) (time.Duration, error) {\n\td, err := parseDurAny(s)\n\tif err != nil {\n\t\treturn 0, err\n\t}\n\tif d <= 0 {\n\t\treturn 0, fmt.Errorf(\"%q is not a window — --since counts back from now, so it needs a positive duration like 30d\", s)\n\t}\n\treturn d, nil\n}\n\n// maxDurationDays is how many whole days fit in a time.Duration: past it the\n// multiplication wraps, and `--since 365000d` — the way to say \"all of it\" —\n// came out negative and dropped the filter it was asked for.\nconst maxDurationDays = int(math.MaxInt64 / (24 * int64(time.Hour)))\n\nfunc parseDurAny(s string) (time.Duration, error) {\n\tif before, ok := strings.CutSuffix(s, \"d\"); ok {\n\t\tn, err := strconv.Atoi(before)\n\t\tif err != nil {\n\t\t\treturn 0, durationError(s)\n\t\t}\n\t\tif n > maxDurationDays {\n\t\t\treturn time.Duration(math.MaxInt64), nil\n\t\t}\n\t\tif n < -maxDurationDays {\n\t\t\treturn time.Duration(math.MinInt64), nil\n\t\t}\n\t\treturn time.Duration(n) * 24 * time.Hour, nil\n\t}\n\td, err := time.ParseDuration(s)\n\tif err != nil {\n\t\t// time.ParseDuration's own message names Go's syntax, not deja's, and\n\t\t// it does not mention days — which is the unit people reach for here.\n\t\treturn 0, durationError(s)\n\t}\n\treturn d, nil\n}\n\nfunc durationError(s string) error {\n\treturn fmt.Errorf(\"%q is not a duration deja understands — try 30d, 12h, or 90m\", s)\n}\n\n// presentFiles is one path if it exists, nothing otherwise: a store deja names\n// but does not have should weigh nothing rather than the directory around it.\nfunc presentFiles(paths ...string) []string {\n\tvar out []string\n\tfor _, p := range paths {\n\t\tif p == \"\" {\n\t\t\tcontinue\n\t\t}\n\t\tif fi, err := os.Stat(p); err == nil && !fi.IsDir() {\n\t\t\tout = append(out, p)\n\t\t}\n\t}\n\treturn out\n}\n\nfunc cursorReadFiles() []string {\n\treturn append(sources.CursorTranscripts(), sources.CursorDBs()...)\n}\n\n// grokReadFiles is both of Grok's stores: the session files Grok Build writes,\n// and the SQLite store the maintained CLI writes instead. The row listed only\n// the first, so the size column read 0 B on a machine whose whole history is in\n// the database (#3225).\nfunc grokReadFiles() []string {\n\tfiles := sources.GrokSessionFiles()\n\tif db := sources.GrokDB(); db != \"\" {\n\t\tfiles = append(files, db)\n\t}\n\treturn files\n}\n\n// filesSize sums what the parser would open, counting each path once: cursor\n// and hermes list a file under more than one discovery rule.\nfunc filesSize(paths []string) int64 {\n\tseen := map[string]bool{}\n\tvar total int64\n\tfor _, p := range paths {\n\t\tif p == \"\" || seen[p] {\n\t\t\tcontinue\n\t\t}\n\t\tseen[p] = true\n\t\tif fi, err := os.Stat(p); err == nil && !fi.IsDir() {\n\t\t\ttotal += fi.Size()\n\t\t}\n\t}\n\treturn total\n}\n\n// commonDir is the deepest directory holding every path, which is the answer to\n// \"where is my history\" — the configured root can be a parent of it, or, when a\n// harness keeps its store somewhere else entirely, not contain it at all.\nfunc commonDir(paths []string) string {\n\tdir := \"\"\n\tfor _, p := range paths {\n\t\tif p == \"\" {\n\t\t\tcontinue\n\t\t}\n\t\td := filepath.Dir(p)\n\t\tif dir == \"\" {\n\t\t\tdir = d\n\t\t\tcontinue\n\t\t}\n\t\tfor dir != d && !strings.HasPrefix(d+string(filepath.Separator), dir+string(filepath.Separator)) {\n\t\t\tparent := filepath.Dir(dir)\n\t\t\tif parent == dir {\n\t\t\t\treturn dir\n\t\t\t}\n\t\t\tdir = parent\n\t\t}\n\t}\n\treturn dir\n}\n\n// projectExcludePatterns counts project rules from the file and environment.\n// Count them directly: excluded stores can also come from the environment,\n// and duplicate harness rules do not each add a store (#5401).\nfunc projectExcludePatterns() int {\n\tn := 0\n\tfor _, pattern := range sources.ExclusionPatterns() {\n\t\tif !strings.HasPrefix(pattern, \"harness:\") {\n\t\t\tn++\n\t\t}\n\t}\n\treturn n\n}\n\n// An environment exclusion must not be attributed to the exclude file.\n// Prefer the environment when both settings exclude the same store.\nfunc harnessExclusionSource(name string) string {\n\tfor excluded := range strings.SplitSeq(os.Getenv(\"DEJA_EXCLUDE_HARNESSES\"), \",\") {\n\t\tif strings.EqualFold(strings.TrimSpace(excluded), name) {\n\t\t\treturn \"DEJA_EXCLUDE_HARNESSES\"\n\t\t}\n\t}\n\treturn sources.ExcludePath()\n}\n\n// harnessExclusionSources names where a set of store exclusions come from:\n// the exclude file, DEJA_EXCLUDE_HARNESSES, or both.\nfunc harnessExclusionSources(names map[string]bool) string {\n\tenv, file := false, false\n\tfor name := range names {\n\t\tif harnessExclusionSource(name) == \"DEJA_EXCLUDE_HARNESSES\" {\n\t\t\tenv = true\n\t\t} else {\n\t\t\tfile = true\n\t\t}\n\t}\n\tswitch {\n\tcase env && file:\n\t\treturn reportPath(sources.ExcludePath()) + \" and DEJA_EXCLUDE_HARNESSES\"\n\tcase env:\n\t\treturn \"DEJA_EXCLUDE_HARNESSES\"\n\t}\n\treturn reportPath(sources.ExcludePath())\n}\n\nfunc harnessExclusionReason(name string) string {\n\tsetting := harnessExclusionSource(name)\n\tif setting == \"DEJA_EXCLUDE_HARNESSES\" {\n\t\treturn \"excluded — \" + setting\n\t}\n\treturn fmt.Sprintf(\"excluded — `harness:%s` is in %s\", name, setting)\n}\n\nfunc printSources(dir string) {\n\t// A terminal gets a table; a pipe gets the tab-separated rows scripts\n\t// read, exactly as before.\n\tif briefWanted(os.Stdout) {\n\t\tvar buf bytes.Buffer\n\t\tprintSourcesTo(&buf, dir)\n\t\tfmt.Print(sourcesScreen(buf.String(), statColorOK(os.Stdout), briefWidth()))\n\t\treturn\n\t}\n\tprintSourcesTo(os.Stdout, dir)\n}\n\n// rootsOrDefault names the roots deja found, or the default one when none\n// exists yet, so a row never has an empty location: someone who installs the\n// harness later can see where its history should appear (#5638).\nfunc rootsOrDefault(roots []string, def string) string {\n\tif len(roots) == 0 {\n\t\treturn def\n\t}\n\treturn strings.Join(roots, string(os.PathListSeparator))\n}\n\nfunc printSourcesTo(w io.Writer, dir string) {\n\tredactions := map[string]int{}\n\tif red, err := index.Redactions(dir); err == nil {\n\t\tredactions = red.Files\n\t}\n\t// Transcripts a store holds that the index has never read. doctor has said\n\t// so since #3747, but `deja sources` is the command people run first, and\n\t// its session count reads as \"nothing written yet\" rather than \"files never\n\t// opened\" — which is exactly how ten unread transcripts, five of them eight\n\t// weeks old, went unnoticed on a real store (#3752). Nil before the first\n\t// index, and then there is nothing to say.\n\tneverRead := index.HarnessUnreadCounts(dir)\n\tunreadNote := func(name string) string {\n\t\tif u := neverRead[name]; u > 0 {\n\t\t\treturn \"\\t(\" + doctorCount(u, \"transcript\") + \" never read — `deja index`)\"\n\t\t}\n\t\treturn \"\"\n\t}\n\tantigravityRoots := sources.AntigravityRoots()\n\tantigravityLocation := strings.Join(antigravityRoots, string(os.PathListSeparator))\n\tif antigravityLocation == \"\" {\n\t\tantigravityLocation = filepath.Join(sources.Home(), \".gemini\", \"antigravity*\")\n\t}\n\t// files names what the parser opens. The screen answers \"where is my history\n\t// and how much of it is there\", and roots are where deja looks rather than\n\t// what it reads: a codex root reported 108 MB of plugins, caches and sqlite\n\t// WALs around 1.3 MB of transcripts, and hermes named a directory holding\n\t// one crash log while the store it reads sat elsewhere (#654).\n\titems := []struct {\n\t\tname, location string\n\t\troots          []string\n\t\tfiles          func() []string\n\t\tload           func() []model.Session\n\t}{\n\t\t{\"claude\", strings.Join(sources.ClaudeRoots(), string(os.PathListSeparator)), sources.ClaudeRoots(), sources.ClaudeFiles, sources.LoadClaude},\n\t\t{\"codex\", strings.Join(sources.CodexRoots(), string(os.PathListSeparator)), sources.CodexRoots(), sources.CodexFiles, sources.LoadCodex},\n\t\t{\"trae\", sources.TraeRoot(), []string{sources.TraeRoot()}, sources.TraeFiles, sources.LoadTrae},\n\t\t{\"gemini\", sources.GeminiRoot(), []string{filepath.Join(sources.GeminiRoot(), \"tmp\")}, sources.GeminiChatFiles, sources.LoadGemini},\n\t\t{\"cursor\", strings.Join([]string{sources.CursorUserRoot(), sources.CursorCLIRoot()}, string(os.PathListSeparator)), []string{sources.CursorUserRoot(), sources.CursorCLIRoot()}, cursorReadFiles, sources.LoadCursor},\n\t\t{\"antigravity\", antigravityLocation, antigravityRoots, sources.AntigravityTranscripts, sources.LoadAntigravity},\n\t\t// Both halves, the way the registry's grok entry loads them: the\n\t\t// maintained CLI writes one SQLite store beside the config and no\n\t\t// session files at all, so a machine on that build read as zero\n\t\t// sessions here while doctor and search both found them (#3225).\n\t\t{\"grok\", sources.GrokRoot(), []string{sources.GrokRoot()}, grokReadFiles, func() []model.Session {\n\t\t\treturn append(sources.LoadGrok(), sources.LoadGrokDB()...)\n\t\t}},\n\t\t{\"qwen\", filepath.Join(sources.QwenRoot(), \"projects\"), []string{filepath.Join(sources.QwenRoot(), \"projects\")}, sources.QwenSessionFiles, sources.LoadQwen},\n\t\t{\"codebuddy\", strings.Join(sources.CodeBuddyRoots(), string(os.PathListSeparator)), sources.CodeBuddyRoots(), sources.CodeBuddySessionFiles, sources.LoadCodeBuddy},\n\t\t{\"kimi\", filepath.Join(sources.KimiRoot(), \"sessions\"), []string{filepath.Join(sources.KimiRoot(), \"sessions\")}, sources.KimiSessionFiles, sources.LoadKimi},\n\t\t{\"goose\", filepath.Join(sources.GooseRoot(), \"sessions\"), sources.GooseSessionsDirs(), sources.GooseSessionFiles, sources.LoadGoose},\n\t\t{\"hermes\", sources.HermesProfilesRoot(), []string{sources.HermesProfilesRoot()}, sources.HermesSessionFiles, sources.LoadHermes},\n\t\t{\"copilot\", sources.CopilotRoot(), []string{sources.CopilotRoot()}, sources.CopilotSessionFiles, sources.LoadCopilot},\n\t\t{\"copilot-chat\", rootsOrDefault(sources.CopilotChatRoots(), sources.CopilotChatDefaultRoot()), sources.CopilotChatRoots(), sources.CopilotChatSessionFiles, sources.LoadCopilotChat},\n\t\t{\"cline\", sources.ClineSessionsDir(), append([]string{sources.ClineSessionsDir()}, sources.ClineLegacyRoots()...), sources.ClineSessionFiles, sources.LoadCline},\n\t\t{\"roo\", rootsOrDefault(sources.RooRoots(), sources.RooDefaultRoot()), sources.RooRoots(), sources.RooTaskFiles, sources.LoadRoo},\n\t\t{\"kilocode\", rootsOrDefault(sources.KiloRoots(), sources.KiloDefaultRoot()), sources.KiloRoots(), sources.KiloSessionFiles, sources.LoadKilo},\n\t\t{\"cherrystudio\", rootsOrDefault(sources.CherryStudioAllRoots(), sources.CherryStudioDefaultRoot()), sources.CherryStudioAllRoots(), sources.CherryStudioSessionFiles, sources.LoadCherryStudio},\n\t\t{\"kiro\", sources.KiroRoot(), []string{sources.KiroRoot()}, sources.KiroSessionFiles, sources.LoadKiro},\n\t\t{\"senpi\", sources.SenpiRoot(), []string{sources.SenpiRoot()}, sources.SenpiSessionFiles, sources.LoadSenpi},\n\t\t{\"kimchi\", sources.KimchiRoot(), []string{sources.KimchiRoot()}, sources.KimchiSessionFiles, sources.LoadKimchi},\n\t\t{\"commandcode\", sources.CommandCodeRoot(), []string{sources.CommandCodeRoot()}, sources.CommandCodeSessionFiles, sources.LoadCommandCode},\n\t\t{\"zcode\", sources.ZCodeRoot(), []string{sources.ZCodeRoot()}, sources.ZCodeSessionFiles, sources.LoadZCode},\n\t\t{\"gjc\", sources.GjcRoot(), []string{sources.GjcRoot()}, sources.GjcSessionFiles, sources.LoadGjc},\n\t\t{\"continue\", filepath.Join(sources.ContinueRoot(), \"sessions\"), []string{filepath.Join(sources.ContinueRoot(), \"sessions\")}, sources.ContinueSessionFiles, sources.LoadContinue},\n\t\t{\"pi\", sources.PiRoot(), []string{sources.PiRoot()}, sources.PiSessionFiles, sources.LoadPi},\n\t\t{\"omp\", sources.OmpRoot(), []string{sources.OmpRoot()}, sources.OmpSessionFiles, sources.LoadOmp},\n\t\t{\"prime\", sources.PrimeRoot(), sources.PrimeRoots(), sources.PrimeSessionFiles, sources.LoadPrime},\n\t\t{\"amp\", sources.AmpRoot(), []string{sources.AmpRoot()}, sources.AmpThreadFiles, sources.LoadAmp},\n\t\t{\"openclaw\", sources.OpenClawRoot(), []string{sources.OpenClawRoot()}, sources.OpenClawStoreFiles, sources.LoadOpenClaw},\n\t\t{\"codewhale\", sources.CodeWhaleRoot(), sources.CodeWhaleRoots(), sources.CodeWhaleSessionFiles, sources.LoadCodeWhale},\n\t\t{\"junie\", sources.JunieRoot(), []string{sources.JunieRoot()}, sources.JunieSessionFiles, sources.LoadJunie},\n\t\t{\"jetbrains\", sources.JetBrainsRoot(), []string{sources.JetBrainsRoot()}, sources.JetBrainsSessionFiles, sources.LoadJetBrains},\n\t\t{\"windsurf\", sources.WindsurfRoot(), []string{sources.WindsurfRoot()}, sources.WindsurfSessionFiles, sources.LoadWindsurf},\n\t\t{\"reasonix\", sources.ReasonixRoot(), sources.ReasonixRoots(), sources.ReasonixSessionFiles, sources.LoadReasonix},\n\t\t{\"muse\", sources.MuseRoot(), sources.MuseRoots(), sources.MuseSessionFiles, sources.LoadMuse},\n\t\t{\"mcode\", sources.McodeRoot(), []string{sources.McodeRoot()}, sources.McodeSessionFiles, sources.LoadMcode},\n\t\t{\"deepseek\", sources.DeepSeekRoot(), []string{sources.DeepSeekRoot()}, sources.DeepSeekSessionFiles, sources.LoadDeepSeek},\n\t\t{\"zed\", sources.ZedDB(), []string{sources.ZedDB()}, func() []string { return presentFiles(sources.ZedDB()) }, sources.LoadZed},\n\t\t{\"devin\", filepath.Dir(sources.DevinSessionsDB()), []string{filepath.Dir(sources.DevinSessionsDB())}, sources.DevinFiles, sources.LoadDevin},\n\t\t// The location is the registry, not a store: Crush keeps one store per\n\t\t// project, under the project, and the registry is the only thing that\n\t\t// says where they are.\n\t\t{\"crush\", sources.CrushDataHome(), sources.CrushDBs(), sources.CrushDBs, sources.LoadCrush},\n\t\t{\"deja\", sources.NotesFile(), []string{sources.NotesFile()}, func() []string { return presentFiles(sources.NotesFile()) }, sources.LoadNotes},\n\t}\n\tskipStore := sources.ExcludedHarnesses()\n\tfor _, it := range items {\n\t\t// A store DEJA_STORES leaves out has no row, as in doctor: it is not\n\t\t// read, so it has no count to report.\n\t\tif sources.StoreSilenced(it.name) {\n\t\t\tcontinue\n\t\t}\n\t\t// A store the reader excluded is named and not read. Walking it here\n\t\t// reported three sessions and eighteen messages for a harness deja had\n\t\t// just been told never to open, which is the opposite of what this\n\t\t// screen is for (#3499).\n\t\tif skipStore[it.name] {\n\t\t\tfmt.Fprintf(w, \"%s\\t%s\\t%s\\n\", it.name, it.location, harnessExclusionReason(it.name))\n\t\t\tcontinue\n\t\t}\n\t\tredacted := 0\n\t\tfor _, root := range it.roots {\n\t\t\tredacted += redactionsUnder(redactions, root)\n\t\t}\n\t\t// Only paths that are files on this machine: a discovery rule can name\n\t\t// something that is not one — hermes returns a token for a Postgres\n\t\t// store — and neither a size nor a directory can be read off that.\n\t\tread := presentFiles(it.files()...)\n\t\tsize := filesSize(read)\n\t\tlocation := it.location\n\t\tif where := commonDir(read); where != \"\" {\n\t\t\tlocation = where\n\t\t}\n\t\traw := it.load()\n\t\tss := sources.FilterSessions(raw)\n\t\texcluded := len(raw) - len(ss)\n\t\tmsg := sources.CountMessages(ss)\n\t\tnote := \"\"\n\t\t// `deja sources` is where the empty-machine advice sends people, and a\n\t\t// store deja is not allowed to read looked exactly like one nobody has\n\t\t// used: `sessions=0 messages=0 size=0 B` (#1000).\n\t\tif denied, whole := firstDeniedDir(it.roots); denied != \"\" {\n\t\t\tnote = \"\\t(cannot be read — permission denied on \" + denied + \")\"\n\t\t} else if !whole {\n\t\t\tnote = \"\\t(permissions not fully checked — too many directories to walk)\"\n\t\t}\n\t\tif it.name == \"cursor\" && len(sources.CursorDBs()) > 0 && !sources.SQLite3Available() {\n\t\t\tnote = \"\\t(\" + sources.SQLite3Problem() + \" — Cursor IDE sessions unavailable)\"\n\t\t}\n\t\t// Zed needs zstd as well as sqlite3: sqlite3 alone opens the store and\n\t\t// reads nothing out of it, since every thread body is a compressed\n\t\t// frame. SkipReason already words which of the two is missing.\n\t\tif it.name == \"zed\" {\n\t\t\tif reason := sources.SkipReason(\"zed\"); reason != \"\" {\n\t\t\t\tnote = \"\\t(\" + reason + \" — Zed threads unavailable)\"\n\t\t\t}\n\t\t}\n\t\tif it.name == \"windsurf\" {\n\t\t\tif reason := sources.SkipReason(\"windsurf\"); reason != \"\" {\n\t\t\t\tnote = \"\\t(\" + reason + \" — those conversations unavailable)\"\n\t\t\t}\n\t\t}\n\t\tif n := projectExcludePatterns(); n > 0 {\n\t\t\tnote += fmt.Sprintf(\"\\texcluded-patterns=%d\", n)\n\t\t}\n\t\tif excluded > 0 {\n\t\t\tnote += fmt.Sprintf(\"\\texcluded-sessions=%d\", excluded)\n\t\t}\n\t\tnote += unreadNote(it.name)\n\t\tfmt.Fprintf(w, \"%s\\t%s\\tsessions=%d messages=%d size=%s redacted=%d%s\\n\", it.name, location, sources.CountSessions(ss), msg, humanBytes(size), redacted, note)\n\t}\n\t// The two rows below are written by hand rather than driven by the table\n\t// above, and the exclusion has to reach them too: the store #3499 named is\n\t// one of them, and an excluded opencode kept being opened and kept printing\n\t// the sqlite3 error the exclusion exists to silence.\n\texcludedRow := func(name, location string) bool {\n\t\tif sources.StoreSilenced(name) {\n\t\t\treturn true\n\t\t}\n\t\tif !skipStore[name] {\n\t\t\treturn false\n\t\t}\n\t\tfmt.Fprintf(w, \"%s\\t%s\\t%s\\n\", name, location, harnessExclusionReason(name))\n\t\treturn true\n\t}\n\taiderFiles := sources.AiderFiles()\n\tvar aiderSize int64\n\taiderRedactions := 0\n\tfor _, p := range aiderFiles {\n\t\tif fi, err := os.Stat(p); err == nil {\n\t\t\taiderSize += fi.Size()\n\t\t}\n\t\taiderRedactions += redactions[p]\n\t}\n\taiderLocationForSkip := filepath.Join(sources.Home(), \".aider.chat.history.md\")\n\tskipAider := excludedRow(\"aider\", aiderLocationForSkip)\n\tvar rawAiderSessions, aiderSessions []model.Session\n\tif !skipAider {\n\t\trawAiderSessions = sources.LoadAider()\n\t\taiderSessions = sources.FilterSessions(rawAiderSessions)\n\t}\n\taiderMessages := 0\n\tfor _, s := range aiderSessions {\n\t\taiderMessages += sources.CountMessages([]model.Session{s})\n\t}\n\taiderLocation := filepath.Join(sources.Home(), \".aider.chat.history.md\")\n\tif roots := os.Getenv(\"DEJA_AIDER_ROOTS\"); roots != \"\" {\n\t\taiderLocation += string(os.PathListSeparator) + roots\n\t}\n\tnote := \"\"\n\tif n := projectExcludePatterns(); n > 0 {\n\t\tnote = fmt.Sprintf(\"\\texcluded-patterns=%d\", n)\n\t}\n\tif excluded := len(rawAiderSessions) - len(aiderSessions); excluded > 0 {\n\t\tnote += fmt.Sprintf(\"\\texcluded-sessions=%d\", excluded)\n\t}\n\tnote += unreadNote(\"aider\")\n\tif len(rawAiderSessions) == 0 && !skipAider {\n\t\tnote += \"\\tnote=\" + aiderNoHistoryHint\n\t}\n\tif !skipAider {\n\t\tfmt.Fprintf(w, \"aider\\t%s\\tsessions=%d messages=%d size=%s redacted=%d%s\\n\", aiderLocation, sources.CountSessions(aiderSessions), aiderMessages, humanBytes(aiderSize), aiderRedactions, note)\n\t}\n\tif excludedRow(\"opencode\", sources.OpencodeDB()) {\n\t\treturn\n\t}\n\tvar size int64\n\tif fi, err := os.Stat(sources.OpencodeDB()); err == nil {\n\t\tsize = fi.Size()\n\t}\n\ts, m, countErr := sources.OpencodeCounts()\n\t// The counts come out of sqlite, which knows nothing about the exclude\n\t// list, so with a pattern in force this row kept reporting sessions that\n\t// are not indexed, not searchable and not exported while every other row\n\t// subtracted them (#2247). Only then is the store loaded: counting by SQL\n\t// is why this row is cheap on a large database.\n\topencodeExcluded := 0\n\tif len(sources.ExclusionPatterns()) > 0 {\n\t\traw := sources.LoadOpencode()\n\t\tkept := sources.FilterSessions(raw)\n\t\topencodeExcluded = len(raw) - len(kept)\n\t\t// Subtracted from the SQL numbers rather than recounted from what\n\t\t// loaded: the loader drops a session holding no text at all, which the\n\t\t// row has always counted, so recounting would move the numbers for a\n\t\t// reason that has nothing to do with the exclude list.\n\t\tdropped := 0\n\t\tfor _, x := range raw {\n\t\t\tif sources.ExcludedProject(x.Project) {\n\t\t\t\tdropped += len(x.Messages)\n\t\t\t}\n\t\t}\n\t\ts, m = max(0, s-opencodeExcluded), max(0, m-dropped)\n\t}\n\tnote = \"\"\n\tif size > 0 && !sources.SQLite3Available() {\n\t\tnote = \"\\t(\" + sources.SQLite3Problem() + \" — opencode sessions unavailable)\"\n\t}\n\tif n := projectExcludePatterns(); n > 0 {\n\t\tnote += fmt.Sprintf(\"\\texcluded-patterns=%d\", n)\n\t}\n\tif opencodeExcluded > 0 {\n\t\tnote += fmt.Sprintf(\"\\texcluded-sessions=%d\", opencodeExcluded)\n\t}\n\t// A store sqlite could not open — locked past the timeout, or a file the\n\t// reader may not open — looked like one nobody had used, the shape #1000\n\t// fixed for the file stores (#3190).\n\tif countErr != nil && sources.SQLite3Available() {\n\t\treason := \"sqlite3: \" + countErr.Error()\n\t\tif line := sources.ExitStderrLine(countErr); line != \"\" {\n\t\t\treason = \"sqlite3: \" + line\n\t\t}\n\t\tif f, err := os.Open(sources.OpencodeDB()); err != nil {\n\t\t\treason = err.Error()\n\t\t} else {\n\t\t\t_ = f.Close()\n\t\t}\n\t\tnote = \"\\t(cannot be read — \" + reason + \")\" + note\n\t}\n\tnote += unreadNote(\"opencode\")\n\tfmt.Fprintf(w, \"opencode\\t%s\\tsessions=%d messages=%d size=%s redacted=%d%s\\n\", sources.OpencodeDB(), s, m, humanBytes(size), redactions[sources.OpencodeDB()], note)\n}\n\n// orphanedTombstones reports which tombstones name a session that exists\n// nowhere: not in the index and not in any store on disk.\n//\n// Only a positive answer is ever given. A tombstone whose harness this build\n// does not know, or whose store cannot be loaded, is left unmarked — calling a\n// tombstone useless on a guess would invite someone to lift one that is still\n// hiding a transcript.\nfunc orphanedTombstones(dir string, keys []string) map[string]bool {\n\tif len(keys) == 0 {\n\t\treturn nil\n\t}\n\tindexed := index.IndexedSessionKeys(dir)\n\t// Load each harness a tombstone names once, however many tombstones name it.\n\tonDisk := map[string]map[string]bool{}\n\tlive := func(harness string) (map[string]bool, bool) {\n\t\tif seen, ok := onDisk[harness]; ok {\n\t\t\treturn seen, seen != nil\n\t\t}\n\t\tvar found map[string]bool\n\t\tfor _, h := range sources.StoresToRead() {\n\t\t\tif h.Name != harness || h.Load == nil {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tfound = map[string]bool{}\n\t\t\tfor _, s := range h.Load() {\n\t\t\t\tfound[s.Harness+\":\"+s.ID] = true\n\t\t\t}\n\t\t}\n\t\tonDisk[harness] = found\n\t\treturn found, found != nil\n\t}\n\tout := map[string]bool{}\n\tfor _, key := range keys {\n\t\tharness, _, ok := strings.Cut(key, \":\")\n\t\tif !ok || indexed[key] {\n\t\t\tcontinue\n\t\t}\n\t\tstored, known := live(harness)\n\t\tif !known || stored[key] {\n\t\t\tcontinue\n\t\t}\n\t\tout[key] = true\n\t}\n\treturn out\n}\n\n// forgetScopeRefusal stops a destructive run whose selector reaches further\n// than the reader can have meant.\n//\n// `--session` takes a prefix, which is documented and useful for a day's ids —\n// but it also let one exact-looking id drop twelve sessions, and the count\n// arrived in the past tense afterwards (#870). An id copied off a result line\n// is worse still: the characters that tell the sessions apart are the ones the\n// line elided, so no longer prefix exists to reach for (#859).\nfunc forgetScopeRefusal(selector string, matches int, allMatches bool) error {\n\tif matches <= 1 || allMatches {\n\t\treturn nil\n\t}\n\tif strings.Contains(selector, \"…\") {\n\t\treturn fmt.Errorf(\"%q matches %d sessions — the ids differ in the middle the line elides; `deja last` prints them whole\", selector, matches)\n\t}\n\treturn fmt.Errorf(\"%q matches %d sessions — `deja forget --session %s --dry-run` lists what would go; add --all-matches to drop them all\",\n\t\tselector, matches, pasteSafe(selector))\n}\n\nfunc runForget(dir string, args []string) error {\n\tfa, perr := parseForgetArgs(args)\n\tif perr != nil {\n\t\treturn perr\n\t}\n\to, list, allMatches, unforget, unforgetGiven := fa.o, fa.list, fa.allMatches, fa.unforget, fa.unforgetGiven\n\t// An empty `--unforget` was answered with the selectors for forgetting:\n\t// the reader asked to bring something back and was told how to drop more\n\t// (#1041).\n\tif unforgetGiven && unforget == \"\" {\n\t\treturn errors.New(\"forget: --unforget needs an id — `deja forget --list` names the ids\")\n\t}\n\tif !list && unforget == \"\" && o.Session == \"\" && o.Project == \"\" && o.Before.IsZero() {\n\t\t// Naming the selectors here is what separates one call from hundreds:\n\t\t// forgetting 100 sessions one id at a time took 10.5s against 0.2s for\n\t\t// `--project`, and nothing on this path said the second form exists\n\t\t// (#1022).\n\t\treturn errors.New(\"forget: selector required — `--session <id>`, `--project <name>` or `--before <date>`; `--dry-run` shows what would go, `--list` what already went\")\n\t}\n\tif list {\n\t\treturn printForgetList(dir)\n\t}\n\tif unforget != \"\" {\n\t\treturn runUnforget(dir, unforget, allMatches, o.DryRun)\n\t}\n\t// The scope check runs on a dry pass first: a refusal printed after\n\t// index.Forget has already written the tombstones is not a refusal.\n\t//\n\t// The same pass answers what is about to go: after the real Forget the rows\n\t// are out of the manifest, so a row that covered two conversations can no\n\t// longer be recognised (#970).\n\t// With no index, Forget matches in the stores and writes only the\n\t// tombstones. An index on a disk that went away also reads as no index,\n\t// and saying \"nothing indexed yet\" there would leave the session in the\n\t// index that comes back with the disk.\n\tif parent, gone := indexLooksUnmounted(dir); gone && !index.HasManifest(dir) {\n\t\treturn fmt.Errorf(\"the index directory is not there (%s) — the disk it lives on may have been unmounted; reconnect it, or point DEJA_INDEX_DIR somewhere local\", parent)\n\t}\n\tshared := 0\n\tif !o.DryRun {\n\t\tprobe := o\n\t\tprobe.DryRun = true\n\t\tpr, perr := index.Forget(dir, probe)\n\t\tif perr != nil {\n\t\t\t// The probe fails the same ways the real pass does — a vanished\n\t\t\t// volume, a read-only cache — and handing its syscall back was the\n\t\t\t// shape #798 replaced everywhere else.\n\t\t\treturn ensureError(dir, perr)\n\t\t}\n\t\tif o.Session != \"\" {\n\t\t\tif err := forgetScopeRefusal(o.Session, pr.Sessions-pr.Attached, allMatches); err != nil {\n\t\t\t\treturn err\n\t\t\t}\n\t\t}\n\t\tshared = sharedRowsAmong(dir, pr.Keys)\n\t}\n\tresult, err := index.Forget(dir, o)\n\tif !o.DryRun {\n\t\t// The digests cached beside the index quote sessions as prose, and a\n\t\t// forget left them there: recall never served them past their minute,\n\t\t// and the text was still on the disk (#3411).\n\t\tdropHookCaches(dir)\n\t}\n\tif err != nil {\n\t\t// The tombstone is already written; what failed is the rebuild that\n\t\t// takes the records out. Handing back `mkdir /…/idx.tmp: permission\n\t\t// denied` names an internal path and leaves the reader believing the\n\t\t// session is gone while search still returns it (#976).\n\t\tif !o.DryRun && index.Tombstoned(forgetKeyOf(dir, o)) {\n\t\t\treturn fmt.Errorf(\"%w\\nthe session is marked forgotten and is still in the index until it can be rebuilt — search keeps returning it until then\", ensureError(dir, err))\n\t\t}\n\t\treturn ensureError(dir, err)\n\t}\n\tif o.DryRun {\n\t\treturn printForgetDryRun(dir, o, result, allMatches, shared)\n\t}\n\t// A promoted note borrows the source session's first line as its title, and\n\t// the note is a separate record — so forgetting a session left that line on\n\t// screen in `deja last` (#666). The note stays; only the borrowed title\n\t// goes, and the parser falls back to \"promoted from <src>\".\n\t//\n\t// Matching on the keys that were actually dropped rather than on the\n\t// selector: --project and --before drop sessions too, and keying off\n\t// o.Session left the borrowed line — a customer name, in the case that\n\t// found this — sitting in notes.jsonl after the project was forgotten\n\t// (#690).\n\tif len(result.Keys) > 0 {\n\t\tforgetPromotedLeftovers(dir, o, result)\n\t}\n\t// Nothing matched is a different answer from nothing was dropped: the\n\t// first means the selector found no session, and reporting it as a\n\t// successful removal of zero leaves the reader believing they deleted\n\t// something that is in fact still there under a different id.\n\tif result.Sessions == 0 && result.Messages == 0 {\n\t\treturn forgetNothingMatched(dir, o, result)\n\t}\n\tif result.Unindexed {\n\t\t// Nothing was in an index to drop; \"sessions dropped: 1\" would claim a\n\t\t// removal that never happened.\n\t\tfmt.Fprintf(os.Stdout, \"nothing is indexed yet, so nothing was dropped\\ntombstones added: %d — the first `deja index` leaves %s out\\n\",\n\t\t\tresult.Tombstones, safeForStatusline(joinCapped(result.Keys, 5), 400))\n\t} else {\n\t\tfmt.Fprintf(os.Stdout, \"sessions dropped: %d\\nmessages dropped: %d\\ntombstones added: %d\\n\", result.Sessions, result.Messages, result.Tombstones)\n\t}\n\t// \"1 session\" can be two conversations: transcripts that share an id are\n\t// filed under one row, and the message count is the only tell (#970).\n\tif shared > 0 {\n\t\tfmt.Fprintf(os.Stdout, \"%s covered more than one conversation — transcripts that share an id are filed under one row, and both went\\n\",\n\t\t\tdoctorCount(shared, \"of them\"))\n\t}\n\t// Forgetting keeps the session out of later pushes but cannot reach a\n\t// machine that already has it. Three lines about what was dropped read as\n\t// \"it is gone everywhere\" to someone forgetting a customer name (#788).\n\tif len(result.Peers) > 0 {\n\t\tfmt.Fprintf(os.Stdout, \"already pushed to %s — forgetting here does not remove it there\\n\", strings.Join(result.Peers, \", \"))\n\t} else if result.Exported {\n\t\tfmt.Fprintln(os.Stdout, \"already exported once — forgetting here does not remove copies elsewhere\")\n\t}\n\tif line := forgetCopiesLine(result.Copies); line != \"\" {\n\t\tfmt.Fprintln(os.Stdout, line)\n\t}\n\t// The notes are decisions the reader deliberately kept, so folding them\n\t// into the session count reads as \"four conversations\" when half of it is\n\t// their own writing (#690).\n\t// Through forgetNotesLine, like the dry run above it. #957 taught that\n\t// sentence to tell a `remember` note from a promoted one and only wired it\n\t// into `--dry-run`, so the run that actually dropped a day of notes still\n\t// called them promoted — the same command, two answers, and the wrong one\n\t// on the path that changes something (#3599).\n\tif line := forgetNotesLine(result); line != \"\" {\n\t\tfmt.Fprintln(os.Stdout, line)\n\t}\n\treturn nil\n}\n\n// forgetCopiesLine names the sessions that still hold a copy of what was\n// forgotten: a fork opens with its source's turns under its own id. Named, not\n// taken: forgetting a fork whole drops the work it did after the copy.\nfunc forgetCopiesLine(keys []string) string {\n\tif len(keys) == 0 {\n\t\treturn \"\"\n\t}\n\tverb, cmd := \"hold\", \"`deja forget --session <id>` drops each, with its own work\"\n\tif len(keys) == 1 {\n\t\tid := keys[0]\n\t\tif _, rest, ok := strings.Cut(id, \":\"); ok {\n\t\t\tid = rest\n\t\t}\n\t\tverb, cmd = \"holds\", \"`deja forget --session \"+id+\"` drops it too, with its own work\"\n\t}\n\treturn fmt.Sprintf(\"%s still %s a copy of these turns (a fork or its source): %s — %s\",\n\t\tcountNoun(len(keys), \"other session\"), verb, safeForStatusline(joinCapped(keys, 5), 400), cmd)\n}\n\n// verbShare keeps \"1 session share\" off the screen.\nfunc verbShare(n int) string {\n\tif n == 1 {\n\t\treturn \"shares\"\n\t}\n\treturn \"share\"\n}\n\n// verbWere keeps \"1 of them are promoted notes\" off the screen.\nfunc verbWere(n int) string {\n\tif n == 1 {\n\t\treturn \"is a\"\n\t}\n\treturn \"are\"\n}\n\n// forgetSelector names what the caller asked to forget, so the empty answer\n// says which selector came back empty.\nfunc forgetSelector(o index.ForgetOptions) string {\n\tvar parts []string\n\tif o.Session != \"\" {\n\t\tparts = append(parts, fmt.Sprintf(\"session %q\", o.Session))\n\t}\n\tif o.Project != \"\" {\n\t\tparts = append(parts, fmt.Sprintf(\"project %q\", o.Project))\n\t}\n\tif !o.Before.IsZero() {\n\t\tparts = append(parts, \"before \"+o.Before.Format(\"2006-01-02\"))\n\t}\n\tif len(parts) == 0 {\n\t\treturn \"the given selector\"\n\t}\n\treturn strings.Join(parts, \" and \")\n}\n\nfunc parseForgetDate(s string) (time.Time, error) {\n\tfor _, layout := range []string{time.RFC3339, \"2006-01-02\", \"2006-01-02 15:04:05\"} {\n\t\tif t, err := time.Parse(layout, s); err == nil {\n\t\t\treturn t, nil\n\t\t}\n\t}\n\treturn time.Time{}, errors.New(\"invalid date\")\n}\n\nfunc redactionsUnder(files map[string]int, root string) int {\n\ttotal := 0\n\tfor p, n := range files {\n\t\tif p == root || strings.HasPrefix(p, root+string(os.PathSeparator)) {\n\t\t\ttotal += n\n\t\t}\n\t}\n\treturn total\n}\n\nfunc pathSize(root string) int64 {\n\tvar total int64\n\t_ = filepath.WalkDir(root, func(_ string, d os.DirEntry, err error) error {\n\t\tif err == nil && d.Type()&os.ModeSymlink == 0 && !d.IsDir() {\n\t\t\tif fi, e := d.Info(); e == nil {\n\t\t\t\ttotal += fi.Size()\n\t\t\t}\n\t\t}\n\t\treturn nil\n\t})\n\treturn total\n}\n\nfunc humanBytes(n int64) string {\n\tunits := []string{\"B\", \"KB\", \"MB\", \"GB\", \"TB\"}\n\tf := float64(n)\n\ti := 0\n\tfor f >= 1024 && i < len(units)-1 {\n\t\tf /= 1024\n\t\ti++\n\t}\n\tif i == 0 {\n\t\treturn fmt.Sprintf(\"%d B\", n)\n\t}\n\treturn fmt.Sprintf(\"%.1f %s\", f, units[i])\n}\n\n// wrapTargets lays install target names out over as many indented lines as they\n// need. Naming them inline in the usage text is what let help drift: eleven of\n// the thirty-one were listed, so `deja install aider` and `deja install\n// openclaw-auto` — both of them in the README — read as invalid (#1106).\nfunc wrapTargets(names []string, indent string, width int) string {\n\tvar b strings.Builder\n\tline := indent\n\tfor i, n := range names {\n\t\tpiece := n\n\t\tif i < len(names)-1 {\n\t\t\tpiece += \",\"\n\t\t}\n\t\tif len(line) > len(indent) && len(line)+1+len(piece) > width {\n\t\t\tb.WriteString(line + \"\\n\")\n\t\t\tline = indent\n\t\t}\n\t\tif len(line) > len(indent) {\n\t\t\tline += \" \"\n\t\t}\n\t\tline += piece\n\t}\n\treturn b.String() + line\n}\n\n// helpHidden names the commands deliberately kept out of `deja help`. They are\n// wired by `deja install` and read by a harness, not typed by a person: the\n// session-start and compaction hooks, goose's two, the refresh worker and the\n// warmup probe. The list exists so the omission is a decision with a reason\n// rather than drift — help listed five hook commands and hid five, including\n// hook-context, because the text is hand-maintained and nothing compared it\n// with the dispatch table (#1654). TestHelpCoversEveryCommand is that\n// comparison.\nvar helpHidden = map[string]bool{\n\t\"help\":              true,\n\t\"hook-codewhale\":    true,\n\t\"hook-context\":      true,\n\t\"hook-goose\":        true,\n\t\"hook-goose-prompt\": true,\n\t\"hook-mcp-call\":     true,\n\t\"hook-precompact\":   true,\n\t\"hook-refresh\":      true,\n\t\"hook-session-end\":  true,\n\t\"hook-stop\":         true,\n\t\"reasonix-ext\":      true,\n\t\"warmup-status\":     true,\n}\n\nfunc printUsage() {\n\tfmt.Print(wrapUsage(usageText(), printableWidth(os.Stdout)))\n}\n\n// usageWidth is the column budget for the parts of help that are laid out\n// rather than typed. It follows the terminal, as the brief, files, restore and\n// search already do — the list was computed to a fixed 76 and so came out the\n// same six lines on a 30-column pane and a 120-column one (#1660).\n//\n// Off a terminal printableWidth answers 0, and the fixed 76 stands: piped and\n// redirected help keeps the byte-identical output that goldens and CI compare.\nfunc usageWidth() int {\n\tif w := printableWidth(os.Stdout); w > 0 {\n\t\treturn w\n\t}\n\treturn 76\n}\n\n// wantsHelp reports whether a command line asks for help rather than work.\nfunc wantsHelp(rest []string) bool {\n\tfor _, a := range rest {\n\t\tif a == \"--help\" || a == \"-h\" {\n\t\t\treturn true\n\t\t}\n\t\tif a == \"--\" {\n\t\t\treturn false\n\t\t}\n\t}\n\treturn false\n}\n\n// movedBucketHint explains a note-bucket id that stopped resolving. The id\n// carries the day it was minted in, so a machine that changed zone renames its\n// buckets on the next build — and every id refusal then read as \"that note is\n// gone\" while the note sat under the neighbouring day (#1039).\nfunc movedBucketHint(dir, id string) string {\n\tif !strings.HasPrefix(id, \"deja-\") || len(id) < 15 {\n\t\treturn \"\"\n\t}\n\tday, rest := id[5:15], id[15:]\n\twhen, err := time.Parse(\"2006-01-02\", day)\n\tif err != nil {\n\t\treturn \"\"\n\t}\n\tmetas, err := index.AllMeta(dir)\n\tif err != nil {\n\t\treturn \"\"\n\t}\n\tpol := policy.Load()\n\tfor _, shift := range []int{-1, 1} {\n\t\twant := \"deja-\" + when.AddDate(0, 0, shift).Format(\"2006-01-02\") + rest\n\t\tfor _, m := range metas {\n\t\t\tif m.ID != want {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\t// Naming it is recalling it: a rule that hides the session hides\n\t\t\t// the fact that it moved too, or the hint becomes the way around\n\t\t\t// the rule (#1043).\n\t\t\tif !pol.Allows(policy.ActivationSearch, m.Project) {\n\t\t\t\treturn \"\"\n\t\t\t}\n\t\t\treturn fmt.Sprintf(\" — the days regrouped when this machine's zone changed; it is %#q now\", want)\n\t\t}\n\t}\n\treturn \"\"\n}\n\n// showNeedsID is the refusal show gives with no argument. \"id-prefix\" names a\n// thing the reader has no way to produce on their own; promote has pointed at\n// `deja last` all along, and show, share and resume are the three commands\n// reached for right after a search result (#1063).\nconst showNeedsID = \"show needs an id prefix (see `deja last`)\"\n\n// noSessionMatches is the refusal for an id that names no session: the bucket\n// that moved when there is one, otherwise where the ids are listed (#1063).\nfunc noSessionMatches(dir, id string) error {\n\tif hint := movedBucketHint(dir, id); hint != \"\" {\n\t\treturn fmt.Errorf(\"no session matches %q%s\", id, hint)\n\t}\n\treturn fmt.Errorf(\"no session matches %q — `deja last` lists recent ones\", id)\n}\n\n// idPrefixNeeded is the refusal for a command that needs a session named on the\n// command line. \"see `deja last`\" is a step the reader can take and learn\n// nothing from when the store is empty: the listing answers with the same\n// emptiness deja already knows about here (#992).\nfunc idPrefixNeeded(dir, subject, refusal string) error {\n\tif n, err := index.SessionCount(dir); err == nil && n == 0 {\n\t\treturn errors.New(strings.TrimPrefix(emptyIndexHint(subject+\", and nothing is indexed yet\"), \"deja: \"))\n\t}\n\treturn errors.New(refusal)\n}\n\n// indexIsEmpty reports whether the index holds no session at all. An index\n// that cannot be counted counts as empty on purpose, so the caller falls back\n// to the empty-index hint it printed before.\nfunc indexIsEmpty(dir string) bool {\n\tn, err := index.SessionCount(dir)\n\treturn err != nil || n == 0\n}\n\n// emptyIndexReason opens the empty-index sentence. \"Nothing to index yet\" is\n// for a machine deja has never seen history from; a run that has just evicted a\n// store says what went away instead, because the line above it has already told\n// the reader what was lost and the two must not contradict each other (#1762).\nfunc emptyIndexReason(_ index.BuildSummary, evicted int) string {\n\tif evicted > 0 {\n\t\treturn emptyIndexHint(fmt.Sprintf(\"%d indexed file%s went away with the store that held %s, and nothing is left to index\",\n\t\t\tevicted, pluralS(evicted), pluralWhich(evicted)))\n\t}\n\treturn emptyIndexHint(\"nothing to index yet\")\n}\n\n// deniedStoresLine names the stores deja could not read on a pass whose index\n// still holds sessions, with the files the pass evicted when there were any.\nfunc deniedStoresLine(denied, evicted int) string {\n\tline := fmt.Sprintf(\"%d store%s could not be read (permission denied); `deja doctor` names %s\",\n\t\tdenied, pluralS(denied), pluralWhich(denied))\n\tif evicted > 0 {\n\t\tline = fmt.Sprintf(\"%d indexed file%s went away with the store that held %s — %s\",\n\t\t\tevicted, pluralS(evicted), pluralWhich(evicted), line)\n\t}\n\treturn \"deja: \" + line\n}\n\n// emptyIndexHint phrases the nothing-here answer the same way everywhere, and\n// points at the next command rather than leaving the user to guess.\n//\n// Which command depends on why it is empty. Every path that reaches here has\n// already built the index — the build narration prints a line above this one —\n// so telling someone to run `deja index` sends them to do again what just\n// happened, and they are left where they started. When no agent history was\n// found at all, the useful next step is finding out where deja looked.\nfunc emptyIndexHint(what string) string {\n\t// A store deja is not allowed to open, before anything else. The sessions\n\t// are there, behind a permission wall doctor and sources both name (#1020)\n\t// — and the branch used to sit inside the no-history one, so it was\n\t// unreachable in the case that matters: a store whose files deja can see\n\t// and cannot read counts as history, so the answer was \"run `deja index`\",\n\t// which is what the reader had just done and cannot help (#3585).\n\tif denied := deniedStoreCount(); denied > 0 {\n\t\treturn fmt.Sprintf(\"deja: %s — %d store%s could not be read (permission denied); `deja doctor` names %s\",\n\t\t\twhat, denied, pluralS(denied), pluralWhich(denied))\n\t}\n\tif noAgentHistoryFound() {\n\t\treturn \"deja: \" + what + \" — no agent history was found on this machine; `deja sources` shows where deja looked\"\n\t}\n\treturn \"deja: \" + what + \" — run `deja index`, or `deja doctor` to see which agent stores were found\"\n}\n\n// emptyStoreLine is emptyIndexHint for a command whose answer goes to stdout\n// without deja's prefix, when the index holds no session at all. tests,\n// secrets, recap and rules candidates each said their own nothing there —\n// \"no provider keys … in your agent history\" read as an all-clear on a machine\n// with no history to check.\nfunc emptyStoreLine(dir, what string) (string, bool) {\n\tif n, err := index.SessionCount(dir); err != nil || n > 0 {\n\t\treturn \"\", false\n\t}\n\t// At a terminal, at its width and between words; piped, as one line.\n\treturn fitLine(os.Stdout, strings.TrimPrefix(emptyIndexHint(what), \"deja: \")), true\n}\n\n// newestSessionNote is the tail of an empty windowed answer: when the newest\n// session it may show is older than the window, the date and the --since that\n// reaches it. The demo store of a machine idle for three months answered\n// `deja recap` with \"nothing in the last 7d\" and nothing else.\nfunc newestSessionNote(dir, command string, window time.Duration) string {\n\tmetas, err := index.AllMeta(dir)\n\tif err != nil {\n\t\treturn \"\"\n\t}\n\tpol := policy.Load()\n\tvar newest time.Time\n\tfor _, m := range metas {\n\t\tif m.Updated.After(newest) && pol.Allows(policy.ActivationSearch, m.Project) {\n\t\t\tnewest = m.Updated\n\t\t}\n\t}\n\tif newest.IsZero() || time.Since(newest) <= window {\n\t\treturn \"\"\n\t}\n\tdays := int(time.Since(newest).Hours()/24) + 1\n\treturn fmt.Sprintf(\" — the newest session is from %s; `deja %s --since %dd` reaches it\",\n\t\tnewest.Local().Format(\"2006-01-02\"), command, days)\n}\n\n// fitLine wraps a sentence between words at the width of the terminal w is,\n// and leaves it whole for a pipe.\nfunc fitLine(w io.Writer, line string) string {\n\tif n := printableWidth(w); n > 0 {\n\t\treturn wrapProse(line, n)\n\t}\n\treturn line\n}\n\n// sinceArg is the --since value as the reader typed it.\nfunc sinceArg(args []string) string {\n\tfor i, a := range args {\n\t\tif a == \"--since\" && i+1 < len(args) {\n\t\t\treturn args[i+1]\n\t\t}\n\t}\n\treturn \"\"\n}\n\n// countNoun is \"1 session\" or \"3 sessions\"; the forget dry run printed\n// \"1 session(s)\".\nfunc countNoun(n int, noun string) string {\n\treturn fmt.Sprintf(\"%d %s%s\", n, noun, pluralS(n))\n}\n\nfunc forgetCounts(sessions, messages int) string {\n\treturn countNoun(sessions, \"session\") + \", \" + countNoun(messages, \"message\")\n}\n\n// deniedStoreCount reports how many harness stores exist but cannot be opened.\n// Opened, not parsed: the probe stops before doctor's parser (#4272).\nfunc deniedStoreCount() int {\n\tn := 0\n\tfor _, check := range deniedStoreChecks() {\n\t\tif store, _, _ := probeDoctorStore(check); store.State == \"denied\" {\n\t\t\tn++\n\t\t}\n\t}\n\treturn n\n}\n\n// deniedStoreChecks is doctorStoreChecks, swappable so a test can count what\n// the probe parses.\nvar deniedStoreChecks = doctorStoreChecks\n\n// noAgentHistoryFound reports whether the stores themselves are empty, as\n// opposed to an index that merely has not been built yet.\nfunc noAgentHistoryFound() bool {\n\tfor _, check := range doctorStoreChecks() {\n\t\t// The count, not the inspection. `store.Files` is `len(check.files)`\n\t\t// and nothing else ever sets it (doctor_report.go:471), so asking\n\t\t// `inspectDoctorStore` for it paid a stat per path, a listing per\n\t\t// directory, and the newest file of the store opened and run through\n\t\t// that store's parser — SQLite for opencode and cursor — to learn a\n\t\t// number already in hand. Measured on a real home, 514 ms against\n\t\t// 6.6 ms for the same answer (#1991).\n\t\tif len(check.files) == 0 {\n\t\t\tcontinue\n\t\t}\n\t\t// By content, not by existence: an empty notes file — one `deja\n\t\t// remember` later forgotten, or a file someone touched — counted as\n\t\t// history and turned the answer into \"run `deja index`\", which is the\n\t\t// one piece of advice this branch exists to avoid (#996).\n\t\tfor _, f := range check.files {\n\t\t\tif fi, err := os.Stat(f); err == nil && fi.Size() > 0 {\n\t\t\t\treturn false\n\t\t\t}\n\t\t}\n\t}\n\treturn true\n}\n\n// pluralNote words the notes in the failure line above.\nfunc pluralNote(n int) string {\n\tif n == 1 {\n\t\treturn \"the promoted note\"\n\t}\n\treturn \"the promoted notes\"\n}\n\n// forgetTitleFix names the fix by the cause. The first version of this line\n// said \"permissions\" whatever had happened, so a full disk sent the reader to\n// chmod a file that was already writable (#808).\nfunc forgetTitleFix(err error) string {\n\tswitch {\n\tcase errors.Is(err, fs.ErrPermission):\n\t\treturn \"fix that file's permissions\"\n\tcase errors.Is(err, syscall.ENOSPC):\n\t\treturn \"free some space on that filesystem\"\n\t}\n\treturn \"clear the problem above\"\n}\n\n// sortedHarnesses orders the ingest-health entries so a run reports them the\n// same way twice.\nfunc sortedHarnesses(m map[string]index.HarnessIngest) []string {\n\tout := make([]string, 0, len(m))\n\tfor h := range m {\n\t\tout = append(out, h)\n\t}\n\tsort.Strings(out)\n\treturn out\n}\n\n// pluralSessionWord words the tail of the empty-transcript line.\nfunc pluralSessionWord(n int) string {\n\tif n == 1 {\n\t\treturn \"a session\"\n\t}\n\treturn \"sessions\"\n}\n\n// pluralWhich matches the pronoun to the count in the ingest warning.\nfunc pluralWhich(n int) string {\n\tif n == 1 {\n\t\treturn \"it\"\n\t}\n\treturn \"them\"\n}\n\n// staleUnwritableIndex reports that a build could not run because the store\n// cannot be written, while an index that can still answer is right there.\n// Refusing the whole search then is deja withholding what it has: the reader\n// gets nothing instead of slightly old memory and a line saying why (#904).\n// A full disk belongs here next to a denied one: it is the commoner of the\n// two, and it took every answer with it — empty stdout and exit 1 while a\n// complete index sat in the store.\nfunc staleUnwritableIndex(dir string, err error) bool {\n\tif !index.Unwritable(err) && !errors.Is(err, syscall.ENOSPC) {\n\t\treturn false\n\t}\n\treturn index.HasManifest(dir)\n}\n\n// deniedPath names the file a permission error was actually about, so the fix\n// deja suggests points at it rather than at the index directory (#1031).\nfunc deniedPath(err error) string {\n\tvar pe *fs.PathError\n\tif errors.As(err, &pe) {\n\t\treturn pe.Path\n\t}\n\treturn \"\"\n}\n\n// existingNonDirAncestor names the first ancestor of p that exists and is not\n// a directory. Such a path can never hold an index, and the errno differs by\n// platform, so the shape is worth naming rather than the syscall.\nfunc existingNonDirAncestor(p string) string {\n\tfor cur := filepath.Clean(p); ; {\n\t\tparent := filepath.Dir(cur)\n\t\tif parent == cur {\n\t\t\treturn \"\"\n\t\t}\n\t\tif fi, err := os.Stat(parent); err == nil && !fi.IsDir() {\n\t\t\treturn parent\n\t\t}\n\t\tcur = parent\n\t}\n}\n\n// nearestExistingDir walks up until it finds a directory that is there, so a\n// refusal can name the thing that actually refused rather than the path that\n// could not be created under it.\nfunc nearestExistingDir(p string) string {\n\tfor cur := filepath.Clean(p); ; {\n\t\tparent := filepath.Dir(cur)\n\t\tif parent == cur {\n\t\t\tif dirExists(cur) {\n\t\t\t\treturn cur\n\t\t\t}\n\t\t\treturn \"\"\n\t\t}\n\t\tif dirExists(parent) {\n\t\t\treturn parent\n\t\t}\n\t\tcur = parent\n\t}\n}\n\n// dirWritable reports whether this process can create something in dir.\n// Permission bits alone answer for the wrong user on the wrong platform, so it\n// asks the filesystem.\nfunc dirWritable(dir string) bool {\n\tf, err := os.CreateTemp(dir, \".deja-probe-*\")\n\tif err != nil {\n\t\treturn false\n\t}\n\tname := f.Name()\n\t_ = f.Close()\n\t_ = os.Remove(name)\n\treturn true\n}\n\n// ensureError turns a failed build into something the reader can act on.\n// A denied write surfaced as `ensure: open /…/index.db.lock: permission\n// denied` — the path of an internal lock file and a syscall error, which says\n// nothing about what to change.\nfunc ensureError(dir string, err error) error {\n\tif dir == \"\" {\n\t\tdir = index.DefaultDir()\n\t}\n\t// Worded for the reader already, command included (#5385).\n\tif index.IsManualStop(err) {\n\t\treturn err\n\t}\n\tif errors.Is(err, fs.ErrPermission) {\n\t\t// An ejected volume takes its mount point with it, and creating that\n\t\t// point back fails with EPERM on macOS — so the errno says permissions\n\t\t// while the disk is simply gone. The same trap the notes and export\n\t\t// paths hit (#893, #906), and the reader is sent to check the\n\t\t// permissions of a directory that no longer exists (#931).\n\t\tif parent := filepath.Dir(dir); !dirExists(dir) && !dirExists(parent) {\n\t\t\t// Unless something above it is there and simply refuses: a\n\t\t\t// locked-down ~/.cache cannot be written into either, and reading\n\t\t\t// that as an ejected volume sent the reader to reconnect a disk\n\t\t\t// that never left (#2267).\n\t\t\tif a := nearestExistingDir(parent); a != \"\" && !dirWritable(a) {\n\t\t\t\treturn fmt.Errorf(\"cannot create the index directory (%s) — %s is not writable; check its permissions, or point DEJA_INDEX_DIR somewhere writable\", parent, a)\n\t\t\t}\n\t\t\treturn fmt.Errorf(\"the index directory is not there (%s) — the disk it lives on may have been unmounted; reconnect it, or point DEJA_INDEX_DIR somewhere local\", parent)\n\t\t}\n\t\t// The denial is not always about the index: forget writes the\n\t\t// tombstone file first, and a read-only ~/.config/deja arrived here\n\t\t// as \"check the index directory\", which was writable — the reader was\n\t\t// sent to change a permission that was already right (#1031, #808).\n\t\tif p := deniedPath(err); p != \"\" && !strings.HasPrefix(p, dir) {\n\t\t\treturn fmt.Errorf(\"cannot write %s — check that file's permissions\", p)\n\t\t}\n\t\treturn fmt.Errorf(\"cannot write the index at %s — check the directory's permissions, or point DEJA_INDEX_DIR somewhere writable\", dir)\n\t}\n\t// A full disk arrived as `ensure: write /…/index.db.tmp/records.bin: no\n\t// space left on device`: an internal path nobody can act on, and the same\n\t// shape #798 replaced for permissions. The build needs room beside the\n\t// index, so the directory to free is the one named here (#888).\n\t// A volume that went away mid-write — an unmounted disk, a network share\n\t// that dropped — arrives as `write /…/index.db.tmp/records.bin:\n\t// input/output error`: the same internal path as #888, and a reader who\n\t// cannot tell that the disk is simply gone (#899).\n\tif errors.Is(err, syscall.EIO) || errors.Is(err, syscall.ENXIO) || errors.Is(err, syscall.ENODEV) {\n\t\treturn fmt.Errorf(\"the index directory is not reachable (%s) — the disk it lives on may have been unmounted or dropped; reconnect it, or point DEJA_INDEX_DIR somewhere local\", filepath.Dir(dir))\n\t}\n\tif errors.Is(err, syscall.ENOSPC) {\n\t\treturn fmt.Errorf(\"no space left where the index is built (%s) — free some room there, or point DEJA_INDEX_DIR at a disk that has it\", filepath.Dir(dir))\n\t}\n\t// A volume ejected cleanly mid-build leaves its mount point behind as an\n\t// empty directory, so the write fails with ENOENT rather than the EIO of a\n\t// disk yanked out (#899) — an internal `idx.tmp/buckets/…` path and a\n\t// syscall for what is simply a disconnected disk. The index that was\n\t// already there is untouched, since the build writes beside it and\n\t// renames, and saying so is the part that decides whether the reader goes\n\t// looking for damage (#1068).\n\t// An index path that points inside a file is not a disconnected disk: on\n\t// unix the write fails with ENOTDIR and fell through to the raw syscall,\n\t// on windows it fails with ENOENT and read as an unmounted volume (found\n\t// by CI on windows after #1068).\n\tif p := existingNonDirAncestor(dir); p != \"\" {\n\t\treturn fmt.Errorf(\"the index path runs through %s, which is a file — point DEJA_INDEX_DIR at a directory\", p)\n\t}\n\tif errors.Is(err, fs.ErrNotExist) && !dirExists(dir) {\n\t\t// Only a write inside the build directory is a build the disk went\n\t\t// away from. A read of an index never built fails the same way, and\n\t\t// sent a fresh machine to reconnect a disk that was fine (#5057).\n\t\tvar pe *fs.PathError\n\t\tif errors.As(err, &pe) && !pathUnder(pe.Path, dir+\".tmp\") {\n\t\t\treturn fmt.Errorf(\"nothing is indexed yet (%s) — `deja index` builds it\", dir)\n\t\t}\n\t\treturn fmt.Errorf(\"the index directory went away mid-build (%s) — the disk it lives on may have been unmounted; the index already there is unharmed, so reconnect it and run `deja index` again, or point DEJA_INDEX_DIR somewhere local\", dir)\n\t}\n\t// Already worded where it was raised — the leftover-swap case names the\n\t// directory to remove and the command to rerun, the refused index path\n\t// names the file it will not delete, and \"ensure:\" in front of either is\n\t// internal noise (#1009).\n\tfor _, worded := range []string{\"an earlier index swap left \", \"the index path \"} {\n\t\tif strings.HasPrefix(err.Error(), worded) {\n\t\t\treturn err\n\t\t}\n\t}\n\treturn fmt.Errorf(\"ensure: %w\", err)\n}\n\n// pathUnder reports whether p is dir or lies inside it.\nfunc pathUnder(p, dir string) bool {\n\trel, err := filepath.Rel(filepath.Clean(dir), filepath.Clean(p))\n\treturn err == nil && rel != \"..\" && !strings.HasPrefix(rel, \"..\"+string(filepath.Separator)) && !filepath.IsAbs(rel)\n}\n\n// indexLooksUnmounted reports an index whose directory and parent are both\n// missing where a build could not simply create them: a volume that went\n// away, not a machine that never built an index. It returns the parent to\n// name.\nfunc indexLooksUnmounted(dir string) (string, bool) {\n\tif dir == \"\" {\n\t\tdir = index.DefaultDir()\n\t}\n\tparent := filepath.Dir(dir)\n\tif dirExists(dir) || dirExists(parent) {\n\t\treturn parent, false\n\t}\n\treturn parent, !freshHomePath(parent)\n}\n\n// searchValueFlags take a value, so \"--flag=value\" has to become two arguments\n// before the parser sees it. Anything else keeps its equals sign: a query may\n// legitimately contain one.\nvar searchValueFlags = map[string]bool{\n\t\"--harness\": true, \"--project\": true, \"--since\": true,\n\t\"--role\": true, \"--limit\": true, \"--session\": true, \"--sort\": true,\n}\n\nfunc splitEqualsForms(args []string) []string {\n\tout := make([]string, 0, len(args))\n\tfor _, a := range args {\n\t\tname, value, found := strings.Cut(a, \"=\")\n\t\tif found && searchValueFlags[name] {\n\t\t\tout = append(out, name, value)\n\t\t\tcontinue\n\t\t}\n\t\tout = append(out, a)\n\t}\n\treturn out\n}\n\n// forgetNotesLine says how much of what is going is the user's own writing.\n// Everything deja files under its own harness counted as a \"promoted note\",\n// so forgetting a day of `remember` notes named something the reader had never\n// done (#957).\nfunc forgetNotesLine(result index.ForgetResult) string {\n\tswitch {\n\tcase result.Notes == 0:\n\t\treturn \"\"\n\tcase result.Promoted == result.Notes:\n\t\treturn fmt.Sprintf(\"%d of them %s promoted note%s — the decisions you kept, not raw sessions\",\n\t\t\tresult.Notes, verbWere(result.Notes), pluralS(result.Notes))\n\tcase result.Promoted == 0:\n\t\tif result.Notes == 1 {\n\t\t\treturn \"1 of them is a day of your own notes, not raw sessions\"\n\t\t}\n\t\treturn fmt.Sprintf(\"%d of them are %s of your own notes, not raw sessions\",\n\t\t\tresult.Notes, dayWord(result.Notes))\n\tdefault:\n\t\treturn fmt.Sprintf(\"%d of them %s your own writing — %d promoted, %s of notes — not raw sessions\",\n\t\t\tresult.Notes, verbWere(result.Notes), result.Promoted, dayWord(result.Notes-result.Promoted))\n\t}\n}\n\n// dayWord names day buckets the way the reader wrote them: by the day.\nfunc dayWord(n int) string {\n\tif n == 1 {\n\t\treturn \"a day\"\n\t}\n\treturn fmt.Sprintf(\"%d days\", n)\n}\n\n// pluralIsLifted and pluralTranscript keep the two sentences readable for one\n// key and for several; joinCapped names up to five.\nfunc pluralIsLifted(n int) string {\n\tif n == 1 {\n\t\treturn \" is\"\n\t}\n\treturn \"s are\"\n}\n\nfunc pluralTranscript(n int) string {\n\tif n == 1 {\n\t\treturn \" it\"\n\t}\n\treturn \"s they\"\n}\n\n// unforgetGoneLines says why a lifted tombstone restored nothing. Two causes\n// with two answers: a session deja only ever held in its own index came from\n// another machine and sync import brings it back (#967), while a transcript\n// this machine wrote and then deleted is simply not on disk — telling that\n// reader to import from another machine names one they never had (#1755).\nfunc unforgetGoneLines(missing []string) []string {\n\tvar imported, local []string\n\tfor _, key := range missing {\n\t\tid := key\n\t\tif _, after, ok := strings.Cut(key, \":\"); ok {\n\t\t\tid = after\n\t\t}\n\t\tif strings.HasPrefix(id, \"imported-\") {\n\t\t\timported = append(imported, key)\n\t\t\tcontinue\n\t\t}\n\t\tlocal = append(local, key)\n\t}\n\tvar out []string\n\tif len(imported) > 0 {\n\t\tout = append(out, fmt.Sprintf(\"%s came from another machine and deja held the only copy — the tombstone%s lifted, but the records are gone; `deja sync import` brings them back\", joinCapped(imported, 5), pluralIsLifted(len(imported))))\n\t}\n\tif len(local) > 0 {\n\t\tout = append(out, fmt.Sprintf(\"%s %s no longer on this machine — the tombstone%s lifted, but the transcript%s named %s gone, so there is nothing to index\",\n\t\t\tjoinCapped(local, 5), verbIs(len(local)), pluralIsLifted(len(local)), pluralTranscript(len(local)), verbIs(len(local))))\n\t}\n\treturn out\n}\n\n// restoredSessions splits what a lifted tombstone actually returned from what\n// it could not: a session whose transcript is on this machine is re-read by the\n// rebuild, while an imported one existed only in the index that forget rewrote.\nfunc restoredSessions(dir, selector string, lifted int, lifting []string) (back, gone int, names, missing []string) {\n\tmetas, err := index.AllMeta(dir)\n\tif err != nil {\n\t\treturn lifted, 0, lifting, nil\n\t}\n\t// A session counts as back only if its row is in the manifest again: an\n\t// imported one lives only in the index, so forget took the last copy and\n\t// lifting its tombstone restores nothing (#967).\n\there := map[string]bool{}\n\tfor _, m := range metas {\n\t\there[m.Harness+\":\"+m.ID] = true\n\t}\n\tfor _, key := range lifting {\n\t\tif here[key] {\n\t\t\tback++\n\t\t\tnames = append(names, key)\n\t\t\tcontinue\n\t\t}\n\t\tmissing = append(missing, key)\n\t}\n\tif back == 0 && lifted > 0 {\n\t\t// Selectors that are not whole keys (a bare id, a prefix) still count\n\t\t// through the manifest, as before.\n\t\tfor _, m := range metas {\n\t\t\tif index.SelectorMatches(m, selector) {\n\t\t\t\tback++\n\t\t\t\tnames = append(names, m.Harness+\":\"+m.ID)\n\t\t\t}\n\t\t}\n\t\tif back > lifted {\n\t\t\tback, names = lifted, names[:lifted]\n\t\t}\n\t\tif back > 0 {\n\t\t\t// The prefix path found them by manifest row, so nothing here is\n\t\t\t// missing by name.\n\t\t\tmissing = nil\n\t\t}\n\t}\n\tsort.Strings(names)\n\tsort.Strings(missing)\n\treturn back, lifted - back, names, missing\n}\n\n// restorePromotedTitles gives a promoted note back the title it borrowed from a\n// session that has just been restored. forget clears it so the text of a\n// forgotten session does not live on in the note (#666); unforget is the moment\n// that reason stops applying (#969).\nfunc restorePromotedTitles(dir, selector string) {\n\tmetas, err := index.AllMeta(dir)\n\tif err != nil {\n\t\treturn\n\t}\n\ttitles := map[string]string{}\n\tfor _, m := range metas {\n\t\tif !index.SelectorMatches(m, selector) {\n\t\t\tcontinue\n\t\t}\n\t\ts, ok, err := index.FindByPrefix(dir, m.ID)\n\t\tif err != nil || !ok {\n\t\t\tcontinue\n\t\t}\n\t\tif t := firstUserTitle(s); t != \"\" {\n\t\t\ttitles[m.Harness+\":\"+m.ID] = t\n\t\t}\n\t}\n\tif len(titles) == 0 {\n\t\treturn\n\t}\n\t_, _ = sources.RestorePromotedTitles(func(src string) string { return titles[src] })\n}\n\n// sharedRowsAmong counts the manifest rows in keys that hold more than one\n// conversation, so forget can say what it is about to take (#970).\nfunc sharedRowsAmong(dir string, keys []string) int {\n\tif len(keys) == 0 {\n\t\treturn 0\n\t}\n\tmetas, err := index.AllMeta(dir)\n\tif err != nil {\n\t\treturn 0\n\t}\n\twant := make(map[string]bool, len(keys))\n\tfor _, k := range keys {\n\t\twant[k] = true\n\t}\n\tn := 0\n\tfor _, m := range metas {\n\t\tif m.Shared && want[m.Harness+\":\"+m.ID] {\n\t\t\tn++\n\t\t}\n\t}\n\treturn n\n}\n\n// noteForgottenSource says when an id lookup landed on the note promoted from a\n// session that has been forgotten. Asking for the session by the id you\n// remember answered with the note and said nothing, so the reply looked like\n// the session itself until you noticed the id had changed (#971).\nfunc noteForgottenSource(s model.Session, selector string, resolved bool) {\n\tif line := forgottenSourceNote(s, selector, resolved); line != \"\" {\n\t\tfmt.Fprintf(os.Stderr, \"deja: %s\\n\", line)\n\t}\n}\n\n// forgottenSourceNote is the sentence itself, so every surface can carry it.\n// resolved says the selector reached this session through a prefix lookup: on\n// that path any prefix is honest by construction, and a length rule would only\n// guess at what the resolver already answered.\n// It lived inside the printer, which meant the CLI said a session was\n// forgotten and the MCP tools handed an agent the same note with the fact\n// removed — and \"forgotten\" is a decision the reader made about that session,\n// which is the kind of fact recall exists to carry (#1624).\nfunc forgottenSourceNote(s model.Session, selector string, resolved bool) string {\n\t// Through promotedNoteID, so a note that arrived by sync is one: its local\n\t// id is `imported-…` and the id it names lives in OrigID (#2839).\n\tnoteID := promotedNoteID(s)\n\tif noteID == \"\" {\n\t\treturn \"\"\n\t}\n\tsrc, ok := strings.CutPrefix(noteID, \"deja-note-\")\n\tif !ok || src == \"\" {\n\t\treturn \"\"\n\t}\n\t// The selector named the source, not the note: a reader who typed the note\n\t// id knows what they asked for — either id of it.\n\tif strings.HasPrefix(s.ID, selector) || strings.HasPrefix(noteID, selector) {\n\t\treturn \"\"\n\t}\n\tkey := strings.Replace(src, \"-\", \":\", 1)\n\t// Only when the reader named that session: an ordinary topical query that\n\t// happens to land on the note is not asking about the forgotten source, and\n\t// the line would be noise on every such search.\n\t//\n\t// Named means named. Testing the selector as a substring of the key fired\n\t// on \"claude\" — the harness name is in every key — and on any single\n\t// character, while the reverse case never fired at all: over MCP the\n\t// selector is usually a sentence, and \"what did we decide in s15\" is a\n\t// reader naming the session as plainly as `s15` is (#1624).\n\tif !selectorNamesSession(selector, key, resolved) {\n\t\treturn \"\"\n\t}\n\t// The key the note names is the source's key on the machine that made it,\n\t// and a source that arrived by sync is keyed here by the id the import\n\t// gave it — which is a pure function of that key, so it can be rebuilt\n\t// rather than looked up. Asking about the original alone said nothing\n\t// about a session the reader had forgotten here (#2839).\n\tharness, id, _ := strings.Cut(key, \":\")\n\tif imported := harness + \":\" + index.ImportedSessionID(harness, id); index.Tombstoned(imported) {\n\t\t// Named as the reader will find it in `deja forget --list`.\n\t\tkey = imported\n\t} else if !index.Tombstoned(key) {\n\t\treturn \"\"\n\t}\n\t// Prose, not a command: the key is read here rather than pasted — the\n\t// command in this sentence takes no argument — so it is neutralised the\n\t// way every other echo is.\n\treturn safeForStatusline(key, 200) + \" is forgotten — this is the note promoted from it; `deja forget --list` names what is gone\"\n}\n\n// selectorNamesSession reports whether the reader's selector names this\n// session: the whole key, an id prefix long enough to mean it, or one of the\n// words of a sentence being either of those.\nfunc selectorNamesSession(selector, key string, resolved bool) bool {\n\tif strings.TrimSpace(selector) == \"\" {\n\t\treturn false\n\t}\n\t_, id, _ := strings.Cut(key, \":\")\n\tfor word := range strings.FieldsSeq(selector) {\n\t\tif word == key || word == id {\n\t\t\treturn true\n\t\t}\n\t\t// A prefix counts only where something resolved it: `deja ctx 3f2a9c`\n\t\t// reached this session and nothing else. Where nothing resolved — a\n\t\t// search query — a prefix is a guess, and the ids real harnesses write\n\t\t// make it a bad one: codex ids start with a year, cline ids start with\n\t\t// the harness name, so \"what did we ship in 2026\" and \"cline\" would\n\t\t// each name a session (#1624).\n\t\tif resolved && strings.HasPrefix(id, word) {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\n// forgetKeyOf names the exact session a selector reached, so a failed forget\n// can tell whether the tombstone landed (#976).\nfunc forgetKeyOf(dir string, o index.ForgetOptions) string {\n\tif o.Session == \"\" {\n\t\treturn \"\"\n\t}\n\tmetas, err := index.AllMeta(dir)\n\tif err != nil {\n\t\treturn \"\"\n\t}\n\tfor _, m := range metas {\n\t\tif index.SelectorMatches(m, o.Session) {\n\t\t\treturn m.Harness + \":\" + m.ID\n\t\t}\n\t}\n\treturn \"\"\n}\n\n// reachableSessionCount reports how many indexed sessions this path may read,\n// how many of those the trust policy alone allows, and how many there are.\n//\n// Both rules withhold, so both are counted (#2707): the trust policy was here\n// from the start (#986) and the ignore rule was not counted at all, which had\n// the empty answer naming twice the history search would open. The trust-only\n// figure is kept because the reader has to be told which of the two emptied\n// their search.\nfunc reachableSessionCount(dir string) (reach, trusted, total int, ok bool) {\n\tmetas, err := index.AllMeta(dir)\n\tif err != nil {\n\t\treturn 0, 0, 0, false\n\t}\n\tpol := policy.Load()\n\tfor _, m := range metas {\n\t\tif !pol.Allows(policy.ActivationSearch, m.Project) {\n\t\t\tcontinue\n\t\t}\n\t\ttrusted++\n\t\tif !pol.Ignored(m.Path, m.Project) {\n\t\t\treach++\n\t\t}\n\t}\n\treturn reach, trusted, len(metas), true\n}\n\n// joinCapped lists at most n items and says how many it left out, so a refusal\n// stays one line on a machine with many tombstones.\nfunc joinCapped(items []string, n int) string {\n\tif len(items) <= n {\n\t\treturn strings.Join(items, \", \")\n\t}\n\treturn strings.Join(items[:n], \", \") + fmt.Sprintf(\", +%d more\", len(items)-n)\n}\n\n// forgetDigestMatcher decides which stored digests belong to what a forget just\n// took. A record written since #2324 names its own projects, which is exact; an\n// older one is recognised by the ids and project name inside its text, the same\n// weaker test the view page falls back to.\nfunc forgetDigestMatcher(o index.ForgetOptions, keys []string) func(usage.Snapshot) bool {\n\t// Both spellings: a listing renders `claude:abc` and a hook block quotes\n\t// the bare id, so a sweep that knew only one of them missed half the\n\t// records it was meant to take.\n\tids := make([]string, 0, 2*len(keys))\n\tfor _, k := range keys {\n\t\tif k == \"\" {\n\t\t\tcontinue\n\t\t}\n\t\tids = append(ids, k)\n\t\tif _, id, ok := strings.Cut(k, \":\"); ok && id != \"\" {\n\t\t\tids = append(ids, id)\n\t\t}\n\t}\n\treturn func(s usage.Snapshot) bool {\n\t\tif o.Project != \"\" {\n\t\t\tif slices.Contains(s.Projects, o.Project) {\n\t\t\t\treturn true\n\t\t\t}\n\t\t\tif len(s.Projects) == 0 && digestNames(s.Digest, o.Project) {\n\t\t\t\treturn true\n\t\t\t}\n\t\t}\n\t\tfor _, id := range ids {\n\t\t\tif digestNames(s.Digest, id) {\n\t\t\t\treturn true\n\t\t\t}\n\t\t}\n\t\treturn false\n\t}\n}\n\n// digestNames reports whether a digest names a project or a session where it\n// renders one, rather than anywhere in its text. Searching the whole text made\n// `forget --project api` delete a digest about work/web whose prose read \"a\n// late api call\": the reader forgot one project and lost another's record\n// (#2330). The two shapes deja writes are the recall listing,\n//\n//  1. [claude] work/app · claude:abc · 2 matches\n//\n// and the hook block,\n//\n//   - **work/app** `abc` · 2026-08-28\n//\n// A digest in neither shape names nothing, so a sweep keeps it: with `projects`\n// recorded since #2324 the guess is only needed for older records, and deleting\n// one on a guess cannot be undone.\nfunc digestNames(digest, want string) bool {\n\tif want == \"\" {\n\t\treturn false\n\t}\n\tfor line := range strings.SplitSeq(digest, \"\\n\") {\n\t\tif slices.Contains(digestNamedFields(line), want) {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\n// digestNamedFields pulls the project and id positions out of one rendered\n// line: the fields that follow the harness in brackets, and anything a hook\n// block emphasises or quotes.\nfunc digestNamedFields(line string) []string {\n\tvar out []string\n\tif _, after, ok := strings.Cut(line, \"] \"); ok {\n\t\tfor field := range strings.SplitSeq(after, \" · \") {\n\t\t\tout = append(out, strings.TrimSpace(field))\n\t\t}\n\t}\n\tout = append(out, betweenAll(line, \"**\")...)\n\tout = append(out, betweenAll(line, \"`\")...)\n\treturn out\n}\n\n// betweenAll returns every substring wrapped by the given marker.\nfunc betweenAll(s, marker string) []string {\n\tvar out []string\n\tfor {\n\t\ti := strings.Index(s, marker)\n\t\tif i < 0 {\n\t\t\treturn out\n\t\t}\n\t\trest := s[i+len(marker):]\n\t\tbefore, after, ok := strings.Cut(rest, marker)\n\t\tif !ok {\n\t\t\treturn out\n\t\t}\n\t\tout = append(out, strings.TrimSpace(before))\n\t\ts = after\n\t}\n}\n\n// flagName is the flag without its value, so `--limit=3` and `--limit 3` are\n// recognised as the same spelling.\nfunc flagName(a string) string {\n\tif before, _, ok := strings.Cut(a, \"=\"); ok {\n\t\treturn before\n\t}\n\treturn a\n}\n\n// capTierHits bounds the two tiers that build their own hits — the ranked\n// relevance list and the error signature — which never went through the cap in\n// RunDetailed: `--limit 3` printed the whole retrieval window of fifty\n// sessions there while the exact tier printed three (#3345). With no flag they\n// keep the window they have always served, which the JSON envelope's own test\n// pins; only what the reader asked for binds them.\nfunc capTierHits(hits []search.Hit, o search.Options) ([]search.Hit, bool) {\n\tif o.Limit == 0 {\n\t\treturn hits, false\n\t}\n\t// A limit the reader typed binds even beside --all, which is how the exact\n\t// tier has always read the pair: --all lifts the default, and the number\n\t// asked for is still the number wanted. Letting --all win here made the\n\t// same two flags mean opposite things depending on which tier answered\n\t// (review of #3345).\n\treturn search.CapHits(hits, o.Limit, false)\n}\n\n// newestFirstNote is the line above a date-ordered answer. The exact tiers\n// read the newest of the whole match, so the line says only the order; the\n// relevance and error tiers rank a window first, and the newest of that\n// window is not the newest of the match when it ran past it.\nfunc newestFirstNote(o search.Options, shown int, tierWindow bool, window int) string {\n\tswitch {\n\tcase tierWindow && window > 0:\n\t\treturn fmt.Sprintf(\"newest first among the %d closest of %s\", window, grouped(o.Total))\n\tcase o.Total > shown:\n\t\t// Under --limit the list is the top of the order, and \"all 5\n\t\t// matches\" sat under \"showing 5 of 40\".\n\t\treturn \"newest first\"\n\t}\n\treturn fmt.Sprintf(\"all %d matches, newest first\", shown)\n}\n"
